        ExprKind::If {
            condition,
            then_branch,
            else_branch,
        } => {
            if let Some(value) = check_expr(
                program,
                current,
                condition,
                variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            ) {
                if value.native_unit {
                    reject_native_unit_value(program, condition, &value, diagnostics);
                } else if value.ty != Type::Bool {
                    diagnostics.push(error(
                        program,
                        "SPX-T210",
                        "`if` condition must be bool",
                        condition.span,
                    ));
                }
            }
            let original_names = variables.keys().cloned().collect::<Vec<_>>();
            let mut then_variables = variables.clone();
            let mut else_variables = variables.clone();
            let then_value = check_expr(
                program,
                current,
                then_branch,
                &mut then_variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            );
            let else_value = check_expr(
                program,
                current,
                else_branch,
                &mut else_variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            );
            let then_exits=then_value.as_ref().is_some_and(|value|value.ty==Type::Never) && crate::ast::returns_only(then_branch);
            let else_exits=else_value.as_ref().is_some_and(|value|value.ty==Type::Never) && crate::ast::returns_only(else_branch);
            for name in &original_names {
                if let Some(binding) = variables.get_mut(name) {
                    if then_exits!=else_exits {
                        if let Some(state)=(if then_exits {&else_variables}else{&then_variables}).get(name) {*binding=state.clone();} continue;
                    }
                    let then_state = then_variables
                        .get(name)
                        .map_or(Availability::Available, |value| value.availability);
                    let else_state = else_variables
                        .get(name)
                        .map_or(Availability::Available, |value| value.availability);
                    binding.availability = then_state.join(else_state);
                    if let (Some(then_binding), Some(else_binding)) =
                        (then_variables.get(name), else_variables.get(name))
                    {
                        binding.active_loans = then_binding
                            .active_loans
                            .union(&else_binding.active_loans)
                            .cloned()
                            .collect();
                        binding.moved_places = join_moved_places(then_binding, else_binding);
                        binding.definitely_partial =
                            join_definitely_partial(then_binding, else_binding);
                    }
                }
            }
            match (then_value, else_value) {
                (Some(left),Some(right)) if left.ty==Type::Never=>Some(right),
                (Some(left),Some(right)) if right.ty==Type::Never=>Some(left),
                (Some(then_value), Some(else_value)) => {
                    if then_value.native_unit || else_value.native_unit {
                        reject_native_unit_value(
                            program,
                            then_branch,
                            &then_value,
                            diagnostics,
                        );
                        reject_native_unit_value(
                            program,
                            else_branch,
                            &else_value,
                            diagnostics,
                        );
                    } else if then_value.ty != else_value.ty {
                        diagnostics.push(error(
                            program,
                            "SPX-T211",
                            format!(
                                "`if` branches return different types: {} and {}",
                                then_value.ty, else_value.ty
                            ),
                            expr.span,
                        ));
                    }
                    if types.needs_drop(&then_value.ty) && then_value.mode != else_value.mode
                    {
                        diagnostics.push(error(
                            program,
                            "SPX-O106",
                            "`if` branches must produce the same resource ownership mode",
                            expr.span,
                        ));
                    }
                    Some(then_value)
                }
                _ => None,
            }
        }
    }
}

//! Function-level checks: declaration admission, generic call cycles, and the
//! per-function body, contract, and effect checks.
use crate::ast::program_source::ProgramSource;
use crate::ast::{
    Expr, ExprKind, Function, ImportDeclaration, InterfaceDeclaration, MatchPattern, ParamMode,
    RecordMatchFieldPattern, Statement, Type,
};
use crate::diagnostic::Diagnostic;
use crate::source_verify::binding::{Availability, Binding};
use crate::source_verify::declared_type::{
    check_declared_type, check_ownership_mode, function_reaches, function_reaches_any,
    generic_function_arguments_are_forwarded, generic_function_contains_nested_owned_record_slot,
    generic_function_expression_is_direct_scalar,
    generic_function_expression_is_owned_record_composition,
    generic_function_has_owned_record_composition, generic_function_owned_record_slot,
    generic_function_signature_slot, owned_record_function_substitutions,
    scalar_function_substitutions,
};
use crate::source_verify::declared_type::{declared_collection::reject_function, generic_result};
use crate::source_verify::diagnostics::{
    error, invalid_stable_id, reject_native_unit_value, reject_reserved_host_id, require_bool,
    source_identifier,
};
use crate::source_verify::iterative::check_expr_with_helpers;
use crate::source_verify::type_table::TypeTable;
use std::collections::{BTreeSet, HashMap, HashSet};
pub(in crate::source_verify::declaration) fn check_function_declarations<'p>(
    program: &'p dyn ProgramSource,
    functions: &mut HashMap<&'p str, &'p Function>,
    ids: &mut HashSet<&'p str>,
    diagnostics: &mut Vec<Diagnostic>,
) {
    for function in program.functions() {
        if !source_identifier(&function.name) {
            diagnostics.push(error(
                program,
                "SPX-S104",
                format!("`{}` is not a valid function identifier", function.name),
                function.name_span,
            ));
        }
        if function.name == crate::literal_format::NAME
            || crate::string_ops::by_name(&function.name).is_some()
            || crate::map_ops::by_name(&function.name).is_some()
        {
            diagnostics.push(error(
                program,
                "SPX-S113",
                format!(
                    "function name `{}` is reserved by the compiler-owned string operations",
                    function.name
                ),
                function.name_span,
            ));
        }
        if crate::str_ops::by_name(&function.name).is_some() {
            diagnostics.push(error(
                program,
                "SPX-S113",
                format!(
                    "function name `{}` is reserved by the compiler-owned borrowed string operations",
                    function.name
                ),
                function.name_span,
            ));
        }
        if crate::byte_ops::by_name(&function.name).is_some() {
            diagnostics.push(error(
                program,
                "SPX-S113",
                format!(
                    "function name `{}` is reserved by the compiler-owned byte operations",
                    function.name
                ),
                function.name_span,
            ));
        }
        if crate::source_verify::vec_field::reserved_function(function) {
            diagnostics.push(error(
                program,
                "SPX-S113",
                format!(
                    "function name `{}` is reserved by the compiler-owned vector operations",
                    function.name
                ),
                function.name_span,
            ));
        }
        if crate::box_ops::by_name(&function.name).is_some()
            || crate::iterator_ops::by_name(&function.name).is_some()
            || crate::list_ops::by_name(&function.name).is_some()
        {
            diagnostics.push(error(
                program,
                "SPX-S113",
                format!(
                    "function name `{}` is reserved by the compiler-owned box operations",
                    function.name
                ),
                function.name_span,
            ));
        }
        if crate::host_io_ops::by_name(&function.name).is_some() {
            diagnostics.push(error(
                program,
                "SPX-S113",
                format!(
                    "function name `{}` is reserved by the compiler-owned host I/O operations",
                    function.name
                ),
                function.name_span,
            ));
        }
        if crate::command_io_ops::by_name(&function.name).is_some()
            || crate::stdin_stream_ops::pure_by_name(&function.name).is_some()
        {
            diagnostics.push(error(
                program,
                "SPX-S113",
                format!(
                    "function name `{}` is reserved by the compiler-owned command I/O operations",
                    function.name
                ),
                function.name_span,
            ));
        }
        reject_reserved_host_id(
            program,
            &function.stable_id,
            "function",
            function.span,
            diagnostics,
        );
        if functions.insert(function.name.as_str(), function).is_some() {
            diagnostics.push(error(
                program,
                "SPX-S101",
                format!("duplicate function `{}`", function.name),
                function.name_span,
            ));
        }
        if function.stable_id.is_empty() {
            diagnostics.push(
                error(
                    program,
                    "SPX-S102",
                    format!("function `{}` has an empty stable id", function.name),
                    function.name_span,
                )
                .with_help("give the declaration a dotted stable identity with @id(\"your.namespace.symbol\")"),
            );
        } else if function.stable_id.contains('\0') {
            diagnostics.push(invalid_stable_id(
                program,
                "SPX-S102",
                format!("function `{}`", function.name),
                function.span,
            ));
        } else if function
            .stable_id
            .starts_with("semaprax.function-execution.v1:")
        {
            diagnostics.push(error(
                program,
                "SPX-T225",
                format!(
                    "function `{}` uses the reserved generic execution identity domain",
                    function.name
                ),
                function.span,
            ));
        } else if !ids.insert(function.stable_id.as_str()) {
            diagnostics.push(error(
                program,
                "SPX-S102",
                format!("duplicate stable id `{}`", function.stable_id),
                function.span,
            ));
        }
        if !function.explicit_id {
            diagnostics.push(
                Diagnostic::warning(
                    "SPX-S103",
                    format!(
                        "function `{}` has an automatic identity that changes when renamed",
                        function.name
                    ),
                    function.name_span,
                )
                .at_path(program.path())
                .with_help("add @id(\"your.namespace.symbol\") before the declaration"),
            );
        }
        if crate::vec_ops::wrapper_by_id(&function.stable_id).is_some()
            && !crate::vec_ops::source_module_is_authenticated(program)
        {
            diagnostics.push(error(
                program,
                "SPX-T283",
                format!(
                    "vector wrapper identity `{}` is reserved for module `{}`",
                    function.stable_id,
                    crate::vec_ops::MODULE
                ),
                function.span,
            ));
            continue;
        }
        if crate::box_ops::wrapper_by_id(&function.stable_id).is_some()
            && !crate::box_ops::source_module_is_authenticated(program)
        {
            diagnostics.push(error(
                program,
                "SPX-T286",
                format!(
                    "box wrapper identity `{}` is reserved for module `{}`",
                    function.stable_id,
                    crate::box_ops::MODULE
                ),
                function.span,
            ));
            continue;
        }
        if crate::box_ops::wrapper_by_id(&function.stable_id).is_some()
            && crate::box_ops::source_wrapper(program, function).is_none()
        {
            diagnostics.push(error(
                program,
                "SPX-T286",
                format!(
                    "`{}.{}` must be one exact transparent compiler-owned box wrapper",
                    program.module(),
                    function.name
                ),
                function.span,
            ));
            continue;
        }
        if crate::vec_ops::wrapper_by_id(&function.stable_id).is_some()
            && crate::vec_ops::source_wrapper(program, function).is_none()
        {
            diagnostics.push(error(
                program,
                "SPX-T283",
                format!(
                    "`{}.{}` must be one exact transparent compiler-owned vector wrapper",
                    program.module(),
                    function.name
                ),
                function.span,
            ));
            continue;
        }
        if !function.type_parameters.is_empty() {
            let transparent_vec_wrapper = crate::vec_ops::source_wrapper(program, function);
            let transparent_box_wrapper = crate::box_ops::source_wrapper(program, function);
            if crate::vec_ops::is_source_candidate(program, function)
                && transparent_vec_wrapper.is_none()
            {
                diagnostics.push(error(
                    program,
                    "SPX-T283",
                    format!(
                        "`{}.{}` must be one exact transparent compiler-owned vector wrapper",
                        program.module(),
                        function.name
                    ),
                    function.span,
                ));
                continue;
            }
            if transparent_vec_wrapper.is_some() {
                continue;
            }
            if crate::box_ops::is_source_candidate(program, function)
                && transparent_box_wrapper.is_none()
            {
                diagnostics.push(error(
                    program,
                    "SPX-T286",
                    format!(
                        "`{}.{}` must be one exact transparent compiler-owned box wrapper",
                        program.module(),
                        function.name
                    ),
                    function.span,
                ));
                continue;
            }
            if transparent_box_wrapper.is_some() {
                continue;
            }
            if !(1..=2).contains(&function.type_parameters.len()) {
                diagnostics.push(error(
                    program,
                    "SPX-T224",
                    format!(
                        "generic function `{}` requires one or two type parameters",
                        function.name
                    ),
                    function.span,
                ));
            }
            let mut parameter_names = HashSet::new();
            for parameter in &function.type_parameters {
                if !source_identifier(&parameter.name)
                    || !parameter_names.insert(parameter.name.as_str())
                {
                    diagnostics.push(error(
                        program,
                        "SPX-T224",
                        format!(
                            "invalid or duplicate type parameter `{}` on function `{}`",
                            parameter.name, function.name
                        ),
                        parameter.span,
                    ));
                }
            }
            if !function.effects.is_empty() {
                diagnostics.push(error(
                    program,
                    "SPX-T226",
                    format!(
                        "generic function `{}` must be effect-free in this slice",
                        function.name
                    ),
                    function.span,
                ));
            }
            let variant = crate::source_verify::declared_type::generic_variant::profile(
                function,
                &TypeTable::new_owned_reference(program),
            );
            let owned_result = generic_result::profile(function);
            let collection =
                crate::source_verify::declared_type::generic_collection::profile(function);
            for param in &function.params {
                let owned_record = generic_function_owned_record_slot(
                    function,
                    &param.ty,
                    &TypeTable::new_owned_reference(program),
                );
                if !((param.mode == ParamMode::Value
                    && (generic_function_signature_slot(&param.ty, &parameter_names)
                        || (collection
                            && crate::source_verify::declared_type::generic_collection::callback(
                                function, &param.ty,
                            ))
                        || ((collection || variant)
                            && crate::vec_ops::ast_element_is_admitted(&param.ty))))
                    || (param.mode == ParamMode::Own
                        && (owned_record
                            || (variant
                                && crate::source_verify::declared_type::generic_variant::slot(
                                    function,
                                    &param.ty,
                                    &TypeTable::new_owned_reference(program),
                                ))
                            || (collection
                                && crate::source_verify::declared_type::generic_collection::slot(
                                    function, &param.ty,
                                ))
                            || (owned_result && generic_result::slot(function, &param.ty)))))
                {
                    diagnostics.push(error(
                        program,
                        "SPX-T224",
                        format!(
                            "generic function `{}.{}` must use the direct-scalar profile by value or one admitted flat owned-record template by ownership",
                            function.name, param.name
                        ),
                        param.span,
                    ));
                }
            }
            if !owned_result
                && !variant
                && !collection
                && !generic_function_signature_slot(&function.return_type, &parameter_names)
                && !generic_function_owned_record_slot(
                    function,
                    &function.return_type,
                    &TypeTable::new_owned_reference(program),
                )
            {
                diagnostics.push(error(
                    program,
                    "SPX-T224",
                    format!(
                        "generic function `{}` must return the direct-scalar profile or one admitted flat owned-record template",
                        function.name
                    ),
                    function.span,
                ));
            }
            if generic_function_contains_nested_owned_record_slot(
                function,
                &TypeTable::new_owned_reference(program),
            ) && !generic_function_has_owned_record_composition(
                function,
                &TypeTable::new_owned_reference(program),
            ) {
                diagnostics.push(error(
                    program,
                    "SPX-T224",
                    format!(
                        "generic function `{}` must transfer exactly one bounded owned-record parameter into an identical result type",
                        function.name
                    ),
                    function.span,
                ));
            }
            if let Err(diagnostic) =
                crate::source_verify::closure::validate_generic_syntax(program, function)
            {
                diagnostics.push(diagnostic);
            }
            let types = TypeTable::new_owned_reference(program);
            let invalid_contract = function
                .requires
                .iter()
                .chain(&function.ensures)
                .any(|expression| !generic_function_expression_is_direct_scalar(expression));
            let invalid_body = !crate::source_verify::declared_type::generic_variant::body(
                function,
                &types,
                &function.body,
            ) && !generic_result::body(function, &function.body)
                && !generic_function_expression_is_direct_scalar(&function.body)
                && !generic_function_expression_is_owned_record_composition(
                    function,
                    &types,
                    &function.body,
                );
            let invalid_body = invalid_body && !(crate::source_verify::generic_collection_profile(function)
                && crate::source_verify::declared_type::generic_collection_expression_is_admitted(&function.body));
            if invalid_contract || invalid_body {
                diagnostics.push(error(
                    program,
                    "SPX-T226",
                    format!(
                        "generic function `{}` uses an expression outside the direct-scalar slice",
                        function.name
                    ),
                    function.span,
                ));
            }
        }
    }
}
pub(in crate::source_verify::declaration) fn check_generic_function_cycles<'p>(
    program: &'p dyn ProgramSource,
    call_graph: &HashMap<String, Vec<String>>,
    generic_functions: &HashSet<&'p str>,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let functions = program
        .functions()
        .iter()
        .map(|function| (function.name.as_str(), function))
        .collect::<HashMap<_, _>>();
    let types = TypeTable::new_owned_reference(program);
    for function in program
        .functions()
        .iter()
        .filter(|function| !function.type_parameters.is_empty())
    {
        let mut bindings = function
            .params
            .iter()
            .map(|parameter| (parameter.name.clone(), static_binding(parameter.ty.clone())))
            .collect::<HashMap<_, _>>();
        for expression in function
            .requires
            .iter()
            .chain(std::iter::once(&function.body))
            .chain(&function.ensures)
        {
            check_omitted_generic_mappings(
                program,
                function,
                expression,
                &mut bindings,
                &functions,
                &types,
                diagnostics,
                0,
            );
            expression.visit_call_instances(&mut |callee, arguments, span| {
                if let Some(target) = program.functions().iter().find(|target| {
                    target.name == callee && !target.type_parameters.is_empty()
                }) {
                    if arguments.is_empty() {
                        return;
                    }
                    if !generic_function_arguments_are_forwarded(function, target, arguments) {
                        diagnostics.push(error(
                            program,
                            "SPX-T225",
                            format!(
                                "generic function `{}` must supply admitted explicit type-argument mappings when calling generic function `{callee}`",
                                function.name
                            ),
                            span,
                        ));
                    }
                }
            });
        }
        let participates_in_cycle = call_graph.get(&function.name).is_some_and(|callees| {
            callees.iter().any(|callee| {
                function_reaches(call_graph, callee, &function.name, &mut HashSet::new())
            })
        });
        if participates_in_cycle {
            diagnostics.push(error(
                program,
                "SPX-T226",
                format!(
                    "generic function `{}` participates in a recursive call cycle",
                    function.name
                ),
                function.span,
            ));
        }
        let direct_generic_call = call_graph.get(&function.name).is_some_and(|callees| {
            callees
                .iter()
                .any(|callee| generic_functions.contains(callee.as_str()))
        });
        let reaches_other_generic = call_graph.get(&function.name).is_some_and(|callees| {
            callees.iter().any(|callee| {
                function_reaches_any(call_graph, callee, generic_functions, &mut HashSet::new())
            })
        });
        if reaches_other_generic && !direct_generic_call && !participates_in_cycle {
            diagnostics.push(error(
                program,
                "SPX-T226",
                format!(
                    "generic function `{}` transitively reaches another generic function",
                    function.name
                ),
                function.span,
            ));
        }
    }
}
use super::traversal_scope::static_binding;
const MAX_STATIC_MAPPING_DEPTH: usize = 128;
/// Carries the lexical scope, declaration table, and bounded traversal state
/// required to authenticate an omitted symbolic mapping before body checking.
#[allow(clippy::too_many_arguments)]
fn check_omitted_generic_mappings(
    program: &dyn ProgramSource,
    current: &Function,
    expression: &Expr,
    bindings: &mut HashMap<String, Binding>,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    diagnostics: &mut Vec<Diagnostic>,
    depth: usize,
) {
    if depth >= MAX_STATIC_MAPPING_DEPTH {
        expression.visit_call_instances(&mut |callee, arguments, span| {
            if arguments.is_empty()
                && functions
                    .get(callee)
                    .is_some_and(|target| !target.type_parameters.is_empty())
            {
                diagnostics.push(error(
                    program,
                    "SPX-T225",
                    format!(
                        "generic function `{}` has an omitted type-argument mapping beyond the bounded static traversal",
                        current.name
                    ),
                    span,
                ));
            }
        });
        return;
    }
    let next = depth + 1;
    match &expression.kind {
        ExprKind::LexicalExit { value: None, .. } => {}
        ExprKind::Closure { .. } => {}
        ExprKind::Call {
            name,
            type_arguments,
            args,
        } => {
            for argument in args {
                check_omitted_generic_mappings(
                    program,
                    current,
                    argument,
                    bindings,
                    functions,
                    types,
                    diagnostics,
                    next,
                );
            }
            let Some(target) = functions.get(name.as_str()) else {
                return;
            };
            if target.type_parameters.is_empty() || !type_arguments.is_empty() {
                return;
            }
            let inferred = crate::source_verify::generic_inference::arguments(
                program, current, target, args, bindings, functions, types,
            );
            if !inferred.as_ref().is_some_and(|arguments| {
                generic_function_arguments_are_forwarded(current, target, arguments)
            }) {
                diagnostics.push(error(
                    program,
                    "SPX-T225",
                    format!(
                        "generic function `{}` must supply admitted explicit type-argument mappings when calling generic function `{name}`",
                        current.name
                    ),
                    expression.span,
                ));
            }
        }
        ExprKind::Block { statements, tail } => {
            let mut scope = bindings.clone();
            for statement in statements {
                match statement {
                    Statement::Let {
                        name,
                        declared,
                        value,
                        ..
                    } => {
                        check_omitted_generic_mappings(
                            program,
                            current,
                            value,
                            &mut scope,
                            functions,
                            types,
                            diagnostics,
                            next,
                        );
                        let ty = declared.clone().or_else(|| {
                            crate::source_verify::generic_inference::expression_type(
                                program, current, value, &scope, functions, types,
                            )
                        });
                        scope.remove(name);
                        if let Some(ty) = ty {
                            scope.insert(name.clone(), static_binding(ty));
                        }
                    }
                    Statement::Assign { value, .. } => check_omitted_generic_mappings(
                        program,
                        current,
                        value,
                        &mut scope,
                        functions,
                        types,
                        diagnostics,
                        next,
                    ),
                    Statement::Unsafe { body, .. } => check_omitted_generic_mappings(
                        program,
                        current,
                        body,
                        &mut scope,
                        functions,
                        types,
                        diagnostics,
                        next,
                    ),
                    Statement::While {
                        condition, body, ..
                    } => {
                        check_omitted_generic_mappings(
                            program,
                            current,
                            condition,
                            &mut scope,
                            functions,
                            types,
                            diagnostics,
                            next,
                        );
                        check_omitted_generic_mappings(
                            program,
                            current,
                            body,
                            &mut scope,
                            functions,
                            types,
                            diagnostics,
                            next,
                        );
                    }
                    Statement::For {
                        item, values, body, ..
                    }
                    | Statement::ForBorrow {
                        item, values, body, ..
                    }
                    | Statement::ForOwn {
                        item, values, body, ..
                    } => {
                        check_omitted_generic_mappings(
                            program,
                            current,
                            values,
                            &mut scope,
                            functions,
                            types,
                            diagnostics,
                            next,
                        );
                        let mut body_scope = scope.clone();
                        body_scope.remove(item);
                        if let Statement::ForBorrow {
                            index: Some(index), ..
                        } = statement
                        {
                            body_scope.remove(&index.name);
                        }
                        check_omitted_generic_mappings(
                            program,
                            current,
                            body,
                            &mut body_scope,
                            functions,
                            types,
                            diagnostics,
                            next,
                        );
                    }
                }
            }
            check_omitted_generic_mappings(
                program,
                current,
                tail,
                &mut scope,
                functions,
                types,
                diagnostics,
                next,
            );
        }
        ExprKind::LexicalExit {
            value: Some(value), ..
        }
        | ExprKind::VecConstructor { value, .. }
        | ExprKind::Unary { value, .. }
        | ExprKind::Try { operand: value }
        | ExprKind::Yield { request: value }
        | ExprKind::Project { base: value, .. } => check_omitted_generic_mappings(
            program,
            current,
            value,
            bindings,
            functions,
            types,
            diagnostics,
            next,
        ),
        ExprKind::Binary { left, right, .. } => {
            for child in [left.as_ref(), right.as_ref()] {
                check_omitted_generic_mappings(
                    program,
                    current,
                    child,
                    bindings,
                    functions,
                    types,
                    diagnostics,
                    next,
                );
            }
        }
        ExprKind::If {
            condition,
            then_branch,
            else_branch,
        } => {
            for child in [
                condition.as_ref(),
                then_branch.as_ref(),
                else_branch.as_ref(),
            ] {
                check_omitted_generic_mappings(
                    program,
                    current,
                    child,
                    bindings,
                    functions,
                    types,
                    diagnostics,
                    next,
                );
            }
        }
        ExprKind::ConstructRecord { fields, .. } | ExprKind::ConstructVariant { fields, .. } => {
            for field in fields {
                check_omitted_generic_mappings(
                    program,
                    current,
                    &field.value,
                    bindings,
                    functions,
                    types,
                    diagnostics,
                    next,
                );
            }
        }
        ExprKind::UpdateRecord { base, fields } => {
            check_omitted_generic_mappings(
                program,
                current,
                base,
                bindings,
                functions,
                types,
                diagnostics,
                next,
            );
            for field in fields {
                check_omitted_generic_mappings(
                    program,
                    current,
                    &field.value,
                    bindings,
                    functions,
                    types,
                    diagnostics,
                    next,
                );
            }
        }
        ExprKind::Match {
            scrutinee, arms, ..
        } => {
            check_omitted_generic_mappings(
                program,
                current,
                scrutinee,
                bindings,
                functions,
                types,
                diagnostics,
                next,
            );
            for arm in arms {
                let mut arm_scope = bindings.clone();
                clear_pattern_bindings(&arm.pattern, &mut arm_scope);
                if let Some(guard) = &arm.guard {
                    check_omitted_generic_mappings(
                        program,
                        current,
                        guard,
                        &mut arm_scope,
                        functions,
                        types,
                        diagnostics,
                        next,
                    );
                }
                check_omitted_generic_mappings(
                    program,
                    current,
                    &arm.value,
                    &mut arm_scope,
                    functions,
                    types,
                    diagnostics,
                    next,
                );
            }
        }
        ExprKind::MethodCall { receiver, args, .. } => {
            check_omitted_generic_mappings(
                program,
                current,
                receiver,
                bindings,
                functions,
                types,
                diagnostics,
                next,
            );
            for argument in args {
                check_omitted_generic_mappings(
                    program,
                    current,
                    argument,
                    bindings,
                    functions,
                    types,
                    diagnostics,
                    next,
                );
            }
        }
        ExprKind::SuperMethod { args, .. } => {
            for argument in args {
                check_omitted_generic_mappings(
                    program,
                    current,
                    argument,
                    bindings,
                    functions,
                    types,
                    diagnostics,
                    next,
                );
            }
        }
        ExprKind::Int(_)
        | ExprKind::Int32(_)
        | ExprKind::Uint8(_)
        | ExprKind::Usize(_)
        | ExprKind::Char(_)
        | ExprKind::Float32(_)
        | ExprKind::Float64(_)
        | ExprKind::Bool(_)
        | ExprKind::String(_)
        | ExprKind::BorrowedUtf8Literal(_)
        | ExprKind::ArrayU8(_)
        | ExprKind::RepeatArrayU8 { .. }
        | ExprKind::Var(_) => {}
    }
}
fn clear_pattern_bindings(pattern: &MatchPattern, bindings: &mut HashMap<String, Binding>) {
    match pattern {
        MatchPattern::Variant { fields, .. } => {
            for field in fields {
                bindings.remove(&field.binding);
            }
        }
        MatchPattern::Record { fields, .. } => {
            for field in fields {
                clear_record_pattern_bindings(&field.pattern, bindings);
            }
        }
        MatchPattern::Binding { name, .. } => {
            bindings.remove(name);
        }
        MatchPattern::Wildcard { .. } | MatchPattern::Literal { .. } | MatchPattern::Or { .. } => {}
    }
}
fn clear_record_pattern_bindings(
    pattern: &RecordMatchFieldPattern,
    bindings: &mut HashMap<String, Binding>,
) {
    match pattern {
        RecordMatchFieldPattern::Binding { name, .. } => {
            bindings.remove(name);
        }
        RecordMatchFieldPattern::Record { fields, .. } => {
            for field in fields {
                clear_record_pattern_bindings(&field.pattern, bindings);
            }
        }
        RecordMatchFieldPattern::Wildcard { .. } => {}
    }
}
pub(in crate::source_verify::declaration) fn check_function_bodies<'p>(
    program: &'p dyn ProgramSource,
    functions: &HashMap<&'p str, &'p Function>,
    import_keys: &HashMap<&'p str, (&'p InterfaceDeclaration, &'p ImportDeclaration)>,
    types: &TypeTable<'p>,
    diagnostics: &mut Vec<Diagnostic>,
    fused_producer: Option<&'p Expr>,
) {
    let byte_helpers = crate::loop_calls::byte_writer::SourceIndex::new(program);
    let function_value_targets =
        crate::source_verify::function_value_inventory::function_value_targets(program, functions);
    for template in program.functions() {
        reject_function(program, template, types, diagnostics);
        let type_parameters = template
            .type_parameters
            .iter()
            .map(|parameter| parameter.name.as_str())
            .collect::<HashSet<_>>();
        check_declared_type(
            program,
            &template.return_type,
            template.span,
            types,
            &type_parameters,
            diagnostics,
        );
        for param in &template.params {
            check_declared_type(
                program,
                &param.ty,
                param.span,
                types,
                &type_parameters,
                diagnostics,
            );
        }
        if !template.type_parameters.is_empty()
            && !crate::source_verify::declared_type::generic_collection::profile(template)
            && (template
                .params
                .iter()
                .any(|parameter| matches!(parameter.ty, Type::Function { .. }))
                || matches!(template.return_type, Type::Function { .. }))
        {
            diagnostics.push(error(
                program,
                "SPX-T287",
                "generic function signatures cannot contain function values",
                template.span,
            ));
        }
        let generic_parameter_list_is_valid = (1..=2).contains(&template.type_parameters.len())
            && template
                .type_parameters
                .iter()
                .all(|parameter| source_identifier(&parameter.name))
            && template
                .type_parameters
                .iter()
                .map(|parameter| parameter.name.as_str())
                .collect::<HashSet<_>>()
                .len()
                == template.type_parameters.len();
        let transparent_vec_wrapper = crate::vec_ops::source_wrapper(program, template);
        let transparent_box_wrapper = crate::box_ops::source_wrapper(program, template);
        let specializations: std::borrow::Cow<'_, [Function]> = if template
            .type_parameters
            .is_empty()
            || transparent_vec_wrapper.is_some()
            || transparent_box_wrapper.is_some()
        {
            std::borrow::Cow::Borrowed(std::slice::from_ref(template))
        } else if generic_parameter_list_is_valid {
            // These clones exist only to validate every admitted direct-scalar
            // substitution. Executable HIR instances are discovered separately
            // from reachable explicit calls and never originate here.
            let owned_record = template
                .params
                .iter()
                .any(|param| generic_function_owned_record_slot(template, &param.ty, types))
                || generic_function_owned_record_slot(template, &template.return_type, types);
            let substitutions = if generic_result::profile(template) {
                generic_result::substitutions(template)
            } else if owned_record
                || crate::source_verify::declared_type::generic_variant::profile(template, types)
                || crate::source_verify::declared_type::generic_collection::profile(template)
            {
                owned_record_function_substitutions(template.type_parameters.len())
            } else {
                scalar_function_substitutions(template.type_parameters.len())
            };
            std::borrow::Cow::Owned(
                substitutions
                    .iter()
                    .filter_map(|arguments| {
                        crate::source_verify::closure::specialize_checked(
                            program,
                            template,
                            arguments,
                            diagnostics,
                        )
                    })
                    .collect(),
            )
        } else {
            std::borrow::Cow::Owned(Vec::new())
        };
        let mut specialized_diagnostics = HashSet::new();
        for function in specializations.iter() {
            let specialized_diagnostic_start = diagnostics.len();
            let mut variables = HashMap::new();
            if function.return_type == Type::Str {
                diagnostics.push(error(
                    program,
                    "SPX-O116",
                    format!(
                        "function `{}` cannot return borrowed `str`; borrowed text is confined to the invocation",
                        function.name
                    ),
                    function.span,
                ).with_help("return an owned `string` instead: a literal, `string_concat`, or `string_from_i64` result is owned"));
            }
            crate::source_verify::declared_type::string_record::reject(
                program,
                &function.return_type,
                "returned",
                function.span,
                types,
                diagnostics,
            );
            if function.return_type == Type::SliceU8 {
                diagnostics.push(error(
                    program,
                    "SPX-T264",
                    format!(
                        "function `{}` cannot return borrowed `Slice<u8>`; byte views cannot escape their invocation",
                        function.name
                    ),
                    function.span,
                ));
            }
            for param in &function.params {
                if !source_identifier(&param.name) {
                    diagnostics.push(error(
                        program,
                        "SPX-S105",
                        format!("`{}` is not a valid parameter identifier", param.name),
                        param.span,
                    ));
                }
                if transparent_vec_wrapper.is_none() && transparent_box_wrapper.is_none() {
                    check_ownership_mode(program, function, param, types, diagnostics);
                }
                // By-value `string` parameters carry unique ownership. Bytes
                // use explicit `own Bytes`, but the shared predicate keeps
                // this source-side binding rule identical to resolved HIR.
                let binding_mode = if param.mode == ParamMode::Value && param.ty.is_uniquely_owned()
                {
                    ParamMode::Own
                } else {
                    param.mode
                };
                if variables
                    .insert(
                        param.name.clone(),
                        Binding {
                            contract_local: false,
                            traversal_row: None,
                            ty: param.ty.clone(),
                            mode: binding_mode,
                            availability: Availability::Available,
                            moved_places: HashMap::new(),
                            definitely_partial: HashSet::new(),
                            native_unit_discard: false,
                            mutable: false,
                            active_loans: BTreeSet::new(),
                            borrow_origin: None,
                        },
                    )
                    .is_some()
                {
                    diagnostics.push(error(
                        program,
                        "SPX-T102",
                        format!("duplicate parameter `{}`", param.name),
                        param.span,
                    ));
                }
            }

            let entry_variables = variables.clone();
            for contract in &function.requires {
                contract.visit_calls(&mut |callee, span| {
                    if crate::host_io_ops::by_name(callee).is_some() {
                        diagnostics.push(error(
                            program,
                            "SPX-T269",
                            "stdout_write is not admitted in contracts",
                            span,
                        ));
                    }
                    if crate::command_io_ops::by_name(callee).is_some() {
                        diagnostics.push(error(
                            program,
                            "SPX-T270",
                            "command I/O operations are not admitted in contracts",
                            span,
                        ));
                    }
                });
                require_bool(
                    program,
                    function,
                    contract,
                    &entry_variables,
                    functions,
                    types,
                    None,
                    diagnostics,
                    "precondition",
                );
            }

            if let Some(actual) = check_expr_with_helpers(
                program,
                function,
                &function.body,
                &mut variables,
                functions,
                types,
                None,
                true,
                diagnostics,
                Some(&byte_helpers),
                fused_producer,
            ) {
                if actual.native_unit {
                    reject_native_unit_value(program, &function.body, &actual, diagnostics);
                }
                if !actual.native_unit
                    && actual.ty != Type::Never
                    && actual.ty != function.return_type
                {
                    diagnostics.push(error(
                        program,
                        "SPX-T103",
                        format!(
                            "function `{}` returns {}, but its signature declares {}",
                            function.name,
                            crate::source_verify::private_names::type_name(
                                program, types, &actual.ty
                            ),
                            crate::source_verify::private_names::type_name(
                                program,
                                types,
                                &function.return_type
                            )
                        ),
                        function.body.span,
                    ));
                }
                if actual.ty != Type::Never
                    && types.needs_drop(&function.return_type)
                    && actual.mode != ParamMode::Own
                {
                    diagnostics.push(
                        error(
                            program,
                            "SPX-O104",
                            format!(
                                "function `{}` cannot return a {} resource as owned",
                                function.name,
                                actual.mode.text()
                            ),
                            function.body.span,
                        )
                        .with_help(
                            "return an owned resource or declare a future lifetime-bound view",
                        ),
                    );
                }
            }

            for contract in &function.ensures {
                contract.visit_calls(&mut |callee, span| {
                    if crate::host_io_ops::by_name(callee).is_some() {
                        diagnostics.push(error(
                            program,
                            "SPX-T269",
                            "stdout_write is not admitted in contracts",
                            span,
                        ));
                    }
                    if crate::command_io_ops::by_name(callee).is_some() {
                        diagnostics.push(error(
                            program,
                            "SPX-T270",
                            "command I/O operations are not admitted in contracts",
                            span,
                        ));
                    }
                });
                require_bool(
                    program,
                    function,
                    contract,
                    &variables,
                    functions,
                    types,
                    Some(&function.return_type),
                    diagnostics,
                    "postcondition",
                );
            }

            let declared: HashSet<_> = function.effects.iter().map(String::as_str).collect();
            let mut required_lifecycle_effects = BTreeSet::new();
            for param in &function.params {
                if param.mode == ParamMode::Own {
                    required_lifecycle_effects
                        .extend(types.lifecycle_effects(&param.ty, import_keys));
                }
            }
            required_lifecycle_effects
                .extend(types.lifecycle_effects(&function.return_type, import_keys));
            for callee in crate::source_verify::function_value_inventory::calls(
                function,
                functions,
                &function_value_targets,
            ) {
                if let Some(target) = functions.get(callee.as_str()) {
                    required_lifecycle_effects
                        .extend(types.lifecycle_effects(&target.return_type, import_keys));
                }
            }
            for effect in required_lifecycle_effects {
                if !declared.contains(effect.as_str()) {
                    diagnostics.push(
                    error(
                        program,
                        "SPX-E103",
                        format!(
                            "function `{}` can own a resource; automatic finalization requires effect `{effect}`",
                            function.name
                        ),
                        function.span,
                    )
                    .with_help(format!(
                        "add `{effect}` to the function's `uses` set and module permits"
                    )),
                );
                }
            }
            for effect in &function.effects {
                if !program.permits().iter().any(|permit| permit == effect) {
                    diagnostics.push(crate::source_verify::hints::unpermitted_effect(
                        program, function, effect,
                    ));
                }
            }
            for callee in crate::source_verify::function_value_inventory::calls(
                function,
                functions,
                &function_value_targets,
            ) {
                let span = function.body.span;
                if let Some(effect) = crate::string_ops::by_name(&callee)
                    .and_then(crate::string_ops::StringOp::effect)
                {
                    if !declared.contains(effect) {
                        diagnostics.push(crate::source_verify::hints::missing_effect(
                            program, &callee, effect, function, span,
                        ));
                    }
                    continue;
                }
                if let Some(op) = crate::host_io_ops::by_name(&callee) {
                    if !declared.contains(op.effect()) {
                        diagnostics.push(crate::source_verify::hints::missing_effect(
                            program,
                            &callee,
                            op.effect(),
                            function,
                            span,
                        ));
                    }
                    continue;
                }
                if let Some(op) = crate::command_io_ops::by_name(&callee) {
                    for effect in crate::command_io_ops::required_effects(op) {
                        if !declared.contains(effect) {
                            diagnostics.push(crate::source_verify::hints::missing_effect(
                                program, &callee, effect, function, span,
                            ));
                        }
                    }
                    continue;
                }
                if let Some(target) = functions.get(callee.as_str()) {
                    for effect in &target.effects {
                        if !declared.contains(effect.as_str()) {
                            diagnostics.push(crate::source_verify::hints::missing_effect(
                                program, &callee, effect, function, span,
                            ));
                        }
                    }
                }
            }
            if !template.type_parameters.is_empty() {
                let added = diagnostics
                    .drain(specialized_diagnostic_start..)
                    .collect::<Vec<_>>();
                for diagnostic in added {
                    if specialized_diagnostics.insert(diagnostic.json()) {
                        diagnostics.push(diagnostic);
                    }
                }
            }
        }
    }
    if let Some(error) = byte_helpers.failure() {
        diagnostics.push(error.at_path(program.path()));
    }
}

//! The `Enter` frame: the first visit to an expression, which either
//! produces a value directly or schedules the frames its operands need.

use crate::ast::{Expr, ExprKind, ImportResult, ParamMode, Statement, Type, TypeDeclarationKind};
use crate::diagnostic::Diagnostic;
use crate::source_verify::arguments::{
    activate_borrowed_bytes_call_loans, source_byte_view_place_is_admitted,
};
use crate::source_verify::binding::{Availability, CheckedValue};
use crate::source_verify::declared_type::{
    check_declared_type, function_value_signature, generic_function_arguments_are_admitted,
    generic_function_arguments_are_forwarded, validation_specialize_signature,
};
use crate::source_verify::diagnostics::{error, source_identifier};
use crate::source_verify::hints;
use crate::source_verify::place::{
    check_source_place_availability, overlapping_place_state, source_place,
};
use crate::source_verify::scope::{
    VerifierCallTarget, VerifierFrame, VerifierFunctionSignature, VerifierScope,
};
use crate::source_verify::type_table::effective_record_fields;
use crate::source_verify::IterativeVerifier;
use std::collections::HashSet;

impl<'a, 'p> IterativeVerifier<'a, 'p> {
    pub(super) fn frame_enter(
        &mut self,
        expression: &'p Expr,
        scope: usize,
    ) -> Result<(), Diagnostic> {
        match &expression.kind {
            ExprKind::VecConstructor { .. } => {
                let hygienic = *self.constructor_hygiene.get_or_insert_with(|| {
                    crate::ast::expression_statement::projection_roots(
                        self.current
                            .requires
                            .iter()
                            .chain(std::iter::once(&self.current.body))
                            .chain(&self.current.ensures),
                        self.current
                            .params
                            .iter()
                            .map(|param| param.name.as_str())
                            .chain(
                                self.current
                                    .type_parameters
                                    .iter()
                                    .map(|param| param.name.as_str()),
                            ),
                        crate::bounded_output::reserve_active_required,
                    )
                });
                if !hygienic {
                    return Err(error(
                        self.program,
                        "SPX-T318",
                        "Vec constructor generated owner names are not hygienic",
                        expression.span,
                    ));
                }
                let expansion = crate::ast::vec_constructor::inspect(expression)
                    .map_err(|message| error(self.program, "SPX-T318", message, expression.span))?;
                self.frames.push(VerifierFrame::Enter {
                    expression: expansion.value,
                    scope,
                });
            }
            ExprKind::LexicalExit { kind, value } => {
                if let Some(operand) = value {
                    self.frames.push(VerifierFrame::ResumeLexicalReturn {
                        expression,
                        operand,
                        scope,
                    });
                    self.frames.push(VerifierFrame::Enter {
                        expression: operand,
                        scope,
                    });
                } else if *kind != crate::ast::LexicalExitKind::Return {
                    self.values.push(Some(CheckedValue::value(Type::Never)));
                } else {
                    return Err(error(
                        self.program,
                        "SPX-T312",
                        "return requires an operand",
                        expression.span,
                    ));
                }
            }
            ExprKind::Closure { .. } => self.enter_closure(expression, scope)?,
            ExprKind::Int(_) => self.values.push(Some(CheckedValue::value(Type::I64))),
            ExprKind::Int32(_) => self.values.push(Some(CheckedValue::value(Type::I32))),
            ExprKind::Char(_) => self.values.push(Some(CheckedValue::value(Type::Char))),
            ExprKind::Uint8(_) => self.values.push(Some(CheckedValue::value(Type::U8))),
            ExprKind::Usize(_) => self.values.push(Some(CheckedValue::value(Type::Usize))),
            ExprKind::ArrayU8(values) => self.values.push(Some(CheckedValue::value(
                Type::ArrayU8(values.len() as u32),
            ))),
            ExprKind::RepeatArrayU8 { count, .. } => self
                .values
                .push(Some(CheckedValue::value(Type::ArrayU8(*count)))),
            ExprKind::Float32(_) => self.values.push(Some(CheckedValue::value(Type::F32))),
            ExprKind::Float64(_) => self.values.push(Some(CheckedValue::value(Type::F64))),
            ExprKind::Bool(_) => self.values.push(Some(CheckedValue::value(Type::Bool))),
            ExprKind::String(_) => self.values.push(Some(CheckedValue::value(Type::String))),
            ExprKind::BorrowedUtf8Literal(text) => {
                self.values
                    .push(Some(crate::source_verify::static_text::checked(
                        self.program,
                        expression.span,
                        text,
                    )?))
            }
            ExprKind::Var(name) if name == "result" => {
                let value = self
                    .result_type
                    .map(|ty| CheckedValue::returned(ty.clone(), self.types.needs_drop(ty)));
                if value.is_none() {
                    self.diagnostics.push(
                        error(
                            self.program,
                            "SPX-T201",
                            "`result` is only available in postconditions",
                            expression.span,
                        )
                        .with_help(hints::RESULT_NAME_HELP),
                    );
                }
                self.values.push(value);
            }
            ExprKind::Var(name) => {
                if self.scopes[scope]
                    .bindings
                    .get(name)
                    .is_some_and(|binding| binding.traversal_row.is_some())
                    && !self
                        .row_loan_sites
                        .contains(&(expression.span.start, expression.span.end))
                {
                    return Err(error(
                        self.program,
                        "SPX-T284",
                        "record traversal row cannot escape or materialize aggregate storage; select a field",
                        expression.span,
                    ));
                }
                let value = self.scopes[scope].bindings.get(name).map(|binding| {
                    crate::source_verify::owning_closure::reject_escaping_read(
                        self.program,
                        name,
                        &binding.ty,
                        expression.span,
                        self.diagnostics,
                    );
                    match binding.availability {
                        Availability::Moved => self.diagnostics.push(
                            error(
                                self.program,
                                "SPX-O101",
                                format!("use of resource `{name}` after ownership was moved"),
                                expression.span,
                            )
