                    VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Borrowed(
                        function,
                    ))) => activate_borrowed_bytes_call_loans(
                        self.program,
                        args,
                        &function.params,
                        &mut self.scopes[scope].bindings,
                        self.types,
                    ),
                    VerifierCallTarget::Ordinary(Some(
                        VerifierFunctionSignature::Specialized { params, .. },
                    )) if params.iter().any(|p| {
                        crate::source_verify::declared_type::collection_record::vector(
                            self.types, &p.ty,
                        )
                    }) =>
                    {
                        activate_borrowed_bytes_call_loans(
                            self.program,
                            args,
                            params,
                            &mut self.scopes[scope].bindings,
                            self.types,
                        )
                    }
                    _ => Vec::new(),
                };
                if let Some(argument) = args.first() {
                    self.frames.push(VerifierFrame::ResumeCallArgument {
                        expression,
                        name,
                        args,
                        scope,
                        index: 0,
                        target,
                        borrowed_bytes_loans,
                    });
                    self.frames.push(VerifierFrame::Enter {
                        expression: argument,
                        scope,
                    });
                } else {
                    self.values.push(Some(match target {
                        VerifierCallTarget::LiteralFormat => {
                            CheckedValue::returned(Type::String, true)
                        }
                        VerifierCallTarget::Native(import) => {
                            let mut value = CheckedValue::returned(
                                import.result.value_type(),
                                import.result.is_owned(),
                            );
                            value.native_unit = import.result == ImportResult::Unit;
                            value
                        }
                        VerifierCallTarget::Byte(op) => {
                            let ty = op.ast_return_type();
                            let owns = self.types.needs_drop(&ty);
                            CheckedValue::returned(ty, owns)
                        }
                        VerifierCallTarget::HostIo(op) => {
                            CheckedValue::returned(op.ast_return_type(), false)
                        }
                        VerifierCallTarget::CommandIo(op) => CheckedValue {
                            ty: crate::command_io_ops::ast_return_type(op),
                            mode: match op {
                                crate::hir::ResolvedHostCommandOperation::ArgUtf8 => {
                                    ParamMode::Borrow
                                }
                                crate::hir::ResolvedHostCommandOperation::StdinRead => {
                                    ParamMode::Own
                                }
                                crate::hir::ResolvedHostCommandOperation::ArgsLen
                                | crate::hir::ResolvedHostCommandOperation::StderrWrite
                                | crate::hir::ResolvedHostCommandOperation::StdoutAppend
                                | crate::hir::ResolvedHostCommandOperation::StderrAppend => {
                                    ParamMode::Value
                                }
                                operation => {
                                    match crate::command_io_ops::result_ownership(operation) {
                                        crate::hir::OwnershipMode::Own => ParamMode::Own,
                                        crate::hir::OwnershipMode::Borrow => ParamMode::Borrow,
                                        _ => ParamMode::Value,
                                    }
                                }
                            },
                            native_unit: false,
                        },
                        VerifierCallTarget::Ordinary(Some(target)) => CheckedValue::returned(
                            target.return_type().clone(),
                            self.types.needs_drop(target.return_type()),
                        ),
                        VerifierCallTarget::Ordinary(None) => {
                            self.values.push(None);
                            return Ok(());
                        }
                    }));
                }
            }
            ExprKind::MethodCall {
                receiver,
                method,
                type_arguments,
                args,
                ..
            } => {
                if !type_arguments.is_empty() {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T225",
                        format!("method `{method}` does not accept type arguments in this slice"),
                        expression.span,
                    ));
                }
                self.frames.push(VerifierFrame::ResumeMethodReceiver {
                    expression,
                    receiver,
                    method,
                    args,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: receiver,
                    scope,
                });
            }
            // These walkers only traverse generic-function and contract
            // expressions; `super` is meaningful only inside a class-method
            // override, whose body is resolved by the HIR layer instead.
            ExprKind::SuperMethod { method_span, .. } => {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T231",
                    "`super` is only allowed inside a class-method override",
                    *method_span,
                ));
                self.values.push(None);
            }
            ExprKind::If {
                condition,
                then_branch,
                else_branch,
            } => {
                self.frames.push(VerifierFrame::ResumeIfCondition {
                    expression,
                    then_branch,
                    else_branch,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: condition,
                    scope,
                });
            }
            ExprKind::Block { statements, tail } => {
                let outer_names = self.scopes[scope]
                    .bindings
                    .keys()
                    .cloned()
                    .collect::<Vec<_>>();
                let block_scope = self.scopes.len();
                self.scopes.push(VerifierScope {
                    bindings: self.scopes[scope].bindings.clone(),
                    local_borrow_count: self.scopes[scope].local_borrow_count,
                });
                if let Some(first_statement) = statements.first() {
                    if let Statement::Let {
                        name, name_span, ..
                    } = first_statement
                    {
                        if !source_identifier(name) {
                            self.diagnostics.push(hints::reserved_local_binding(
                                self.program,
                                name,
                                *name_span,
                            ));
                        }
                    }
                    if let Statement::While {
                        condition, body, ..
                    } = first_statement
                    {
                        self.begin_while_statement(
                            expression,
                            statements,
                            tail,
                            scope,
                            block_scope,
                            0,
                            outer_names,
                            condition,
                            body,
                        );
                    } else if let Statement::For {
                        item,
                        item_span,
                        values,
                        body,
                        ..
                    }
                    | Statement::ForBorrow {
                        item,
                        item_span,
                        values,
                        body,
                        ..
                    }
                    | Statement::ForOwn {
                        item,
                        item_span,
                        values,
                        body,
                        ..
                    } = first_statement
                    {
                        self.begin_for_statement(
                            expression,
                            statements,
                            tail,
                            scope,
                            block_scope,
                            0,
                            outer_names,
                            item,
                            *item_span,
                            values,
                            body,
                        );
                    } else {
                        self.check_string_replacement_entry(first_statement, block_scope);
                        self.note_owned_buffer_reopen(first_statement);
                        self.frames.push(VerifierFrame::ResumeBlockStatement {
                            expression,
                            statements,
                            tail,
                            parent_scope: scope,
                            block_scope,
                            index: 0,
                            outer_names,
                        });
                        self.frames.push(VerifierFrame::Enter {
                            expression: first_statement.value(),
                            scope: block_scope,
                        });
                    }
                } else {
                    self.frames.push(VerifierFrame::ResumeBlockTail {
                        parent_scope: scope,
                        block_scope,
                        outer_names,
                    });
                    self.frames.push(VerifierFrame::Enter {
                        expression: tail,
                        scope: block_scope,
                    });
                }
            }
            // Resumable Effects v1 (issue #204). See
            // `iterative::calls::frame_resume_yield`.
            ExprKind::Yield { request } => {
                self.frames.push(VerifierFrame::ResumeYield {
                    expression,
                    request,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: request,
                    scope,
                });
            }
            ExprKind::Try { operand } => {
                self.frames.push(VerifierFrame::ResumeTry {
                    expression,
                    operand,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: operand,
                    scope,
                });
            }
            ExprKind::Project { base, field, .. } => {
                if let Some((root, value)) = crate::source_verify::record_traversal::project(
                    expression,
                    &self.scopes[scope].bindings,
                    self.types,
                ) {
                    let owner = Expr {
                        kind: ExprKind::Var(root),
                        span: expression.span,
                    };
                    if let Some(place) =
                        source_place(&owner, &self.scopes[scope].bindings, self.types)
                    {
                        check_source_place_availability(
                            self.program,
                            &place,
                            &self.scopes[scope].bindings,
                            expression.span,
                            self.diagnostics,
                        );
                    }
                    self.values.push(Some(value));
                    return Ok(());
                }
                let rooted_string_view = matches!(
                    self.frames.last(),
                    Some(VerifierFrame::ResumeCallArgument {
                        target: VerifierCallTarget::Byte(crate::byte_ops::ByteOp::StringAsStr),
                        ..
                    })
                ) && source_byte_view_place_is_admitted(
                    crate::byte_ops::ByteOp::StringAsStr,
                    expression,
                    &self.scopes[scope].bindings,
                    self.types,
                );
                if self.loop_depth != 0 && !rooted_string_view
                    && source_place(base, &self.scopes[scope].bindings, self.types).is_some_and(
                        |place| {
                            !crate::source_verify::declared_type::owned_leaf_collection::copy_or_leaf_admitted(
                                self.types, &place.ty,
                            ) && !crate::source_verify::declared_type::collection_record::admitted(&place.ty, self.types)
                        },
                    )
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T252",
                        "record field projection is not yet admitted in while bodies",
                        expression.span,
                    ));
                }
                if let Some(place) =
                    source_place(expression, &self.scopes[scope].bindings, self.types)
                {
                    check_source_place_availability(
                        self.program,
                        &place,
                        &self.scopes[scope].bindings,
                        expression.span,
                        self.diagnostics,
                    );
                    self.values.push(Some(CheckedValue {
                        ty: place.ty,
                        mode: place.mode,
                        native_unit: false,
                    }));
                } else {
                    self.frames.push(VerifierFrame::ResumeProject {
                        expression,
                        base,
                        field,
                    });
                    self.frames.push(VerifierFrame::Enter {
                        expression: base,
                        scope,
                    });
                }
            }
            ExprKind::ConstructRecord {
                type_name,
                type_arguments,
                fields,
                ..
            } => {
                if matches!(type_name.as_str(), "Map" | "Set") {
                    return Err(error(
                        self.program,
                        "SPX-T274",
                        "collections can only be created by map_new/set_new",
                        expression.span,
                    ));
                }
                if type_name == "Iter" {
                    return Err(error(
                        self.program,
                        "SPX-T290",
                        "Iter carriers can only be created by vec_into_iter",
                        expression.span,
                    ));
                }
                let instance = Type::Named {
                    name: type_name.clone(),
                    arguments: type_arguments.clone(),
                };
                check_declared_type(
                    self.program,
                    &instance,
                    expression.span,
                    self.types,
                    &HashSet::new(),
                    self.diagnostics,
                );
                let declared_fields = effective_record_fields(self.types, &instance);
                if declared_fields.is_none() {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T215",
                        format!("`{type_name}` is not a declared record type"),
                        expression.span,
                    ));
                }
                if !fields.is_empty() {
                    self.frames.push(VerifierFrame::PrepareRecordField {
                        expression,
                        type_name,
                        type_arguments,
                        fields,
                        declared_fields,
                        scope,
                        index: 0,
                        supplied: HashSet::new(),
                    });
                } else {
                    if let Some(declared_fields) = declared_fields {
                        for field in declared_fields {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-T213",
                                format!(
                                    "record `{type_name}` construction is missing field `{}`",
                                    field.name
                                ),
                                expression.span,
                            ));
                        }
                        self.values.push(Some(CheckedValue::returned(
                            instance.clone(),
                            self.types.needs_drop(&instance),
                        )));
                    } else {
                        self.values.push(None);
                    }
                }
            }
            ExprKind::ConstructVariant {
                type_name,
                type_arguments,
                case_name,
                fields,
                ..
            } => {
                let declaration = self.types.declaration(type_name);
                let instance = Type::Named {
                    name: type_name.clone(),
                    arguments: type_arguments.clone(),
                };
                check_declared_type(
                    self.program,
                    &instance,
                    expression.span,
                    self.types,
                    &HashSet::new(),
                    self.diagnostics,
                );
                let cases = declaration.and_then(|declaration| match &declaration.kind {
                    TypeDeclarationKind::Variant { cases } => Some(cases.as_slice()),
                    TypeDeclarationKind::Resource { .. }
                    | TypeDeclarationKind::Record { .. }
                    | TypeDeclarationKind::Class { .. } => None,
                });
                let case =
                    cases.and_then(|cases| cases.iter().find(|case| case.name == *case_name));
                if cases.is_none() || case.is_none() {
                    let diagnostic = error(
                        self.program,
                        "SPX-T215",
                        format!("`{type_name}::{case_name}` is not a declared variant constructor"),
                        expression.span,
                    );
                    self.diagnostics.push(
                        match cases.and_then(|cases| {
                            crate::source_verify::hints::nearest_variant_case_name(case_name, cases)
                        }) {
                            Some(nearest) => diagnostic.with_help(format!(
                                "did you mean `{type_name}::{nearest} {{ ... }}`?"
                            )),
                            None => diagnostic,
                        },
                    );
                }
                if !fields.is_empty() {
                    self.frames.push(VerifierFrame::PrepareVariantField {
                        expression,
                        type_name,
                        type_arguments,
                        case_name,
                        fields,
                        declaration,
                        case,
                        scope,
                        index: 0,
                        supplied: HashSet::new(),
                    });
                } else {
                    if let Some(case) = case {
                        for field in &case.fields {
                            self.diagnostics.push(error(self.program, "SPX-T213", format!("variant construction `{type_name}::{case_name}` is missing payload field `{}`", field.name), expression.span));
                        }
                        // Ownership belongs to the complete variant carrier, not
                        // only to the selected case. A zero-payload case of a
                        // variant whose other cases contain owned fields is still
                        // a fresh owned carrier and must cross return/call
                        // boundaries exactly once.
                        self.values.push(Some(CheckedValue::returned(
                            instance.clone(),
                            self.types.needs_drop(&instance),
                        )));
                    } else if cases.is_some() {
                        self.values.push(Some(CheckedValue::returned(
                            instance.clone(),
                            self.types.needs_drop(&instance),
                        )));
                    } else {
                        self.values.push(None);
                    }
                }
            }
            ExprKind::UpdateRecord { base, fields } => {
                self.frames.push(VerifierFrame::ResumeUpdateBase {
                    expression,
                    base,
                    fields,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: base,
                    scope,
                });
            }
            ExprKind::Match {
                scrutinee, arms, ..
            } => {
                self.frames.push(VerifierFrame::ResumeMatchScrutinee {
                    expression,
                    scrutinee,
                    arms,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: scrutinee,
                    scope,
                });
            }
        }
        Ok(())
    }
}

//! Block and `while` frames: statement sequencing, block tails, and the
//! loop-invariance checks a `while` body must satisfy.

use crate::ast::{Expr, ParamMode, Span, Statement, Type};
use crate::diagnostic::Diagnostic;
use crate::source_verify::binding::{Availability, Binding};
use crate::source_verify::diagnostics::{error, is_scalar_source_type, reject_native_unit_value};
use crate::source_verify::loans::{
    activate_local_loan, has_active_overlapping_loan, local_borrow_origin,
    mark_value_sources_moved, merge_moved, release_dead_local_loans,
};
use crate::source_verify::IterativeVerifier;
use std::collections::{BTreeSet, HashMap, HashSet};

impl<'a, 'p> IterativeVerifier<'a, 'p> {
    pub(super) fn check_string_replacement_entry(&mut self, statement: &Statement, scope: usize) {
        if let Statement::Assign {
            name,
            name_span,
            field: None,
            ..
        } = statement
        {
            if let Some(binding) = self.scopes[scope].bindings.get(name) {
                if binding.ty == Type::String && binding.availability != Availability::Available {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-O101",
                        "String replacement starts with an unavailable owner",
                        *name_span,
                    ));
                }
            }
        }
    }
    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_block_statement(
        &mut self,
        expression: &'p Expr,
        statements: &'p [Statement],
        tail: &'p Expr,
        parent_scope: usize,
        block_scope: usize,
        index: usize,
        outer_names: Vec<String>,
    ) -> Result<(), Diagnostic> {
        let actual = self.values.pop().unwrap_or(None);
        match &statements[index] {
            Statement::Let {
                name,
                name_span,
                mutable,
                declared,
                value,
                ..
            } => {
                if self.scopes[block_scope].bindings.contains_key(name) {
                    self.diagnostics.push(
                        error(
                            self.program,
                            "SPX-T209",
                            format!("local binding `{name}` shadows an existing value"),
                            *name_span,
                        )
                        .with_help(crate::source_verify::hints::SHADOW_HELP),
                    );
                } else if let Some(actual) = actual {
                    if let Some(diagnostic) = crate::source_verify::expression_statement::check(
                        self.program,
                        &statements[index],
                        &actual,
                    ) {
                        self.diagnostics.push(diagnostic);
                    }
                    if matches!(actual.ty, Type::SliceU8 | Type::Str) && *mutable {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T264",
                            format!(
                                "byte-slice alias `{name}` must be immutable and cannot be reassigned"
                            ),
                            *name_span,
                        ));
                    }
                    // Class Inheritance v1: a declared type accepts
                    // the value's exact type or an ancestor class
                    // whose prefix consumes the value cleanly; the
                    // binding carries the declared type.
                    let mut binding_ty = actual.ty.clone();
                    let mut binding_mode = actual.mode;
                    if let Some(declared_ty) = declared {
                        let exact = actual.ty == *declared_ty;
                        let mut upcast = false;
                        if !exact {
                            if let (
                                Type::Named { name: child, .. },
                                Type::Named { name: ancestor, .. },
                            ) = (&actual.ty, declared_ty)
                            {
                                if self.types.class_extends(child, ancestor) {
                                    if self.upcast_discards_owned_state(child, ancestor) {
                                        self.diagnostics.push(error(
                                            self.program,
                                            "SPX-T233",
                                            format!(
                                                "upcast from `{child}` to `{ancestor}` would discard owned state; only cleanup-inert child fields are admitted in this slice"
                                            ),
                                            value.span,
                                        ));
                                    }
                                    upcast = true;
                                }
                            }
                        }
                        if exact || upcast {
                            binding_ty = declared_ty.clone();
                            binding_mode = if matches!(declared_ty, Type::SliceU8 | Type::Str) {
                                ParamMode::Borrow
                            } else if self.types.needs_drop(declared_ty)
                                || declared_ty.is_uniquely_owned()
                            {
                                ParamMode::Own
                            } else {
                                ParamMode::Value
                            };
                        } else {
                            let diagnostic = if matches!(
                                (&actual.ty, declared_ty),
                                (Type::ArrayU8(_), Type::ArrayU8(_))
                            ) {
                                "SPX-T262"
                            } else {
                                "SPX-T232"
                            };
                            let help = (diagnostic == "SPX-T232")
                                .then(|| {
                                    crate::source_verify::hints::declared_binding_help(
                                        declared_ty,
                                        value,
                                    )
                                })
                                .flatten();
                            self.diagnostics.push(crate::source_verify::hints::with_optional_help(
                                error(
                                    self.program,
                                    diagnostic,
                                    format!(
                                        "declared binding type `{}` does not accept value type `{}`",
                                        // Generic validation specialization
                                        // substitutes `let` annotations, so a
                                        // declared type can carry a private copy.
                                        crate::source_verify::private_names::type_name(
                                            self.program,
                                            self.types,
                                            declared_ty
                                        ),
                                        crate::source_verify::private_names::type_name(
                                            self.program,
                                            self.types,
                                            &actual.ty
                                        )
                                    ),
                                    value.span,
                                ),
                                help,
                            ));
                        }
                    }
                    let contract_local = !self.allow_moves
                        && actual.mode == ParamMode::Own
                        && crate::source_verify::contract_owners::fresh(
                            value,
                            &actual.ty,
                            &self.scopes[block_scope].bindings,
                        );
                    if self.types.needs_drop(&actual.ty) && actual.mode == ParamMode::Own {
                        if self.allow_moves || contract_local {
                            mark_value_sources_moved(
                                self.program,
                                value,
                                &mut self.scopes[block_scope].bindings,
                                self.types,
                                self.diagnostics,
                            );
                        } else {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-O105",
                                "contract expression cannot transfer an owned resource into a local binding",
                                value.span,
                            ));
                        }
                    }
                    let borrow_origin = matches!(binding_ty, Type::SliceU8 | Type::Str)
                        .then(|| {
                            local_borrow_origin(
                                self.program,
                                value,
                                name,
                                *name_span,
                                &self.scopes[block_scope].bindings,
                                self.types,
                            )
                        })
                        .flatten();
                    if let Some(origin) = &borrow_origin {
                        activate_local_loan(&mut self.scopes[block_scope].bindings, origin);
                        self.scopes[block_scope].local_borrow_count += 1;
                    }
                    self.scopes[block_scope].bindings.insert(
                        name.clone(),
                        Binding {
                            contract_local,
                            traversal_row: None,
                            ty: binding_ty,
                            mode: binding_mode,
                            availability: Availability::Available,
                            moved_places: HashMap::new(),
                            definitely_partial: HashSet::new(),
                            native_unit_discard: actual.native_unit,
                            mutable: *mutable,
                            active_loans: BTreeSet::new(),
                            borrow_origin,
                        },
                    );
                }
            }
            Statement::Assign { value, .. } if !self.allow_moves => {
                // Contract expressions stay pure: no stores.
                self.diagnostics.push(error(
                    self.program,
                    "SPX-U106",
                    "assignment statements are not allowed in contract expressions",
                    value.span,
                ));
            }
            Statement::Assign {
                name,
                name_span,
                field,
                value,
                ..
            } => {
                let assigned_projections = field
                    .iter()
                    .map(|field| field.name.clone())
                    .collect::<Vec<_>>();
                let target = self.scopes[block_scope]
                    .bindings
                    .get(name.as_str())
                    .map(|binding| {
                        (
                            binding.mutable,
                            binding.ty.clone(),
                            has_active_overlapping_loan(binding, &assigned_projections),
                        )
                    });
                if target.is_none() {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T202",
                        format!("unknown value `{name}` in `{}`", self.current.name),
                        *name_span,
                    ));
                }
                if let Some((mutable, binding_ty, has_active_loans)) = target {
                    if has_active_loans {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T265",
                            "assignment would replace storage held by a lexical byte view",
                            *name_span,
                        ));
                    }
                    match field {
                        Some(field) => {
                            // Field Mutation v1: one direct scalar
                            // Copy field of a `let mut` record or
                            // class local.
                            if !mutable {
                                self.diagnostics.push(error(
                                    self.program,
                                    "SPX-U107",
                                    format!(
                                        "cannot assign to field of immutable binding `{name}`; declare it with `let mut`"
                                    ),
                                    *name_span,
                                ));
                            }
                            match self.types.record_fields(&binding_ty) {
                                None => {
                                    self.diagnostics.push(error(
                                        self.program,
                                        "SPX-U112",
                                        format!(
                                            "cannot mutate a field of non-record value `{binding_ty}`"
                                        ),
                                        field.span,
                                    ));
                                }
                                Some(fields) => {
                                    let declared = fields
                                        .iter()
                                        .find(|candidate| candidate.name == field.name);
                                    if let Some(declared) = declared {
                                        let field_ty = self
                                            .types
                                            .record_field_type(&binding_ty, declared)
                                            .unwrap_or_else(|| declared.ty.clone());
                                        if !is_scalar_source_type(&field_ty) {
                                            self.diagnostics.push(error(
                                                self.program,
                                                "SPX-U109",
                                                "field mutation v1 supports only direct scalar Copy record fields",
                                                field.span,
                                            ));
                                        }
                                        if let Some(actual) = &actual {
                                            if actual.ty != field_ty {
                                                self.diagnostics.push(error(
                                                    self.program,
                                                    "SPX-U110",
                                                    format!(
                                                        "assigned value type `{}` does not exactly match field type `{}`",
                                                        actual.ty, field_ty
                                                    ),
                                                    value.span,
                                                ));
                                            }
                                        }
                                    } else {
                                        self.diagnostics.push(error(
                                            self.program,
                                            "SPX-U108",
                                            format!(
                                                "record `{binding_ty}` has no field `{}`",
                                                field.name
                                            ),
                                            field.span,
                                        ));
                                    }
                                }
                            }
                        }
                        None => {
                            // The source verifier runs before HIR has the
                            // enclosing `yields Request -> Response` clause
                            // available to retag this direct expression. Its
                            // initial type is therefore the request type;
                            // defer only this whole-binding mismatch to
                            // `finish_yields_admission`, which checks the
                            // binding against the declared response type.
                            // Field assignments and every non-yield value
                            // retain the ordinary exact-type diagnostic here.
                            let direct_yield =
                                matches!(&value.kind, crate::ast::ExprKind::Yield { .. });
                            // Same-owner replacement: a `Vec<T>` reopen such as
                            // `values = vec_push(values, v)` and the byte-buffer
                            // `buffer = bytes_set(buffer, index, value)` and the
                            // Owned String Loops v1 append
                            // `text = string_concat(text, more)` are the
                            // admitted owned reopen shapes. The right-hand side
                            // evaluates before publication, so exactly one
                            // generation of the owner is ever live.
                            let owned_reopen = (binding_ty == crate::ast::Type::Bytes
                                && self.byte_helper_assignment(name, value))
                                || (binding_ty == crate::ast::Type::String
                                    && actual.as_ref().is_some_and(|v| {
                                        v.ty == crate::ast::Type::String && v.mode == ParamMode::Own
                                    }))
                                || crate::vec_ops::is_same_owner_reassignment_source(
                                    self.program,
                                    value,
                                    name,
                                    &binding_ty,
                                )
                                || crate::byte_ops::is_same_owner_set_source(
                                    value,
                                    name,
                                    &binding_ty,
                                )
                                || crate::string_ops::is_same_owner_concat_source(
                                    value,
                                    name,
                                    &binding_ty,
                                )
                                || (self.loop_depth != 0
                                    && self.admits_record_owner_renewal(name, value))
                                || (crate::stdin_stream_ops::ast_is_reader(&binding_ty)
                                    && crate::stdin_stream_ops::source_next_is_same_owner(
                                        self.program,
                                        name,
                                        value,
                                    ));
                            if !mutable {
                                let mut diagnostic = error(
                                    self.program,
                                    "SPX-U101",
                                    format!(
                                        "cannot assign to immutable binding `{name}`; declare it with `let mut`"
                                    ),
                                    *name_span,
                                );
                                if self
                                    .current
                                    .params
                                    .iter()
                                    .any(|parameter| parameter.name == *name)
                                {
                                    diagnostic = diagnostic.with_help(format!(
                                        "parameters are immutable; copy `{name}` into a new mutable local and use that: `let mut current_{name} = {name};`"
                                    ));
                                }
                                self.diagnostics.push(diagnostic);
                            }
                            if let Some(actual) = &actual {
                                if mutable && actual.ty != binding_ty && !direct_yield {
                                    self.diagnostics.push(error(
                                        self.program,
                                        "SPX-U102",
                                        format!(
                                            "assigned value type `{}` does not exactly match binding type `{}`",
                                            actual.ty, binding_ty
                                        ),
                                        value.span,
                                    ));
                                }
                                if mutable
                                    && (actual.mode != ParamMode::Value
                                        || !crate::source_verify::closure::scoped_scalar(
                                            self.current,
                                            &actual.ty,
                                        ))
                                    && !owned_reopen
                                {
                                    self.diagnostics.push(error(
                                        self.program,
                                        "SPX-U105",
                                        "explicit mutation v1 supports only scalar Copy values",
                                        value.span,
                                    ));
                                }
                            }
                            if mutable && owned_reopen {
                                if binding_ty == Type::String
                                    && !crate::string_ops::is_same_owner_concat_source(
                                        value,
                                        name,
                                        &binding_ty,
                                    )
                                {
                                    mark_value_sources_moved(
                                        self.program,
                                        value,
                                        &mut self.scopes[block_scope].bindings,
                                        self.types,
                                        self.diagnostics,
                                    );
                                }
                                if let Some(binding) =
                                    self.scopes[block_scope].bindings.get_mut(name.as_str())
                                {
                                    binding.availability = Availability::Available;
                                    binding.moved_places.clear();
                                    binding.definitely_partial.clear();
                                }
                            }
                        }
                    }
                }
            }
            Statement::Unsafe { body, span, .. } => {
                // Unsafe Boundary Mechanics v1: the module must
                // explicitly permit the `unsafe` capability and
                // the discarded body result must be a scalar Copy
                // value. Contract expressions reject boundaries.
                if !self.allow_moves {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-N105",
                        "unsafe boundary statements are not allowed in contract expressions",
                        *span,
                    ));
                } else {
                    if !self
                        .program
                        .permits()
                        .iter()
                        .any(|permit| permit == "unsafe")
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-N101",
                            "unsafe block requires the module capability declaration `permit { unsafe }`",
                            *span,
                        ));
                    }
                    if let Some(actual) = &actual {
                        if actual.mode != ParamMode::Value || !is_scalar_source_type(&actual.ty) {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-N104",
                                "unsafe boundary bodies must produce a scalar Copy value",
                                body.span,
                            ));
                        }
                    }
                }
            }
            // While statements never route through this frame:
            // they complete through ResumeWhileBody instead.
            Statement::While { .. }
            | Statement::For { .. }
            | Statement::ForBorrow { .. }
            | Statement::ForOwn { .. } => {}
        }
        // Most blocks have no borrowed local at all. Avoid rescanning every
        // accumulated scalar binding after each statement in that common
        // case; the full liveness walk remains exact once a borrow exists.
        if self.scopes[block_scope].local_borrow_count != 0 {
            let released = release_dead_local_loans(
                &mut self.scopes[block_scope].bindings,
                statements.get(index + 1..).unwrap_or_default(),
                tail,
            );
            self.scopes[block_scope].local_borrow_count = self.scopes[block_scope]
                .local_borrow_count
                .saturating_sub(released);
        }
        self.advance_block_statement(
            expression,
            statements,
            tail,
            parent_scope,
            block_scope,
            index,
            outer_names,
        );
        Ok(())
    }

    pub(super) fn frame_resume_while_condition(
        &mut self,
        condition: &'p Expr,
        block_scope: usize,
        baseline: HashMap<String, Binding>,
    ) -> Result<(), Diagnostic> {
        // The condition is re-evaluated before every iteration and
        // must be exactly `bool`.
        let condition_value = self.values.pop().unwrap_or(None);
        if let Some(value) = condition_value {
            if value.native_unit {
                reject_native_unit_value(self.program, condition, &value, self.diagnostics);
            } else if value.ty != Type::Bool {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T251",
                    "`while` condition must be bool",
                    condition.span,
                ));
            }
        }
        let mut names = baseline.keys().collect::<Vec<_>>();
        names.sort();
        for name in names {
            let before = &baseline[name];
            if self.scopes[block_scope]
                .bindings
                .get(name)
                .is_none_or(|now| {
                    now.availability != before.availability
                        || now.moved_places != before.moved_places
                        || now.definitely_partial != before.definitely_partial
                })
            {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T252",
                    format!("ownership of `{name}` changes inside a while condition"),
                    condition.span,
                ));
            }
        }
        // The body is an ordinary block; it verifies with its own
        // child scope and its value is discarded by
        // ResumeWhileBody.
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_while_body(
        &mut self,
        expression: &'p Expr,
        statements: &'p [Statement],
        tail: &'p Expr,
        parent_scope: usize,
        block_scope: usize,
        index: usize,
        outer_names: Vec<String>,
        statement_span: Span,
        baseline_names: Vec<String>,
        baseline_bindings: HashMap<String, Binding>,
    ) -> Result<(), Diagnostic> {
        // Discard the body block's value: while statements
        // produce none. The body block merged its own child scope
        // through ResumeBlockTail. Because the v1 admission
        // profile admits only Copy-scalar operations inside the
        // loop, every outer binding must be exactly as available
        // as it was on entry; any drift means a move happened
        // inside the loop and is rejected fail-closed.
        let exits = self
            .values
            .pop()
            .flatten()
            .is_some_and(|value| value.ty == Type::Never);
        if exits && crate::ast::returns_only(statements[index].child(1).expect("while body")) {
            for name in &baseline_names {
                if let Some(before) = baseline_bindings.get(name) {
                    self.scopes[block_scope]
                        .bindings
                        .insert(name.clone(), before.clone());
                }
            }
        }
        self.loop_depth = self.loop_depth.saturating_sub(1);
        for name in &baseline_names {
            let drifted = match (
                self.scopes[block_scope].bindings.get(name),
                baseline_bindings.get(name),
            ) {
                (Some(now), Some(before)) => {
                    now.availability != before.availability
                        || now.moved_places != before.moved_places
                        || now.definitely_partial != before.definitely_partial
                }
                (Some(_), None) | (None, Some(_)) => true,
                (None, None) => false,
            };
            if drifted {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T252",
                    format!(
                        "ownership of `{name}` changes inside a while loop, which is not yet admitted"
                    ),
                    statement_span,
                ));
            }
        }
        let _ = baseline_names;
        release_dead_local_loans(
            &mut self.scopes[block_scope].bindings,
            statements.get(index + 1..).unwrap_or_default(),
            tail,
        );
        self.advance_block_statement(
            expression,
            statements,
            tail,
            parent_scope,
            block_scope,
            index,
            outer_names,
        );
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_for_source(
        &mut self,
        expression: &'p Expr,
        statements: &'p [Statement],
        tail: &'p Expr,
        parent_scope: usize,
        block_scope: usize,
        index: usize,
        outer_names: Vec<String>,
        item: &'p str,
        item_span: Span,
        values: &'p Expr,
        body: &'p Expr,
    ) -> Result<(), Diagnostic> {
        let actual = self.values.pop().unwrap_or(None);
        let consuming = matches!(statements[index], Statement::ForOwn { .. });
        let borrowing = matches!(statements[index], Statement::ForBorrow { .. });
        let source = match &values.kind {
            crate::ast::ExprKind::Var(name) if !consuming => Some(name.as_str()),
            _ => None,
        };
        let element = actual.as_ref().and_then(|actual| match &actual.ty {
            ty @ Type::SliceU8 if !consuming && !borrowing => {
                crate::source_verify::byte_traversal::element(ty)
            }
            Type::Named { name, arguments }
                if name == (if consuming { "Iter" } else { "Vec" })
                    && matches!(arguments.as_slice(), [ty] if crate::vec_ops::ast_element_is_admitted(ty) && !borrowing
                        || (borrowing && crate::source_verify::record_traversal::admitted(self.types, ty))
                        || (consuming && (*ty == Type::Bytes
                            || crate::source_verify::declared_type::owned_leaf_collection::runtime_element(self.types, ty)
                            || crate::source_verify::declared_type::generic_collection::slot(self.current, &actual.ty))))
                    && (!consuming || actual.mode == ParamMode::Own) => Some(arguments[0].clone()),
            _ => None,
        });
        if (!consuming && source.is_none()) || element.is_none() {
            self.diagnostics.push(error(self.program, "SPX-T284",
                if consuming { "for own traversal requires an owned Iter<T> for an admitted scalar, Bytes, or owned-record T" }
                else { "for traversal requires a simple immutable binding of exact Vec<T> for a Copy scalar T" }, values.span));
        }
        if consuming {
            if !self.allow_moves {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T253",
                    "for own statements are not allowed in contract expressions",
                    values.span,
                ));
            } else if element.is_some() {
                mark_value_sources_moved(
                    self.program,
                    values,
                    &mut self.scopes[block_scope].bindings,
                    self.types,
                    self.diagnostics,
                );
            }
        }
        if let Some(source) = source {
            if self.scopes[block_scope]
                .bindings
                .get(source)
                .is_some_and(|binding| binding.mutable)
            {
                self.diagnostics.push(
                    error(
                        self.program,
                        "SPX-T284",
                        "for traversal source must be an immutable Vec binding",
                        values.span,
                    )
                    .with_help(crate::source_verify::hints::IMMUTABLE_TRAVERSAL_HELP),
                );
            }
            let _ = self.reject_for_body_disallowed(body, source);
        }
        let baseline = consuming.then(|| self.scopes[block_scope].bindings.clone());
        let owned_record_item = element.as_ref().is_some_and(|element| {
            crate::source_verify::declared_type::owned_leaf_collection::runtime_element(
                self.types, element,
            )
        });
        let _ = self.reject_iterator_body(
            body,
            (consuming && (element == Some(Type::Bytes) || owned_record_item)).then_some(item),
        );
        let item_inserted = !self.scopes[block_scope].bindings.contains_key(item);
        if !item_inserted {
            self.diagnostics.push(error(
                self.program,
                "SPX-T209",
                format!("loop item `{item}` shadows an existing value"),
                item_span,
            ));
        }
        if item_inserted {
            if let Some(element) = element {
                self.scopes[block_scope].bindings.insert(
                    item.to_owned(),
                    Binding { contract_local: false, traversal_row: None,
                        mode: if consuming
                            && (element == Type::Bytes
                                || crate::source_verify::declared_type::owned_leaf_collection::runtime_element(
                                        self.types,
                                        &element,
                                    ))
                        {
                            ParamMode::Own
                        } else {
                            ParamMode::Value
                        },
                        ty: element,
                        availability: Availability::Available,
                        moved_places: HashMap::new(),
                        definitely_partial: HashSet::new(),
                        native_unit_discard: false,
                        mutable: false,
                        active_loans: BTreeSet::new(),
                        borrow_origin: None,
                    },
                );
            }
        }
        if borrowing && item_inserted {
            if let Some(source) = source {
                let selected_index = match &statements[index] {
                    Statement::ForBorrow {
                        index: Some(selected),
                        ..
                    } => Some(selected.name.as_str()),
                    _ => None,
                };
                match crate::source_verify::record_traversal::body_binding_conflict(
                    body,
                    source,
                    item,
                    selected_index,
                ) {
                    Ok(Some(span)) => {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T284",
                            "record traversal cannot shadow its carrier, row or index binding",
                            span,
                        ));
                    }
                    Ok(None) => {}
                    Err(()) => self.diagnostics.push(error(
                        self.program,
                        "SPX-T284",
                        "record traversal binding scan exceeds its source scratch, depth or work budget",
                        body.span,
                    )),
                }

                if let Some(binding) = self.scopes[block_scope].bindings.get_mut(item) {
                    binding.mode = ParamMode::Borrow;
                    binding.traversal_row =
                        Some(Box::new(crate::source_verify::record_traversal::Row {
                            root: source.to_owned(),
                            element: binding.ty.clone(),
                            index_inserted: false,
                            freeze: crate::source_verify::binding::SourceLoanId {
                                borrower: item.to_owned(),
                                start: values.span.start,
                                end: body.span.end,
                            },
                        }));
                }
            }
            if let Some(row) = self.scopes[block_scope]
                .bindings
                .get(item)
                .and_then(|binding| binding.traversal_row.as_deref())
                .cloned()
            {
                if let Some(owner) = self.scopes[block_scope].bindings.get_mut(&row.root) {
                    owner
                        .active_loans
                        .insert(crate::source_verify::binding::SourceLoan {
                            id: row.freeze,
                            projections: Vec::new(),
                        });
                }
            }
            if let Statement::ForBorrow {
                index: Some(selected),
                ..
            } = &statements[index]
            {
                if selected.name == item
                    || self.scopes[block_scope]
                        .bindings
                        .contains_key(&selected.name)
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T209",
                        "record traversal index must be a fresh distinct binding",
                        selected.span,
                    ));
                } else {
                    self.scopes[block_scope].bindings.insert(
                        selected.name.clone(),
                        Binding {
                            contract_local: false,
                            ty: Type::Usize,
                            mode: ParamMode::Value,
                            availability: Availability::Available,
                            moved_places: HashMap::new(),
                            definitely_partial: HashSet::new(),
                            native_unit_discard: false,
                            mutable: false,
                            active_loans: BTreeSet::new(),
                            borrow_origin: None,
                            traversal_row: None,
                        },
                    );
                    if let Some(row) = self.scopes[block_scope]
                        .bindings
                        .get_mut(item)
                        .and_then(|binding| binding.traversal_row.as_deref_mut())
                    {
                        row.index_inserted = true;
                    }
                }
            }
        }
        let byte_source = actual
            .as_ref()
            .is_some_and(|actual| actual.ty == Type::SliceU8)
            && !consuming
            && !borrowing;
        if let (true, Some(source)) = (byte_source && item_inserted, source) {
            crate::source_verify::byte_traversal::freeze(
                &mut self.scopes[block_scope].bindings,
                source,
                &crate::source_verify::byte_traversal::freeze_id(item, values.span, body.span),
            );
        }
        self.frames
            .push(crate::source_verify::scope::VerifierFrame::ResumeForBody {
                expression,
                statements,
                tail,
                parent_scope,
                block_scope,
                index,
                outer_names,
                item,
                item_inserted,
                source,
                baseline,
            });
        self.loop_depth += 1;
        if item_inserted && consuming && owned_record_item {
            self.owned_iterator_items.push(item.to_owned());
        }
        self.frames
            .push(crate::source_verify::scope::VerifierFrame::Enter {
                expression: body,
                scope: block_scope,
            });
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_for_body(
        &mut self,
        expression: &'p Expr,
        statements: &'p [Statement],
        tail: &'p Expr,
        parent_scope: usize,
        block_scope: usize,
        index: usize,
        outer_names: Vec<String>,
        item: &str,
        item_inserted: bool,
        source: Option<&str>,
        baseline: Option<HashMap<String, Binding>>,
    ) -> Result<(), Diagnostic> {
        let _ = self.values.pop();
        self.loop_depth = self.loop_depth.saturating_sub(1);
        if item_inserted
            && self
                .owned_iterator_items
                .last()
                .is_some_and(|active| active == item)
        {
            self.owned_iterator_items.pop();
        }
        if let Some(row) = self.scopes[block_scope]
            .bindings
            .get(item)
            .and_then(|binding| binding.traversal_row.as_deref())
            .cloned()
        {
            if let Some(owner) = self.scopes[block_scope].bindings.get_mut(&row.root) {
                owner.active_loans.retain(|loan| loan.id != row.freeze);
            }
        }
        if let Statement::For { values, body, .. } = &statements[index] {
            crate::source_verify::byte_traversal::release(
                &mut self.scopes[block_scope].bindings,
                &crate::source_verify::byte_traversal::freeze_id(item, values.span, body.span),
            );
        }
        let index_inserted = self.scopes[block_scope]
            .bindings
            .get(item)
            .and_then(|binding| binding.traversal_row.as_deref())
            .is_some_and(|row| row.index_inserted);
        if item_inserted {
            self.scopes[block_scope].bindings.remove(item);
        }
        if let Statement::ForBorrow {
            index: Some(selected),
            ..
        } = &statements[index]
        {
            // Remove only a successfully inserted index. A hostile collision
            // leaves the authoritative outer binding in place.
            if index_inserted {
                self.scopes[block_scope].bindings.remove(&selected.name);
            }
        }
        if let Some(baseline) = baseline {
            if statements[index]
                .child(1)
                .is_some_and(crate::ast::returns_only)
            {
                for (name, binding) in &baseline {
                    self.scopes[block_scope]
                        .bindings
                        .insert(name.clone(), binding.clone());
                }
            }

            let mut names = baseline.keys().collect::<Vec<_>>();
            names.sort();
            for name in names {
                let before = &baseline[name];
                if self.scopes[block_scope]
                    .bindings
                    .get(name)
                    .is_none_or(|after| {
                        after.availability != before.availability
                            || after.moved_places != before.moved_places
                            || after.definitely_partial != before.definitely_partial
                    })
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T252",
                        format!("ownership of `{name}` changes inside a for own loop"),
                        statements[index]
                            .child(1)
                            .map_or(Span::default(), |body| body.span),
                    ));
                }
            }
        }
        if let Some(source) = source {
            let changed = self.scopes[block_scope]
                .bindings
                .get(source)
                .is_none_or(|after| {
                    after.availability != Availability::Available
                        || !after.moved_places.is_empty()
                        || !after.definitely_partial.is_empty()
                });
            if changed {
                self.diagnostics.push(error(
                    self.program, "SPX-T284",
                    format!("for traversal source `{source}` cannot be consumed or mutated in the loop body"),
                    statements[index].child(1).map_or(Span::default(), |body| body.span),
                ));
            }
        }
        self.advance_block_statement(
            expression,
            statements,
            tail,
            parent_scope,
            block_scope,
            index,
            outer_names,
        );
        Ok(())
    }

    pub(super) fn frame_resume_block_tail(
        &mut self,
        parent_scope: usize,
        block_scope: usize,
        outer_names: Vec<String>,
    ) -> Result<(), Diagnostic> {
        if block_scope + 1 != self.scopes.len() {
            return Err(Diagnostic::io(
                "SPX-H006",
                "block verifier scope is not the active child",
            ));
        }
        let actual = self.values.pop().unwrap_or(None);
        let block_bindings = self
            .scopes
            .pop()
            .expect("active block scope index checked above")
            .bindings;
        merge_moved(
            &mut self.scopes[parent_scope].bindings,
            &block_bindings,
            &outer_names,
        );
        self.values.push(actual);
        Ok(())
    }
}

//! Unary, binary, and `if` frames: operand resumption, lazy boolean
//! operands, and the branch joins that follow them.

use crate::ast::{BinaryOp, Expr, ExprKind, Type, UnaryOp};
use crate::diagnostic::Diagnostic;
use crate::source_verify::binding::{Availability, Binding, CheckedValue};
use crate::source_verify::diagnostics::{
    error, reject_aggregate_equality, reject_native_unit_value,
};
use crate::source_verify::hints;
use crate::source_verify::loans::join_conditional;
use crate::source_verify::place::{join_definitely_partial, join_moved_places};
use crate::source_verify::private_names::type_name;
use crate::source_verify::scope::{VerifierFrame, VerifierScope};
use crate::source_verify::IterativeVerifier;
use std::collections::HashMap;

impl<'a, 'p> IterativeVerifier<'a, 'p> {
    pub(super) fn frame_resume_unary(
        &mut self,
        expression: &'p Expr,
        operand: &'p Expr,
        op: UnaryOp,
    ) -> Result<(), Diagnostic> {
        let Some(actual) = self.values.pop().flatten() else {
            self.values.push(None);
            return Ok(());
        };
        let numeric = matches!(op, UnaryOp::Neg)
            .then(|| actual.ty.clone())
            .filter(|ty| matches!(ty, Type::I64 | Type::I32 | Type::F32 | Type::F64));
        let expected = match (&op, &numeric) {
            (UnaryOp::Neg, Some(ty)) => ty.clone(),
            (UnaryOp::Neg, None) => Type::I64,
            (UnaryOp::Not, _) => Type::Bool,
        };
        if !actual.native_unit && actual.ty != expected {
            self.diagnostics.push(error(
                self.program,
                "SPX-T206",
                format!("unary operator expects {expected}, received {}", actual.ty),
                expression.span,
            ));
        }
        reject_native_unit_value(self.program, operand, &actual, self.diagnostics);
        self.values.push(Some(CheckedValue::value(expected)));
        Ok(())
    }

    pub(super) fn frame_resume_binary_left(
        &mut self,
        expression: &'p Expr,
        op: BinaryOp,
        right: &'p Expr,
        scope: usize,
    ) -> Result<(), Diagnostic> {
        let left_value = self.values.pop().unwrap_or(None);
        let lazy = matches!(op, BinaryOp::And | BinaryOp::Or);
        let baseline_names = if lazy {
            self.scopes[scope]
                .bindings
                .keys()
                .cloned()
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        let evaluated_scope = if lazy {
            let index = self.scopes.len();
            self.scopes.push(VerifierScope {
                bindings: self.scopes[scope].bindings.clone(),
                local_borrow_count: self.scopes[scope].local_borrow_count,
            });
            index
        } else {
            scope
        };
        let left = match &expression.kind {
            ExprKind::Binary { left, .. } => left.as_ref(),
            _ => unreachable!(),
        };
        self.frames.push(VerifierFrame::ResumeBinaryRight {
            expression,
            op,
            left,
            left_value,
            scope,
            evaluated_scope,
            baseline_names,
        });
        self.frames.push(VerifierFrame::Enter {
            expression: right,
            scope: evaluated_scope,
        });
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_binary_right(
        &mut self,
        expression: &'p Expr,
        op: BinaryOp,
        left: &'p Expr,
        left_value: Option<CheckedValue>,
        scope: usize,
        evaluated_scope: usize,
        baseline_names: Vec<String>,
    ) -> Result<(), Diagnostic> {
        let right_value = self.values.pop().unwrap_or(None);
        if evaluated_scope != scope {
            if evaluated_scope + 1 != self.scopes.len() {
                return Err(Diagnostic::io(
                    "SPX-H006",
                    "lazy verifier scope is not the active child",
                ));
            }
            let evaluated = self
                .scopes
                .pop()
                .expect("active lazy scope index checked above")
                .bindings;
            join_conditional(
                &mut self.scopes[scope].bindings,
                &evaluated,
                &baseline_names,
            );
        }
        if let Some(value) = &left_value {
            reject_native_unit_value(self.program, left, value, self.diagnostics);
        }
        let right = match &expression.kind {
            ExprKind::Binary { right, .. } => right.as_ref(),
            _ => unreachable!(),
        };
        if let Some(value) = &right_value {
            reject_native_unit_value(self.program, right, value, self.diagnostics);
        }
        let native_unit = left_value.as_ref().is_some_and(|value| value.native_unit)
            || right_value.as_ref().is_some_and(|value| value.native_unit);
        let left_ordered = left_value
            .as_ref()
            .map(|value| value.ty.clone())
            .filter(|ty| {
                matches!(
                    ty,
                    Type::I64
                        | Type::I32
                        | Type::Char
                        | Type::U8
                        | Type::Usize
                        | Type::F32
                        | Type::F64
                        | Type::String
                )
            });
        let left_narrow = left_value
            .as_ref()
            .map(|value| value.ty.clone())
            .filter(|ty| matches!(ty, Type::U8));
        let left_usize = left_value
            .as_ref()
            .map(|value| value.ty.clone())
            .filter(|ty| matches!(ty, Type::Usize));
        let left_numeric = left_value
            .as_ref()
            .map(|value| value.ty.clone())
            .filter(|ty| matches!(ty, Type::F32 | Type::F64));
        let left_integer = left_value
            .as_ref()
            .map(|value| value.ty.clone())
            .filter(|ty| matches!(ty, Type::I32));
        if !native_unit && matches!(op, BinaryOp::Rem) && left_numeric.is_some() {
            self.diagnostics.push(error(
                self.program,
                "SPX-T208",
                format!("operator `{}` expects i64 operands", op.text()),
                expression.span,
            ));
        }
        let string_operands = left_value
            .as_ref()
            .is_some_and(|value| value.ty == Type::String)
            || right_value
                .as_ref()
                .is_some_and(|value| value.ty == Type::String);
        if !native_unit
            && !matches!(
                op,
                BinaryOp::Eq
                    | BinaryOp::Ne
                    | BinaryOp::Lt
                    | BinaryOp::Le
                    | BinaryOp::Gt
                    | BinaryOp::Ge
            )
            && string_operands
        {
            self.diagnostics.push(
                error(
                    self.program,
                    "SPX-T250",
                    format!("operator `{}` does not support string operands", op.text()),
                    expression.span,
                )
                .with_help(crate::source_verify::hints::STRING_OPERATOR_HELP),
            );
        }
        let (expected, output) = match op {
            BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul | BinaryOp::Div | BinaryOp::Rem => {
                let expected = left_numeric
                    .clone()
                    .or(left_integer)
                    .or(left_narrow)
                    .or(left_usize)
                    .unwrap_or(Type::I64);
                (expected.clone(), expected)
            }
            BinaryOp::Lt | BinaryOp::Le | BinaryOp::Gt | BinaryOp::Ge => {
                let expected = left_ordered.unwrap_or(Type::I64);
                (expected, Type::Bool)
            }
            BinaryOp::And | BinaryOp::Or => (Type::Bool, Type::Bool),
            BinaryOp::Eq | BinaryOp::Ne => {
                if let Some(value) = &left_value {
                    reject_aggregate_equality(
                        self.program,
                        self.types,
                        expression,
                        value,
                        self.diagnostics,
                    );
                }
                if !native_unit
                    && left_value.is_some()
                    && right_value.is_some()
                    && left_value.as_ref().map(|value| &value.ty)
                        != right_value.as_ref().map(|value| &value.ty)
                {
                    self.diagnostics.push(hints::with_optional_help(
                        error(
                            self.program,
                            "SPX-T207",
                            "equality operands must have the same type",
                            expression.span,
                        ),
                        hints::equality_types_help(
                            left_value.as_ref().map(|value| &value.ty),
                            right_value.as_ref().map(|value| &value.ty),
                            left,
                            right,
                        ),
                    ));
                }
                self.values.push(Some(CheckedValue::value(Type::Bool)));
                return Ok(());
            }
        };
        if !native_unit
            && (!string_operands
                || matches!(
                    op,
                    BinaryOp::Lt | BinaryOp::Le | BinaryOp::Gt | BinaryOp::Ge
                ))
            && (left_value
                .as_ref()
                .is_some_and(|value| value.ty != expected)
                || right_value
                    .as_ref()
                    .is_some_and(|value| value.ty != expected))
        {
            self.diagnostics.push(hints::with_optional_help(
                error(
                    self.program,
                    "SPX-T208",
                    format!("operator `{}` expects {expected} operands", op.text()),
                    expression.span,
                ),
                hints::literal_suffix_help(&expected, left, right),
            ));
        }
        self.values.push(Some(CheckedValue::value(output)));
        Ok(())
    }

    pub(super) fn frame_resume_if_condition(
        &mut self,
        expression: &'p Expr,
        then_branch: &'p Expr,
        else_branch: &'p Expr,
        scope: usize,
    ) -> Result<(), Diagnostic> {
        let condition_value = self.values.pop().unwrap_or(None);
        let condition = match &expression.kind {
            ExprKind::If { condition, .. } => condition.as_ref(),
            _ => unreachable!(),
        };
        if let Some(value) = condition_value {
            if value.native_unit {
                reject_native_unit_value(self.program, condition, &value, self.diagnostics);
            } else if value.ty != Type::Bool {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T210",
                    "`if` condition must be bool",
                    condition.span,
                ));
            }
        }
        // Empty blocks containing only a scalar literal cannot inspect or
        // mutate any binding. Check both literal values normally, but avoid
        // copying and joining the complete environment for this identity case.
        let literal_tail = |branch: &'p Expr| match &branch.kind {
            ExprKind::Block { statements, tail }
                if statements.is_empty()
                    && matches!(tail.kind, ExprKind::Int(_) | ExprKind::Bool(_)) =>
            {
                Some(tail.as_ref())
            }
            _ => None,
        };
        if let (Some(then_tail), Some(else_tail)) =
            (literal_tail(then_branch), literal_tail(else_branch))
        {
            self.frames.push(VerifierFrame::ResumeLiteralIf {
                expression,
                then_branch,
                else_branch,
            });
            self.frames.push(VerifierFrame::Enter {
                expression: else_tail,
                scope,
            });
            self.frames.push(VerifierFrame::Enter {
                expression: then_tail,
                scope,
            });
            return Ok(());
        }
        let baseline_names = self.scopes[scope]
            .bindings
            .keys()
            .cloned()
            .collect::<Vec<_>>();
        let then_scope = self.scopes.len();
        self.scopes.push(VerifierScope {
            bindings: self.scopes[scope].bindings.clone(),
            local_borrow_count: self.scopes[scope].local_borrow_count,
        });
        self.frames.push(VerifierFrame::ResumeIfThen {
            expression,
            else_branch,
            scope,
            then_scope,
            baseline_names,
        });
        self.frames.push(VerifierFrame::Enter {
            expression: then_branch,
            scope: then_scope,
        });
        Ok(())
    }

    pub(super) fn frame_resume_if_then(
        &mut self,
        expression: &'p Expr,
        else_branch: &'p Expr,
        scope: usize,
        then_scope: usize,
        baseline_names: Vec<String>,
    ) -> Result<(), Diagnostic> {
        if then_scope + 1 != self.scopes.len() {
            return Err(Diagnostic::io(
                "SPX-H006",
                "then verifier scope is not the active child",
            ));
        }
        let then_value = self.values.pop().unwrap_or(None);
        let then_bindings = self
            .scopes
            .pop()
            .expect("active then scope index checked above")
            .bindings;
        let else_scope = self.scopes.len();
        self.scopes.push(VerifierScope {
            bindings: self.scopes[scope].bindings.clone(),
            local_borrow_count: self.scopes[scope].local_borrow_count,
        });
        let then_branch = match &expression.kind {
            ExprKind::If { then_branch, .. } => then_branch.as_ref(),
            _ => unreachable!(),
        };
        self.frames.push(VerifierFrame::ResumeIfElse {
            expression,
            then_branch,
            else_branch,
            scope,
            else_scope,
            baseline_names,
            then_value,
            then_bindings,
        });
        self.frames.push(VerifierFrame::Enter {
            expression: else_branch,
            scope: else_scope,
        });
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_if_else(
        &mut self,
        expression: &'p Expr,
        then_branch: &'p Expr,
        else_branch: &'p Expr,
        scope: usize,
        else_scope: usize,
        baseline_names: Vec<String>,
        then_value: Option<CheckedValue>,
        then_bindings: HashMap<String, Binding>,
    ) -> Result<(), Diagnostic> {
        if else_scope + 1 != self.scopes.len() {
            return Err(Diagnostic::io(
                "SPX-H006",
                "else verifier scope is not the active child",
            ));
        }
        let else_value = self.values.pop().unwrap_or(None);
        let else_bindings = self
            .scopes
            .pop()
            .expect("active else scope index checked above")
            .bindings;
        let then_exits = then_value
            .as_ref()
            .is_some_and(|value| value.ty == Type::Never)
            && crate::ast::returns_only(then_branch);
        let else_exits = else_value
            .as_ref()
            .is_some_and(|value| value.ty == Type::Never)
            && crate::ast::returns_only(else_branch);
        for name in &baseline_names {
            if let Some(binding) = self.scopes[scope].bindings.get_mut(name) {
                if then_exits != else_exits {
                    let normal = if then_exits {
                        &else_bindings
                    } else {
                        &then_bindings
                    };
                    if let Some(state) = normal.get(name) {
                        *binding = state.clone();
                    }
                    continue;
                }
                let then_state = then_bindings
                    .get(name)
                    .map_or(Availability::Available, |value| value.availability);
                let else_state = else_bindings
                    .get(name)
                    .map_or(Availability::Available, |value| value.availability);
                binding.availability = then_state.join(else_state);
                if let (Some(then_binding), Some(else_binding)) =
                    (then_bindings.get(name), else_bindings.get(name))
                {
                    binding.active_loans = then_binding
                        .active_loans
                        .union(&else_binding.active_loans)
                        .cloned()
                        .collect();
                    binding.moved_places = join_moved_places(then_binding, else_binding);
                    binding.definitely_partial =
                        join_definitely_partial(then_binding, else_binding);
                }
            }
        }
        self.finish_if_values(expression, then_branch, else_branch, then_value, else_value);
        Ok(())
    }

    pub(super) fn finish_if_values(
        &mut self,
        expression: &Expr,
        then_branch: &Expr,
        else_branch: &Expr,
        then_value: Option<CheckedValue>,
        else_value: Option<CheckedValue>,
    ) {
        let output = match (then_value, else_value) {
            (Some(then_value), Some(else_value)) if then_value.ty == Type::Never => {
                Some(else_value)
            }
            (Some(then_value), Some(else_value)) if else_value.ty == Type::Never => {
                Some(then_value)
            }
            (Some(then_value), Some(else_value)) => {
                if then_value.native_unit || else_value.native_unit {
                    reject_native_unit_value(
                        self.program,
                        then_branch,
                        &then_value,
                        self.diagnostics,
                    );
                    reject_native_unit_value(
                        self.program,
                        else_branch,
                        &else_value,
                        self.diagnostics,
                    );
                } else if then_value.ty != else_value.ty {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T211",
                        format!(
                            "`if` branches return different types: {} and {}",
                            type_name(self.program, self.types, &then_value.ty),
                            type_name(self.program, self.types, &else_value.ty)
                        ),
                        expression.span,
                    ));
                }
                if self.types.needs_drop(&then_value.ty) && then_value.mode != else_value.mode {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-O106",
                        "`if` branches must produce the same resource ownership mode",
                        expression.span,
                    ));
                }
                Some(then_value)
            }
            _ => None,
        };
        self.values.push(output);
    }
}

//! Record, variant, and record-update construction frames: per-field
//! preparation and resumption.

use crate::ast::{
    Expr, FieldDeclaration, ParamMode, Type, TypeDeclaration, VariantCaseDeclaration,
};
use crate::diagnostic::Diagnostic;
use crate::source_verify::binding::CheckedValue;
use crate::source_verify::diagnostics::{error, reject_native_unit_value};
use crate::source_verify::loans::mark_value_sources_moved;
use crate::source_verify::place::source_place;
use crate::source_verify::scope::VerifierFrame;
use crate::source_verify::type_table::{effective_record_fields, TypeTable};
use crate::source_verify::IterativeVerifier;
use std::collections::HashSet;

impl<'a, 'p> IterativeVerifier<'a, 'p> {
    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_prepare_record_field(
        &mut self,
        expression: &'p Expr,
        type_name: &'p str,
        type_arguments: &'p [Type],
        fields: &'p [crate::ast::FieldInitializer],
        declared_fields: Option<&'p [FieldDeclaration]>,
        scope: usize,
        index: usize,
        mut supplied: HashSet<&'p str>,
    ) -> Result<(), Diagnostic> {
        let field = &fields[index];
        let declared = self
            .types
            .declared_field(type_name, &field.name)
            .or_else(|| {
                declared_fields.and_then(|declared| {
                    declared
                        .iter()
                        .find(|candidate| candidate.name == field.name)
                })
            });
        if !supplied.insert(field.name.as_str()) || declared.is_none() {
            self.diagnostics.push(error(
                self.program,
                "SPX-T212",
                format!(
                    "unknown or duplicate field `{}` in `{type_name}` construction",
                    field.name
                ),
                field.span,
            ));
        }
        self.frames.push(VerifierFrame::ResumeRecordField {
            expression,
            type_name,
            type_arguments,
            fields,
            declared_fields,
            scope,
            index,
            supplied,
        });
        self.frames.push(VerifierFrame::Enter {
            expression: &field.value,
            scope,
        });
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_record_field(
        &mut self,
        expression: &'p Expr,
        type_name: &'p str,
        type_arguments: &'p [Type],
        fields: &'p [crate::ast::FieldInitializer],
        declared_fields: Option<&'p [FieldDeclaration]>,
        scope: usize,
        index: usize,
        supplied: HashSet<&'p str>,
    ) -> Result<(), Diagnostic> {
        let actual = self.values.pop().unwrap_or(None);
        let field = &fields[index];
        let declared = self
            .types
            .declared_field(type_name, &field.name)
            .or_else(|| {
                declared_fields.and_then(|declared| {
                    declared
                        .iter()
                        .find(|candidate| candidate.name == field.name)
                })
            });
        if let (Some(declared), Some(actual)) = (declared, actual) {
            reject_native_unit_value(self.program, &field.value, &actual, self.diagnostics);
            let expected = self
                .types
                .declaration(type_name)
                .and_then(|declaration| {
                    TypeTable::substitute_variant_type(declaration, type_arguments, &declared.ty)
                })
                .unwrap_or_else(|| declared.ty.clone());
            if actual.ty != expected {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T215",
                    format!(
                        "field `{}.{}` expects {}, received {}",
                        type_name, field.name, expected, actual.ty
                    ),
                    field.value.span,
                ));
            }
            if self.types.needs_drop(&expected) && actual.mode == ParamMode::Own {
                if self.allow_moves {
                    mark_value_sources_moved(
                        self.program,
                        &field.value,
                        &mut self.scopes[scope].bindings,
                        self.types,
                        self.diagnostics,
                    );
                } else {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-O105",
                        "contract expression cannot transfer an owned record field",
                        field.value.span,
                    ));
                }
            } else if self.types.needs_drop(&expected)
                && matches!(actual.mode, ParamMode::Borrow | ParamMode::Shared)
            {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-O108",
                    "cannot move an owned field through a borrowed or shared record",
                    field.value.span,
                ));
            }
        }
        let next = index + 1;
        if fields.get(next).is_some() {
            self.frames.push(VerifierFrame::PrepareRecordField {
                expression,
                type_name,
                type_arguments,
                fields,
                declared_fields,
                scope,
                index: next,
                supplied,
            });
        } else {
            if let Some(declared_fields) = declared_fields {
                for field in declared_fields {
                    if !supplied.contains(field.name.as_str()) {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T213",
                            format!(
                                "record `{type_name}` construction is missing field `{}`",
                                field.name
                            ),
                            expression.span,
                        ));
                    }
                }
                let instance = Type::Named {
                    name: type_name.to_owned(),
                    arguments: type_arguments.to_vec(),
                };
                crate::source_verify::declared_type::string_record::reject(
                    self.program,
                    &instance,
                    "constructed",
                    expression.span,
                    self.types,
                    self.diagnostics,
                );
                self.values.push(Some(CheckedValue::returned(
                    instance.clone(),
                    self.types.needs_drop(&instance),
                )));
            } else {
                self.values.push(None);
            }
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_prepare_variant_field(
        &mut self,
        expression: &'p Expr,
        type_name: &'p str,
        type_arguments: &'p [Type],
        case_name: &'p str,
        fields: &'p [crate::ast::FieldInitializer],
        declaration: Option<&'p TypeDeclaration>,
        case: Option<&'p VariantCaseDeclaration>,
        scope: usize,
        index: usize,
        mut supplied: HashSet<&'p str>,
    ) -> Result<(), Diagnostic> {
        let field = &fields[index];
        let declared = case.and_then(|case| {
            case.fields
                .iter()
                .find(|candidate| candidate.name == field.name)
        });
        if !supplied.insert(field.name.as_str()) || (case.is_some() && declared.is_none()) {
            self.diagnostics.push(error(self.program, "SPX-T212", format!("unknown or duplicate payload field `{}` in `{type_name}::{case_name}` construction", field.name), field.span));
        }
        self.frames.push(VerifierFrame::ResumeVariantField {
            expression,
            type_name,
            type_arguments,
            case_name,
            fields,
            declaration,
            case,
            scope,
            index,
            supplied,
        });
        self.frames.push(VerifierFrame::Enter {
            expression: &field.value,
            scope,
        });
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_variant_field(
        &mut self,
        expression: &'p Expr,
        type_name: &'p str,
        type_arguments: &'p [Type],
        case_name: &'p str,
        fields: &'p [crate::ast::FieldInitializer],
        declaration: Option<&'p TypeDeclaration>,
        case: Option<&'p VariantCaseDeclaration>,
        scope: usize,
        index: usize,
        supplied: HashSet<&'p str>,
    ) -> Result<(), Diagnostic> {
        let actual = self.values.pop().unwrap_or(None);
        let field = &fields[index];
        let declared = case.and_then(|case| {
            case.fields
                .iter()
                .find(|candidate| candidate.name == field.name)
        });
        if let (Some(declaration), Some(declared), Some(actual)) = (declaration, declared, actual) {
            reject_native_unit_value(self.program, &field.value, &actual, self.diagnostics);
            let expected =
                TypeTable::substitute_variant_type(declaration, type_arguments, &declared.ty)
                    .unwrap_or_else(|| declared.ty.clone());
            if actual.ty != expected {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T215",
                    format!(
                        "payload `{}::{}.{}` expects {}, received {}",
                        type_name, case_name, field.name, expected, actual.ty
                    ),
                    field.value.span,
                ));
            }
            if self.types.needs_drop(&expected) && actual.mode == ParamMode::Own {
                if self.allow_moves {
                    mark_value_sources_moved(
                        self.program,
                        &field.value,
                        &mut self.scopes[scope].bindings,
                        self.types,
                        self.diagnostics,
                    );
                } else {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-O105",
                        "contract expression cannot transfer an owned variant payload",
                        field.value.span,
                    ));
                }
            } else if self.types.needs_drop(&expected)
                && matches!(actual.mode, ParamMode::Borrow | ParamMode::Shared)
            {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-O108",
                    "cannot move an owned variant payload through a borrowed or shared value",
                    field.value.span,
                ));
            }
        }
        let next = index + 1;
        if fields.get(next).is_some() {
            self.frames.push(VerifierFrame::PrepareVariantField {
                expression,
                type_name,
                type_arguments,
                case_name,
                fields,
                declaration,
                case,
                scope,
                index: next,
                supplied,
            });
        } else {
            if let Some(case) = case {
                for field in &case.fields {
                    if !supplied.contains(field.name.as_str()) {
                        self.diagnostics.push(error(self.program, "SPX-T213", format!("variant construction `{type_name}::{case_name}` is missing payload field `{}`", field.name), expression.span));
                    }
                }
                let instance = Type::Named {
                    name: type_name.to_owned(),
                    arguments: type_arguments.to_vec(),
                };
                self.values.push(Some(CheckedValue::returned(
                    instance.clone(),
                    self.types.needs_drop(&instance),
                )));
            } else if declaration.is_some() {
                let instance = Type::Named {
                    name: type_name.to_owned(),
                    arguments: type_arguments.to_vec(),
                };
                self.values.push(Some(CheckedValue::returned(
                    instance.clone(),
                    self.types.needs_drop(&instance),
                )));
            } else {
                self.values.push(None);
            }
        }
        Ok(())
    }

    pub(super) fn frame_resume_update_base(
        &mut self,
        expression: &'p Expr,
        base: &'p Expr,
        fields: &'p [crate::ast::FieldInitializer],
        scope: usize,
    ) -> Result<(), Diagnostic> {
        let Some(base_value) = self.values.pop().flatten() else {
            self.values.push(None);
            return Ok(());
        };
        reject_native_unit_value(self.program, base, &base_value, self.diagnostics);
        if crate::source_verify::declared_type::collection_record::admitted(
            &base_value.ty,
            self.types,
        ) {
            self.diagnostics.push(error(
                self.program,
                "SPX-T268",
                "Vec-bearing record update is outside the nested collection-record profile",
                expression.span,
            ));
            self.values.push(None);
            return Ok(());
        }
        let Some(declared_fields) = effective_record_fields(self.types, &base_value.ty) else {
            self.diagnostics.push(error(
                self.program,
                "SPX-T215",
                format!(
                    "record update requires a record base, received {}",
                    base_value.ty
                ),
                base.span,
            ));
            self.values.push(None);
            return Ok(());
        };
        let nested_update = (self.types.is_nested_owned_byte_record(&base_value.ty)
            && !self.types.is_flat_owned_byte_record(&base_value.ty))
            || crate::source_verify::declared_type::string_record::admitted(
                &base_value.ty,
                self.types,
            );
        if nested_update
            && source_place(base, &self.scopes[scope].bindings, self.types)
                .is_none_or(|place| !place.projections.is_empty())
        {
            self.diagnostics.push(error(
                self.program,
                "SPX-O117",
                "nested owned-record update requires an exact named owned base place",
                expression.span,
            ));
        }
        if self.types.needs_drop(&base_value.ty) {
            match base_value.mode {
                ParamMode::Own if self.allow_moves => mark_value_sources_moved(
                    self.program,
                    base,
                    &mut self.scopes[scope].bindings,
                    self.types,
                    self.diagnostics,
                ),
                ParamMode::Own => self.diagnostics.push(error(
                    self.program,
                    "SPX-O105",
                    "contract expression cannot transfer an owned record update base",
                    base.span,
                )),
                ParamMode::Borrow | ParamMode::Shared => self.diagnostics.push(error(
                    self.program,
                    "SPX-O108",
                    "cannot update an owned record through a borrowed or shared base",
                    base.span,
                )),
                ParamMode::Value => {}
            }
        }
        if !fields.is_empty() {
            self.frames.push(VerifierFrame::PrepareUpdateField {
                expression,
                base_type: base_value.ty,
                fields,
                declared_fields,
                scope,
                index: 0,
                supplied: HashSet::new(),
            });
        } else {
            self.values.push(Some(CheckedValue::returned(
                base_value.ty.clone(),
                self.types.needs_drop(&base_value.ty),
            )));
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_prepare_update_field(
        &mut self,
        expression: &'p Expr,
        base_type: Type,
        fields: &'p [crate::ast::FieldInitializer],
        declared_fields: &'p [FieldDeclaration],
        scope: usize,
        index: usize,
        mut supplied: HashSet<&'p str>,
    ) -> Result<(), Diagnostic> {
        let field = &fields[index];
        let declared = declared_fields
            .iter()
            .find(|candidate| candidate.name == field.name);
        if !supplied.insert(field.name.as_str()) || declared.is_none() {
            self.diagnostics.push(error(
                self.program,
                "SPX-T212",
                format!(
                    "unknown or duplicate field `{}` in `{}` update",
                    field.name, base_type
                ),
                field.span,
            ));
        }
        self.frames.push(VerifierFrame::ResumeUpdateField {
            expression,
            base_type,
            fields,
            declared_fields,
            scope,
            index,
            supplied,
        });
        self.frames.push(VerifierFrame::Enter {
            expression: &field.value,
            scope,
        });
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_update_field(
        &mut self,
        expression: &'p Expr,
        base_type: Type,
        fields: &'p [crate::ast::FieldInitializer],
        declared_fields: &'p [FieldDeclaration],
        scope: usize,
        index: usize,
        supplied: HashSet<&'p str>,
    ) -> Result<(), Diagnostic> {
        let actual = self.values.pop().unwrap_or(None);
        let field = &fields[index];
        let declared = declared_fields
            .iter()
            .find(|candidate| candidate.name == field.name);
        if let (Some(declared), Some(actual)) = (declared, actual) {
            reject_native_unit_value(self.program, &field.value, &actual, self.diagnostics);
            let expected = self
                .types
                .record_field_type(&base_type, declared)
                .unwrap_or_else(|| declared.ty.clone());
            if actual.ty != expected {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T215",
                    format!(
                        "field `{}.{}` expects {}, received {}",
                        base_type, field.name, expected, actual.ty
                    ),
                    field.value.span,
                ));
            }
            if self.types.needs_drop(&expected) && actual.mode == ParamMode::Own {
                if self.allow_moves {
                    mark_value_sources_moved(
                        self.program,
                        &field.value,
                        &mut self.scopes[scope].bindings,
                        self.types,
                        self.diagnostics,
                    );
                } else {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-O105",
                        "contract expression cannot transfer an owned record replacement",
                        field.value.span,
                    ));
                }
            } else if self.types.needs_drop(&expected)
                && matches!(actual.mode, ParamMode::Borrow | ParamMode::Shared)
            {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-O108",
                    "cannot move an owned replacement through a borrowed or shared value",
                    field.value.span,
                ));
            }
        }
        let next = index + 1;
        if fields.get(next).is_some() {
            self.frames.push(VerifierFrame::PrepareUpdateField {
                expression,
                base_type,
                fields,
                declared_fields,
                scope,
                index: next,
                supplied,
            });
        } else {
            self.values.push(Some(CheckedValue::returned(
                base_type.clone(),
                self.types.needs_drop(&base_type),
            )));
        }
        Ok(())
    }
}

//! Record, variant, and scalar match arm frames: per-arm scope handling and
//! the joins that produce the match's value.

use crate::ast::{MatchMode, MatchPattern, ParamMode, Type};
use crate::diagnostic::Diagnostic;
use crate::source_verify::binding::{Availability, Binding};
use crate::source_verify::declared_type::generic_function_has_owned_record_composition;
use crate::source_verify::diagnostics::{
    error, reject_aggregate_match_result, reject_native_unit_value, source_identifier,
};
use crate::source_verify::loans::merge_moved;
use crate::source_verify::place::{join_definitely_partial, join_moved_places};
use crate::source_verify::private_names::{missing_case, type_name};
use crate::source_verify::scope::{
    ScalarMatchState, VariantMatchState, VerifierFrame, VerifierScope,
};
use crate::source_verify::type_table::TypeTable;
use crate::source_verify::variant_or::{
    check_variant_or_pattern, VariantOrContext, AGGREGATE_REFUTABLE_HELP,
};
use crate::source_verify::IterativeVerifier;
use std::collections::{BTreeSet, HashMap, HashSet};

impl<'a, 'p> IterativeVerifier<'a, 'p> {
    pub(super) fn frame_resume_record_match_arm(
        &mut self,
        arm: &'p crate::ast::MatchArm,
        parent_scope: usize,
        arm_scope: usize,
        outer_names: Vec<String>,
        owns_record_input: bool,
    ) -> Result<(), Diagnostic> {
        if arm_scope + 1 != self.scopes.len() {
            return Err(Diagnostic::io(
                "SPX-H006",
                "record match arm scope is not the active child",
            ));
        }
        let result = self.values.pop().unwrap_or(None);
        if let Some(value) = &result {
            reject_native_unit_value(self.program, &arm.value, value, self.diagnostics);
        }
        let arm_bindings = self
            .scopes
            .pop()
            .expect("record arm scope is active")
            .bindings;
        merge_moved(
            &mut self.scopes[parent_scope].bindings,
            &arm_bindings,
            &outer_names,
        );
        let generic_template = self.functions.get(self.current.name.as_str()).copied();
        let generic_owned_result = generic_template.is_some_and(|function| {
            generic_function_has_owned_record_composition(function, self.types)
        });
        if result.as_ref().is_some_and(|value| {
            value.ty!=Type::Never && (!matches!(value.ty, Type::I64 | Type::Bool) || value.mode != ParamMode::Value)
                && !(generic_template.is_some_and(|function| function.type_parameters.is_empty())
                    && (value.mode == ParamMode::Value || owns_record_input)
                    && crate::source_verify::declared_type::ordinary_record_match_result(&value.ty, value.mode, self.types))
                && !(generic_owned_result
                    && (((value.ty == self.current.return_type || (self.types.is_nested_owned_byte_record(&value.ty) || crate::source_verify::declared_type::string_record::runtime_admitted(&value.ty, self.types))) && value.mode == ParamMode::Own)
                        || (value.mode == ParamMode::Value
                            && (crate::source_verify::type_table::owned_byte_record_copy_field_is_admitted(&value.ty)
                                || matches!(&value.ty, Type::Named { name, arguments }
                                    if arguments.is_empty() && generic_template.is_some_and(|function| function.type_parameters.iter().any(|parameter| parameter.name == *name)))))))
        }) {
            self.diagnostics.push(error(
                self.program,
                "SPX-T216",
                "record match arm must return a Copy i64 or bool value",
                arm.value.span,
            ));
            self.values.push(None);
        } else {
            self.values.push(result);
        }
        Ok(())
    }

    pub(super) fn frame_prepare_variant_match_arm(
        &mut self,
        mut state: VariantMatchState<'p>,
    ) -> Result<(), Diagnostic> {
        if state.index >= state.arms.len() {
            if !state.wildcard_seen {
                if let (Some(variant_name), Some(cases)) =
                    (&state.variant_name, state.declared_cases)
                {
                    if let Some(missing) = cases
                        .iter()
                        .find(|case| !state.covered.contains(&case.name))
                    {
                        self.diagnostics.push(missing_case(
                            self.program,
                            self.types,
                            variant_name,
                            &missing.name,
                            !missing.fields.is_empty(),
                            state.expression.span,
                        ));
                    }
                }
            }
            if let Some((first, rest)) = state.arm_states.split_first() {
                let mut joined = first.clone();
                for branch in rest {
                    for name in &state.outer_names {
                        if let (Some(joined_binding), Some(branch_binding)) =
                            (joined.get_mut(name), branch.get(name))
                        {
                            joined_binding.availability = joined_binding
                                .availability
                                .join(branch_binding.availability);
                            joined_binding.moved_places =
                                join_moved_places(joined_binding, branch_binding);
                            joined_binding.definitely_partial =
                                join_definitely_partial(joined_binding, branch_binding);
                        }
                    }
                }
                merge_moved(
                    &mut self.scopes[state.parent_scope].bindings,
                    &joined,
                    &state.outer_names,
                );
            }
            self.values.push(state.result);
            return Ok(());
        }
        let arm = &state.arms[state.index];
        let arm_scope = self.scopes.len();
        self.scopes.push(VerifierScope {
            bindings: state.baseline.clone(),
            local_borrow_count: state
                .baseline
                .values()
                .filter(|binding| binding.borrow_origin.is_some())
                .count(),
        });
        match &arm.pattern {
            MatchPattern::Wildcard { span } => {
                if state.mode != MatchMode::Value {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-O117",
                        "explicit ownership variant match requires every case pattern",
                        *span,
                    ));
                }
                if state.wildcard_seen
                    || state
                        .declared_cases
                        .is_some_and(|cases| state.covered.len() == cases.len())
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-M102",
                        "unreachable wildcard match arm",
                        *span,
                    ));
                }
                state.wildcard_seen = arm.guard.is_none();
            }
            MatchPattern::Variant {
                type_name,
                case_name,
                fields,
                span,
                ..
            } => {
                let compatible = state.variant_name.as_deref() == Some(type_name);
                let declared_case = compatible
                    .then_some(state.declared_cases)
                    .flatten()
                    .and_then(|cases| cases.iter().find(|case| case.name == *case_name));
                if declared_case.is_none() {
                    let diagnostic = error(
                        self.program,
                        "SPX-M103",
                        format!("pattern `{type_name}::{case_name}` is incompatible with the match scrutinee"),
                        *span,
                    );
                    self.diagnostics.push(
                        match compatible
                            .then_some(state.declared_cases)
                            .flatten()
                            .and_then(|cases| {
                                crate::source_verify::hints::nearest_variant_case_name(
                                    case_name, cases,
                                )
                            }) {
                            Some(nearest) => diagnostic.with_help(format!(
                                "did you mean `{type_name}::{nearest} {{ ... }}`?"
                            )),
                            None => diagnostic,
                        },
                    );
                } else if state.wildcard_seen
                    || state.covered.contains(case_name)
                    || (arm.guard.is_none() && !state.covered.insert(case_name.clone()))
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-M102",
                        format!("unreachable duplicate case `{type_name}::{case_name}`"),
                        *span,
                    ));
                }
                let mut supplied = HashSet::new();
                let mut bindings = HashSet::new();
                for field in fields {
                    let declared_field = declared_case.and_then(|case| {
                        case.fields
                            .iter()
                            .find(|candidate| candidate.name == field.name)
                    });
                    if !supplied.insert(field.name.as_str())
                        || (declared_case.is_some() && declared_field.is_none())
                    {
                        self.diagnostics.push(error(self.program, "SPX-M104", format!("unknown or duplicate pattern field `{}` in `{type_name}::{case_name}`", field.name), field.span));
                    }
                    if !source_identifier(&field.binding)
                        || !bindings.insert(field.binding.as_str())
                        || self.scopes[arm_scope].bindings.contains_key(&field.binding)
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-M104",
                            format!("invalid or duplicate pattern binding `{}`", field.binding),
                            field.binding_span,
                        ));
                        continue;
                    }
                    if let Some(declared_field) = declared_field {
                        let binding_ty = state
                            .variant_name
                            .as_ref()
                            .and_then(|name| {
                                self.types.declaration(name).and_then(|declaration| {
                                    TypeTable::substitute_variant_type(
                                        declaration,
                                        &state.variant_arguments,
                                        &declared_field.ty,
                                    )
                                })
                            })
                            .unwrap_or_else(|| declared_field.ty.clone());
                        let binding_mode = if self.types.needs_drop(&binding_ty) {
                            match state.mode {
                                MatchMode::Own => ParamMode::Own,
                                MatchMode::Borrow => ParamMode::Borrow,
                                MatchMode::Value => ParamMode::Value,
                            }
                        } else {
                            ParamMode::Value
                        };
                        self.scopes[arm_scope].bindings.insert(
                            field.binding.clone(),
                            Binding {
                                contract_local: false,
                                traversal_row: None,
                                ty: binding_ty,
                                mode: binding_mode,
                                availability: Availability::Available,
                                moved_places: HashMap::new(),
                                definitely_partial: HashSet::new(),
                                native_unit_discard: false,
                                mutable: false,
                                active_loans: BTreeSet::new(),
                                borrow_origin: None,
                            },
                        );
                    }
                }
                if let Some(declared_case) = declared_case {
                    for field in &declared_case.fields {
                        if !supplied.contains(field.name.as_str()) {
                            self.diagnostics.push(error(self.program, "SPX-M104", format!("pattern `{type_name}::{case_name}` is missing payload field `{}`", field.name), *span));
                        }
                    }
                }
            }
            MatchPattern::Record { span, .. } => self.diagnostics.push(error(
                self.program,
                "SPX-M103",
                "record pattern is incompatible with a variant scrutinee",
                *span,
            )),
            MatchPattern::Or { alternatives, span } => {
                let context = VariantOrContext {
                    variant_name: state.variant_name.as_deref(),
                    declared_cases: state.declared_cases,
                    mode: state.mode,
                    wildcard_seen: state.wildcard_seen,
                };
                let mut covered = state.covered.clone();
                check_variant_or_pattern(
                    self.program,
                    alternatives,
                    *span,
                    &context,
                    &mut |case| covered.insert(case.to_owned()),
                    self.diagnostics,
                );
                if arm.guard.is_none() {
                    state.covered = covered;
                }
            }
            MatchPattern::Literal { span, .. } | MatchPattern::Binding { span, .. } => {
                self.diagnostics.push(
                    error(
                        self.program,
                        "SPX-T254",
                        "refutable patterns are incompatible with an aggregate variant \
                         scrutinee",
                        *span,
                    )
                    .with_help(AGGREGATE_REFUTABLE_HELP),
                );
            }
        }
        let next = if let Some(guard) = &arm.guard {
            if !crate::source_verify::variant_guards::guard_shape(
                guard,
                &self.scopes[arm_scope].bindings,
            ) {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T254",
                    "Copy variant guards require an ordinary Boolean expression without yield, closure, unsafe or residual propagation",
                    guard.span,
                ));
            }
            state.guard_pending = true;
            guard.as_ref()
        } else {
            &arm.value
        };
        self.frames
            .push(VerifierFrame::ResumeVariantMatchArm { state, arm_scope });
        self.frames.push(VerifierFrame::Enter {
            expression: next,
            scope: arm_scope,
        });
        Ok(())
    }

    pub(super) fn frame_resume_variant_match_arm(
        &mut self,
        mut state: VariantMatchState<'p>,
        arm_scope: usize,
    ) -> Result<(), Diagnostic> {
        if arm_scope + 1 != self.scopes.len() {
            return Err(Diagnostic::io(
                "SPX-H006",
                "variant match arm scope is not the active child",
            ));
        }
        let arm = &state.arms[state.index];
        if state.guard_pending {
            let guard_value = self.values.pop().unwrap_or(None);
            if let Some(value) = guard_value {
                if value.ty != Type::Bool || value.mode != ParamMode::Value {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T256",
                        format!("match guard must be bool; received {}", value.ty),
                        arm.guard.as_ref().expect("guard retained").span,
                    ));
                }
            }
            if !crate::source_verify::variant_guards::ownership_unchanged(
                &state.baseline,
                &self.scopes[arm_scope].bindings,
            ) {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T254",
                    "Copy variant guard changes surrounding ownership",
                    arm.guard.as_ref().expect("guard retained").span,
                ));
            }
            state.guard_pending = false;
            self.frames
                .push(VerifierFrame::ResumeVariantMatchArm { state, arm_scope });
            self.frames.push(VerifierFrame::Enter {
                expression: &arm.value,
                scope: arm_scope,
            });
            return Ok(());
        }
        let arm_value = self.values.pop().unwrap_or(None);
        let exits = arm_value
            .as_ref()
            .is_some_and(|value| value.ty == Type::Never)
            && crate::ast::returns_only(&arm.value);
        let collection_result = |ty: &Type, mode: ParamMode| {
            state.variant_name.as_ref().is_some_and(|name| {
                crate::source_verify::declared_type::collection_outcome::match_result(
                    self.types,
                    &Type::Named {
                        name: name.clone(),
                        arguments: state.variant_arguments.clone(),
                    },
                    state.mode,
                    ty,
                    mode,
                )
            })
        };
        if let Some(value) = &arm_value {
            reject_native_unit_value(self.program, &arm.value, value, self.diagnostics);
            if value.ty != Type::Never
                && !collection_result(&value.ty, value.mode)
                && !crate::source_verify::declared_type::generic_variant::match_result(
                    self.functions.get(self.current.name.as_str()).copied(),
                    self.types,
                    state.mode,
                    &value.ty,
                    value.mode,
                )
            {
                reject_aggregate_match_result(self.program, &arm.value, value, self.diagnostics);
            }
        }
        if let Some(arm_value) = arm_value {
            if arm_value.ty != Type::Never
                && state.needs_drop
                && !collection_result(&arm_value.ty, arm_value.mode)
                && !crate::source_verify::declared_type::generic_variant::match_result(
                    self.functions.get(self.current.name.as_str()).copied(),
                    self.types,
                    state.mode,
                    &arm_value.ty,
                    arm_value.mode,
                )
                && (state.mode == MatchMode::Value
                    || !matches!(arm_value.ty, Type::I64 | Type::Bool)
                    || arm_value.mode != ParamMode::Value)
            {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T216",
                    "owned variant match arms must return a Copy i64 or bool value",
                    arm.value.span,
                ));
            }
            if let Some(expected) = &state.result {
                if expected.ty != Type::Never
                    && arm_value.ty != Type::Never
                    && (expected.ty != arm_value.ty || expected.mode != arm_value.mode)
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T216",
                        format!(
                            "match arms return incompatible values: {} and {}",
                            type_name(self.program, self.types, &expected.ty),
                            type_name(self.program, self.types, &arm_value.ty)
                        ),
                        arm.value.span,
                    ));
                }
            }
            if state
                .result
                .as_ref()
                .is_none_or(|value| value.ty == Type::Never)
            {
                state.result = Some(arm_value);
            }
        }
        let bindings = self
            .scopes
            .pop()
            .expect("variant arm scope is active")
            .bindings;
        if !exits {
            state.arm_states.push(bindings);
        }
        state.index += 1;
        self.frames
            .push(VerifierFrame::PrepareVariantMatchArm(state));
        Ok(())
    }

    pub(super) fn frame_prepare_scalar_match_arm(
        &mut self,
        state: ScalarMatchState<'p>,
    ) -> Result<(), Diagnostic> {
        if state.index >= state.arms.len() {
            if let Some((first, rest)) = state.arm_states.split_first() {
                let mut joined = first.clone();
                for branch in rest {
                    for name in &state.outer_names {
                        if let (Some(joined_binding), Some(branch_binding)) =
                            (joined.get_mut(name), branch.get(name))
                        {
                            joined_binding.availability = joined_binding
                                .availability
                                .join(branch_binding.availability);
                            joined_binding.moved_places =
                                join_moved_places(joined_binding, branch_binding);
                            joined_binding.definitely_partial =
                                join_definitely_partial(joined_binding, branch_binding);
                        }
                    }
                }
                merge_moved(
                    &mut self.scopes[state.parent_scope].bindings,
                    &joined,
                    &state.outer_names,
                );
            }
            self.values.push(state.result);
            return Ok(());
        }
        let arm = &state.arms[state.index];
        let arm_scope = self.scopes.len();
        self.scopes.push(VerifierScope {
            bindings: state.baseline.clone(),
            local_borrow_count: state
                .baseline
                .values()
                .filter(|binding| binding.borrow_origin.is_some())
                .count(),
        });
        match &arm.pattern {
            MatchPattern::Wildcard { .. } => {}
            MatchPattern::Binding { name, span } => {
                if !source_identifier(name) || self.scopes[arm_scope].bindings.contains_key(name) {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-M104",
                        format!("invalid or duplicate pattern binding `{name}`"),
                        *span,
                    ));
                } else {
                    self.scopes[arm_scope].bindings.insert(
                        name.clone(),
                        Binding {
                            contract_local: false,
                            traversal_row: None,
                            ty: state.scrutinee_ty.clone(),
                            mode: ParamMode::Value,
                            availability: Availability::Available,
                            moved_places: HashMap::new(),
                            definitely_partial: HashSet::new(),
                            native_unit_discard: false,
                            mutable: false,
                            active_loans: BTreeSet::new(),
                            borrow_origin: None,
                        },
                    );
                }
            }
            // Literal/or diagnostics fired during admission; the
            // arm value still checks so downstream errors stay
            // deterministic.
            _ => {}
        }
        match &arm.guard {
            Some(guard) => {
                self.frames
                    .push(VerifierFrame::ResumeScalarMatchGuard { state, arm_scope });
                self.frames.push(VerifierFrame::Enter {
                    expression: guard.as_ref(),
                    scope: arm_scope,
                });
            }
            None => {
                self.frames
                    .push(VerifierFrame::ResumeScalarMatchArm { state, arm_scope });
                self.frames.push(VerifierFrame::Enter {
                    expression: &arm.value,
                    scope: arm_scope,
                });
            }
        }
        Ok(())
    }

    pub(super) fn frame_resume_scalar_match_guard(
        &mut self,
        state: ScalarMatchState<'p>,
        arm_scope: usize,
    ) -> Result<(), Diagnostic> {
        if arm_scope + 1 != self.scopes.len() {
            return Err(Diagnostic::io(
                "SPX-H006",
                "scalar match guard scope is not the active child",
            ));
        }
        let guard_value = self.values.pop().unwrap_or(None);
        let arm = &state.arms[state.index];
        if let Some(value) = &guard_value {
            if value.ty != Type::Bool || value.mode != ParamMode::Value {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T256",
                    format!("match guard must be bool; received {}", value.ty),
                    arm.guard.as_ref().map_or(arm.span, |guard| guard.span),
                ));
            }
        }
        // The arm value observes the guard's moves within this
        // arm only.
        self.frames
            .push(VerifierFrame::ResumeScalarMatchArm { state, arm_scope });
        self.frames.push(VerifierFrame::Enter {
            expression: &arm.value,
            scope: arm_scope,
        });
        Ok(())
    }

    pub(super) fn frame_resume_scalar_match_arm(
        &mut self,
        mut state: ScalarMatchState<'p>,
        arm_scope: usize,
    ) -> Result<(), Diagnostic> {
        if arm_scope + 1 != self.scopes.len() {
            return Err(Diagnostic::io(
                "SPX-H006",
                "scalar match arm scope is not the active child",
            ));
        }
        let arm = &state.arms[state.index];
        let arm_value = self.values.pop().unwrap_or(None);
        let exits = arm_value
            .as_ref()
            .is_some_and(|value| value.ty == Type::Never)
            && crate::ast::returns_only(&arm.value);
        if let Some(value) = &arm_value {
            reject_native_unit_value(self.program, &arm.value, value, self.diagnostics);
            reject_aggregate_match_result(self.program, &arm.value, value, self.diagnostics);
        }
        if let Some(arm_value) = arm_value {
            if let Some(expected) = &state.result {
                if expected.ty != Type::Never
                    && arm_value.ty != Type::Never
                    && (expected.ty != arm_value.ty || expected.mode != arm_value.mode)
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T259",
                        format!(
                            "match arms return incompatible values: {} and {}",
                            type_name(self.program, self.types, &expected.ty),
                            type_name(self.program, self.types, &arm_value.ty)
                        ),
                        arm.value.span,
                    ));
                }
            }
            if state
                .result
                .as_ref()
                .is_none_or(|value| value.ty == Type::Never)
            {
                state.result = Some(arm_value);
            }
        }
        let bindings = self
            .scopes
            .pop()
            .expect("scalar arm scope is active")
            .bindings;
        if !exits {
            state.arm_states.push(bindings);
        }
        state.index += 1;
        self.frames
            .push(VerifierFrame::PrepareScalarMatchArm(state));
        Ok(())
    }
}

//! Test-only recursive checking of call and method-call expressions.

use crate::ast::program_source::ProgramSource;
use crate::ast::{Expr, Function, ImportResult, Param, ParamMode, Type};
use crate::diagnostic::Diagnostic;
use crate::source_verify::arguments::{
    activate_borrowed_bytes_call_loans, check_argument_ownership, release_borrowed_bytes_call_loans,
};
use crate::source_verify::binding::{Binding, CheckedValue};
use crate::source_verify::declared_type::{
    generic_function_arguments_are_admitted, generic_function_arguments_are_forwarded,
    validation_specialize_function,
};
use crate::source_verify::diagnostics::{error, reject_native_unit_value};
use crate::source_verify::hints;
use crate::source_verify::oracle::check_expr;
use crate::source_verify::type_table::{resolve_class_method, TypeTable};
use std::collections::HashMap;

#[allow(clippy::too_many_arguments, clippy::ptr_arg)]
pub(super) fn oracle_call(
    name: &String,
    type_arguments: &Vec<Type>,
    args: &Vec<Expr>,
    program: &dyn ProgramSource,
    current: &Function,
    expr: &Expr,
    variables: &mut HashMap<String, Binding>,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    result_type: Option<&Type>,
    allow_moves: bool,
    diagnostics: &mut Vec<Diagnostic>,
) -> Option<CheckedValue> {
    if let Some(result) = crate::source_verify::owning_closure::check_call(
        program,
        name,
        type_arguments,
        args,
        expr.span,
        allow_moves,
        variables,
        types,
        diagnostics,
    ) {
        return result;
    }
    // Independently check the readonly byte vocabulary used by normalization.
    if let Some(op) = crate::byte_ops::by_name(name).filter(|op| {
        matches!(
            op,
            crate::byte_ops::ByteOp::Len
                | crate::byte_ops::ByteOp::Range
                | crate::byte_ops::ByteOp::BytesAsSlice
        )
    }) {
        if !type_arguments.is_empty() {
            diagnostics.push(error(
                program,
                "SPX-T263",
                format!("byte operation `{name}` does not accept type arguments"),
                expr.span,
            ));
        }
        if args.len() != op.arity() {
            diagnostics.push(error(
                program,
                "SPX-T263",
                format!(
                    "byte operation `{name}` expects {} arguments, received {}",
                    op.arity(),
                    args.len()
                ),
                expr.span,
            ));
        }
        if op.is_view()
            && args.first().is_none_or(|argument| {
                !crate::source_verify::arguments::source_byte_view_place_is_admitted(
                    op, argument, variables, types,
                )
            })
        {
            let diagnostic = error(
                program,
                "SPX-T266",
                format!("borrowed view `{name}` requires an exact admitted storage place"),
                expr.span,
            );
            diagnostics.push(match args.first() {
                Some(argument) => diagnostic.with_help(hints::view_place_help(name, argument)),
                None => diagnostic,
            });
        }
        for (index, argument) in args.iter().enumerate() {
            if let Some(actual) = check_expr(
                program,
                current,
                argument,
                variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            ) {
                reject_native_unit_value(program, argument, &actual, diagnostics);
                if !actual.native_unit && !op.accepts_ast(index, &actual.ty) {
                    diagnostics.push(hints::with_optional_help(
                        error(
                            program,
                            "SPX-T263",
                            format!("byte operation `{name}` argument {index} has the wrong type"),
                            argument.span,
                        ),
                        hints::view_argument_help(name, &actual.ty),
                    ));
                }
            }
        }
        return Some(CheckedValue::returned(op.ast_return_type(), false));
    }
    if crate::stdin_stream_ops::pure_by_name(name).is_some()
        || crate::stdin_stream_ops::host_by_name(name).is_some()
    {
        return super::stdin_stream::check_call(
            name,
            type_arguments,
            args,
            program,
            current,
            expr,
            variables,
            functions,
            types,
            result_type,
            allow_moves,
            diagnostics,
        );
    }
    if let Some(binding_type) = variables.get(name.as_str()).map(|binding| {
        crate::source_verify::mutable_closure::invocation_signature(
            program,
            binding,
            name,
            args,
            allow_moves,
            expr.span,
            diagnostics,
        )
    }) {
        let Type::Function { parameters, result } = binding_type else {
            diagnostics.push(error(
                program,
                "SPX-T287",
                format!("`{name}` is a bound value, not a function value"),
                expr.span,
            ));
            return None;
        };
        if !type_arguments.is_empty() {
            diagnostics.push(error(
                program,
                "SPX-T225",
                "function values do not accept type arguments",
                expr.span,
            ));
        }
        if args.len() != parameters.len() {
            diagnostics.push(error(
                program,
                "SPX-T204",
                format!(
                    "`{name}` expects {} arguments, received {}",
                    parameters.len(),
                    args.len()
                ),
                expr.span,
            ));
        }
        let params = parameters
            .into_iter()
            .enumerate()
            .map(|(index, ty)| Param {
                name: format!("argument{index}"),
                mode: ParamMode::Value,
                ty,
                span: expr.span,
            })
            .collect::<Vec<_>>();
        for (index, arg) in args.iter().enumerate() {
            let actual = check_expr(
                program,
                current,
                arg,
                variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            );
            let Some(param) = params.get(index) else {
                continue;
            };
            if let Some(actual) = actual
                .as_ref()
                .filter(|actual| !actual.native_unit && actual.ty != param.ty)
            {
                diagnostics.push(hints::with_optional_help(
                    error(
                        program,
                        "SPX-T205",
                        format!(
                            "argument `{}` to `{name}` expects {}, received {}",
                            param.name, param.ty, actual.ty
                        ),
                        arg.span,
                    ),
                    hints::argument_view_help(name, &param.ty, &actual.ty),
                ));
            }
            check_argument_ownership(
                program,
                current,
                name,
                arg,
                param,
                actual.as_ref(),
                variables,
                types,
                allow_moves,
                false,
                false,
                diagnostics,
            );
        }
        return Some(CheckedValue::returned(*result, false));
    }
    let args = if name == crate::vec_ops::sort_keys::NAME {
        if !current.type_parameters.is_empty()
            || crate::source_verify::sort_keys::descriptor(types, type_arguments, args).is_none()
        {
            diagnostics.push(error(program,"SPX-T311","vec_sort_by requires an explicit monomorphic record and 1..8 unique literal field:asc/field:desc keys",expr.span));
            return None;
        }
        &args[..1]
    } else if name == crate::vec_ops::field_unique::NAME {
        if !current.type_parameters.is_empty()
            || crate::source_verify::field_unique::descriptor(
                types,
                type_arguments,
                args,
                variables,
            )
            .is_none()
        {
            diagnostics.push(error(
                program,
                "SPX-T319",
                crate::vec_ops::field_unique::SHAPE,
                expr.span,
            ));
            return None;
        }
        &args[..1]
    } else {
        args
    };
    if let Some(op) = crate::vec_ops::by_name(name) {
        if op == crate::vec_ops::VecOp::StrAt
            && (!current.type_parameters.is_empty()
                || crate::source_verify::string_slot::root(type_arguments, args, variables)
                    .is_none())
        {
            diagnostics.push(error(
                program,
                "SPX-T281",
                crate::vec_ops::string_slot::SHAPE,
                expr.span,
            ));
        }
        let element = if op == crate::vec_ops::VecOp::StrAt {
            Some(&Type::String)
        } else {
            type_arguments.first()
        };
        if (if op == crate::vec_ops::VecOp::StrAt {
            !type_arguments.is_empty()
        } else {
            type_arguments.len() != 1
        }) || element.is_none_or(|ty| {
            !crate::source_verify::declared_type::owned_leaf_collection::vec_operation_admitted(
                types, op, ty,
            ) && !crate::vec_ops::source_parameter_is_admitted(program, current, op, ty)
        }) {
            diagnostics.push(error(
                program,
                "SPX-T281",
                format!("vector operation `{name}` requires one explicit admitted type argument"),
                expr.span,
            ));
        }
        if args.len() != op.arity() {
            diagnostics.push(error(
                program,
                "SPX-T281",
                format!(
                    "vector operation `{name}` expects {} arguments, received {}",
                    op.arity(),
                    args.len()
                ),
                expr.span,
            ));
        }
        if op.capacity_argument().is_some_and(|index| {
            matches!(args.get(index).map(|arg| &arg.kind), Some(crate::ast::ExprKind::Usize(value)) if *value > crate::vec_ops::MAX_CAPACITY)
        })
        {
            diagnostics.push(error(
                program,
                "SPX-T282",
                format!(
                    "`{name}` literal capacity must be no greater than {}",
                    crate::vec_ops::MAX_CAPACITY
                ),
                expr.span,
            ));
        }
        let params = element
            .map(|element| {
                crate::vec_ops::ast_params_with_owned_element(
                    op,
                    element,
                    *element == crate::ast::Type::Bytes
                        || crate::source_verify::declared_type::owned_leaf_collection::admitted(types, element)
                        || crate::source_verify::declared_type::owned_leaf_collection::runtime_element(types, element),
                )
            })
            .unwrap_or_default();
        for (index, arg) in args.iter().enumerate() {
            let actual = check_expr(
                program,
                current,
                arg,
                variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            );
            let Some(param) = params.get(index) else {
                continue;
            };
            if let Some(actual) = actual.as_ref().filter(|actual| actual.ty != param.ty) {
                diagnostics.push(error(
                    program,
                    "SPX-T205",
                    format!(
                        "argument `{}` to `{name}` expects {}, received {}",
                        param.name, param.ty, actual.ty
                    ),
                    arg.span,
                ));
            }
            check_argument_ownership(
                program,
                current,
                name,
                arg,
                param,
                actual.as_ref(),
                variables,
                types,
                allow_moves,
                false,
                false,
                diagnostics,
            );
        }
        return element.map(|element| {
            if op == crate::vec_ops::VecOp::StrAt {
                CheckedValue {
                    ty: Type::Str,
                    mode: ParamMode::Borrow,
                    native_unit: false,
                }
            } else {
                CheckedValue::returned(op.ast_return_type(element), op.returns_owner())
            }
        });
    }
    if let Some(op) = crate::list_ops::by_name(name) {
        if !type_arguments.is_empty() || args.len() != op.argument_count() {
            diagnostics.push(error(
                program,
                "SPX-T291",
                format!(
                    "immutable list operation `{name}` requires {} arguments and no type arguments",
                    op.argument_count()
                ),
                expr.span,
            ));
        }
        let params = op.ast_params();
        for (index, arg) in args.iter().enumerate() {
            let actual = check_expr(
                program,
                current,
                arg,
                variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            );
            let Some(param) = params.get(index) else {
                continue;
            };
            if let Some(actual) = actual.as_ref().filter(|actual| actual.ty != param.ty) {
                diagnostics.push(error(
                    program,
                    "SPX-T205",
                    format!(
                        "argument `{}` to `{name}` expects {}, received {}",
                        param.name, param.ty, actual.ty
                    ),
                    arg.span,
                ));
            }
            check_argument_ownership(
                program,
                current,
                name,
                arg,
                param,
                actual.as_ref(),
                variables,
                types,
                allow_moves,
                false,
                false,
                diagnostics,
            );
        }
        return Some(CheckedValue::returned(op.ast_return_type(), false));
    }
    if let Some(op) = crate::iterator_ops::by_name(name) {
        let element = type_arguments.first();
        if type_arguments.len() != 1
            || element.is_none_or(|ty| {
                !crate::iterator_ops::ast_element_is_admitted(ty)
                    && !crate::source_verify::declared_type::owned_leaf_collection::runtime_element(
                        types, ty,
                    )
            })
        {
            diagnostics.push(error(
                program,
                "SPX-T290",
                format!("iterator operation `{name}` requires one explicit admitted type argument"),
                expr.span,
            ));
        }
        if args.len() != 1 {
            diagnostics.push(error(
                program,
                "SPX-T290",
                format!(
                    "iterator operation `{name}` expects 1 argument, received {}",
                    args.len()
                ),
                expr.span,
            ));
        }
        let params = element
            .map(|element| crate::iterator_ops::ast_params(op, element))
            .unwrap_or_default();
        for (index, arg) in args.iter().enumerate() {
            let actual = check_expr(
                program,
                current,
                arg,
                variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            );
            let Some(param) = params.get(index) else {
                continue;
            };
            if let Some(actual) = actual.as_ref().filter(|actual| actual.ty != param.ty) {
                diagnostics.push(error(
                    program,
                    "SPX-T205",
                    format!(
                        "argument `{}` to `{name}` expects {}, received {}",
                        param.name, param.ty, actual.ty
                    ),
                    arg.span,
                ));
            }
            check_argument_ownership(
                program,
                current,
                name,
                arg,
                param,
                actual.as_ref(),
                variables,
                types,
                allow_moves,
                false,
                false,
                diagnostics,
            );
        }
        return element.map(|element| CheckedValue::returned(op.ast_return_type(element), true));
    }
    if let Some(op) = crate::box_ops::by_name(name) {
        let element = type_arguments.first();
        if type_arguments.len() != 1
            || element.is_none_or(|ty| {
                !crate::box_ops::ast_operation_element_is_admitted(op, ty)
                    && !crate::box_ops::source_parameter_is_admitted(program, current, op, ty)
            })
        {
            diagnostics.push(error(
                program,
                "SPX-T285",
                format!("box operation `{name}` requires one explicit admitted type argument"),
                expr.span,
            ));
        }
        if args.len() != 1 {
            diagnostics.push(error(
                program,
                "SPX-T285",
                format!(
                    "box operation `{name}` expects 1 argument, received {}",
                    args.len()
                ),
                expr.span,
            ));
        }
        let params = element
            .map(|element| crate::box_ops::ast_params(op, element))
            .unwrap_or_default();
        for (index, arg) in args.iter().enumerate() {
            let actual = check_expr(
                program,
                current,
                arg,
                variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            );
            let Some(param) = params.get(index) else {
                continue;
            };
            if let Some(actual) = actual.as_ref().filter(|actual| actual.ty != param.ty) {
                diagnostics.push(error(
                    program,
                    "SPX-T205",
                    format!(
                        "argument `{}` to `{name}` expects {}, received {}",
                        param.name, param.ty, actual.ty
                    ),
                    arg.span,
                ));
            }
            check_argument_ownership(
                program,
                current,
                name,
                arg,
                param,
                actual.as_ref(),
                variables,
                types,
                allow_moves,
                false,
                false,
                diagnostics,
            );
        }
        return element.map(|element| {
            CheckedValue::returned(
                op.ast_return_type(element),
                op == crate::box_ops::BoxOp::New || *element == Type::Bytes,
            )
        });
    }
    if name == crate::vec_field::NAME {
        let Some((params, ty)) =
            crate::source_verify::vec_field::signature(types, type_arguments, args, expr.span)
        else {
            diagnostics.push(error(program,"SPX-T310","vec_field requires one admitted owned record type, a named Vec and usize index, and an exact literal field selector",expr.span));
            return None;
        };
        if !current.type_parameters.is_empty() {
            diagnostics.push(error(
                program,
                "SPX-T310",
                "vec_field is not admitted in generic function templates",
                expr.span,
            ));
        }
        let loans = activate_borrowed_bytes_call_loans(program, args, &params, variables, types);
        for (arg, param) in args.iter().zip(&params) {
            let actual = check_expr(
                program,
                current,
                arg,
                variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            );
            if let Some(actual) = &actual {
                reject_native_unit_value(program, arg, actual, diagnostics);
                if actual.ty != param.ty {
                    diagnostics.push(error(
                        program,
                        "SPX-T205",
                        "vec_field argument type differs",
                        arg.span,
                    ));
                }
            }
            check_argument_ownership(
                program,
                current,
                name,
                arg,
                param,
                actual.as_ref(),
                variables,
                types,
                allow_moves,
                false,
                false,
                diagnostics,
            );
        }
        release_borrowed_bytes_call_loans(variables, &loans);
        let mode = if matches!(ty, Type::Str | Type::SliceU8) {
            ParamMode::Borrow
        } else {
            ParamMode::Value
        };
        return Some(CheckedValue {
            ty,
            mode,
            native_unit: false,
        });
    }
    if name == crate::literal_format::NAME {
        if !type_arguments.is_empty() || !current.type_parameters.is_empty() {
            diagnostics.push(error(
                program,
                "SPX-T225",
                "string_format is admitted only in monomorphic functions without type arguments",
                expr.span,
            ));
        }
        let Some(Expr {
            kind: crate::ast::ExprKind::String(template),
            ..
        }) = args.first()
        else {
            diagnostics.push(error(
                program,
                "SPX-T204",
                "string_format requires a compile-time string literal as its first argument",
                expr.span,
            ));
            return None;
        };
        match crate::literal_format::scan(template) {
            Ok(pieces) if crate::literal_format::field_count(&pieces) != args.len() - 1 => {
                diagnostics.push(error(
                    program,
                    "SPX-T204",
                    format!(
                        "string_format literal has {} fields, received {} values",
                        crate::literal_format::field_count(&pieces),
                        args.len() - 1
                    ),
                    expr.span,
                ))
            }
            Err(reason) => {
                diagnostics.push(error(program, "SPX-T204", reason.message(), args[0].span))
            }
            _ => {}
        }
        for (index, arg) in args.iter().enumerate().skip(1) {
            let actual = check_expr(
                program,
                current,
                arg,
                variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            );
            if let Some(actual) = actual {
                reject_native_unit_value(program, arg, &actual, diagnostics);
                if !actual.native_unit && !crate::literal_format::accepts_ast_type(&actual.ty) {
                    diagnostics.push(error(
                        program,
                        "SPX-T205",
                        format!(
                            "string_format value {} must be i64, u8, usize, bool, or own string",
                            index - 1
                        ),
                        arg.span,
                    ));
                }
                let parameter = Param {
                    name: format!("value{}", index - 1),
                    mode: if actual.ty == Type::String {
                        ParamMode::Own
                    } else {
                        ParamMode::Value
                    },
                    ty: actual.ty.clone(),
                    span: arg.span,
                };
                check_argument_ownership(
                    program,
                    current,
                    name,
                    arg,
                    &parameter,
                    Some(&actual),
                    variables,
                    types,
                    allow_moves,
                    false,
                    false,
                    diagnostics,
                );
            }
        }
        return Some(CheckedValue::returned(Type::String, true));
    }
    if crate::map_ops::by_generic_name(name, type_arguments).is_some()
        || crate::string_ops::by_name(name).is_some()
        || crate::str_ops::by_name(name).is_some()
    {
        return super::intrinsic_calls::check_call(
            name,
            type_arguments,
            args,
            program,
            current,
            expr,
            variables,
            functions,
            types,
            result_type,
            allow_moves,
            diagnostics,
        );
    }
    let native_import = program
        .interfaces()
        .iter()
        .flat_map(|interface| &interface.imports)
        .find(|import| import.native_rust && import.name == *name);
    if let Some(import) = native_import {
        if !type_arguments.is_empty() || args.len() != import.params.len() {
            diagnostics.push(error(
                program,
                "SPX-B107",
                "Native Rust Interop declaration set is unsupported: scalar value signature required",
                expr.span,
            ));
        }
        for effect in &import.effects {
            if !current.effects.contains(effect) {
                diagnostics.push(error(
                    program,
                    "SPX-B107",
                    "Native Rust Interop declaration set is unsupported: effect or capability mismatch",
                    expr.span,
                ));
            }
        }
        for (index, argument) in args.iter().enumerate() {
            let actual = check_expr(
                program,
                current,
                argument,
                variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            );
            if let (Some(actual), Some(parameter)) = (actual, import.params.get(index)) {
                reject_native_unit_value(program, argument, &actual, diagnostics);
                check_argument_ownership(
                    program,
                    current,
                    name,
                    argument,
                    parameter,
                    Some(&actual),
                    variables,
                    types,
                    allow_moves,
                    false,
                    false,
                    diagnostics,
                );
                if !actual.native_unit
                    && (actual.ty != parameter.ty
                        || (actual.mode != parameter.mode
                            && !(parameter.mode == ParamMode::Borrow
                                && actual.mode == ParamMode::Own
                                && matches!(&argument.kind, crate::ast::ExprKind::Var(_)))))
                {
                    diagnostics.push(error(
                        program,
                        "SPX-B107",
                        "Native Rust Interop declaration set is unsupported: scalar value signature required",
                        argument.span,
                    ));
                }
            }
        }
        let native_unit = import.result == ImportResult::Unit;
        let mut checked =
            CheckedValue::returned(import.result.value_type(), import.result.is_owned());
        checked.native_unit = native_unit;
        if import.result.is_borrowed() {
            checked.mode = ParamMode::Borrow;
        }
        return Some(checked);
    }
    // The condition profile needs the reserved non-transferring Len signature
    // in the recursive oracle as well as the iterative verifier.
    if crate::string_ops::by_name(name) == Some(crate::string_ops::StringOp::Len) {
        let params = crate::string_ops::ast_params(crate::string_ops::StringOp::Len);
        if !type_arguments.is_empty() {
            diagnostics.push(error(
                program,
                "SPX-T225",
                format!("monomorphic function `{name}` does not accept type arguments"),
                expr.span,
            ));
        }
        if args.len() != params.len() {
            diagnostics.push(error(
                program,
                "SPX-T204",
                format!(
                    "`{name}` expects {} arguments, received {}",
                    params.len(),
                    args.len()
                ),
                expr.span,
            ));
        }
        for (index, arg) in args.iter().enumerate() {
            let actual = check_expr(
                program,
                current,
                arg,
                variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            );
            let Some(param) = params.get(index) else {
                continue;
            };
            if let Some(actual) = &actual {
                reject_native_unit_value(program, arg, actual, diagnostics);
            }
            if let Some(actual) = actual
                .as_ref()
                .filter(|actual| !actual.native_unit && actual.ty != param.ty)
            {
                diagnostics.push(hints::with_optional_help(
                    error(
                        program,
                        "SPX-T205",
                        format!(
                            "argument `{}` to `{name}` expects {}, received {}",
                            param.name, param.ty, actual.ty
                        ),
                        arg.span,
                    ),
                    hints::argument_view_help(name, &param.ty, &actual.ty),
                ));
            }
            check_argument_ownership(
                program,
                current,
                name,
                arg,
                param,
                actual.as_ref(),
                variables,
                types,
                allow_moves,
                false,
                false,
                diagnostics,
            );
        }
        return Some(CheckedValue::returned(Type::I64, false));
    }
    let target = functions.get(name.as_str()).copied();
    if target.is_none() {
        diagnostics.push(hints::unknown_function(program, name, functions, expr.span));
    }
    if target.is_some_and(|target| args.len() != target.params.len()) {
        let target = target.expect("checked above");
        diagnostics.push(error(
            program,
            "SPX-T204",
            format!(
                "`{name}` expects {} arguments, received {}",
                target.params.len(),
                args.len()
            ),
            expr.span,
        ));
    }
    let specialized_target = target.and_then(|target| {
        if target.type_parameters.is_empty() {
            if !type_arguments.is_empty() {
                diagnostics.push(error(
                    program,
                    "SPX-T225",
                    format!("monomorphic function `{name}` does not accept type arguments"),
                    expr.span,
                ));
                return None;
            }
            return Some(target.clone());
        }
        let inferred_arguments;
        let type_arguments = if type_arguments.is_empty() {
            inferred_arguments = crate::source_verify::generic_inference::arguments(
                program, current, target, args, variables, functions, types,
            );
            inferred_arguments.as_deref().unwrap_or(type_arguments)
        } else {
            type_arguments
        };
        if type_arguments.len() != target.type_parameters.len() {
            diagnostics.push(
                error(
                    program,
                    "SPX-T225",
                    format!(
                        "generic function `{name}` expects {} explicit type arguments, received {}",
                        target.type_parameters.len(),
                        type_arguments.len()
                    ),
                    expr.span,
                )
                .with_help(hints::generic_call_help(name)),
            );
            return None;
        }
        if !generic_function_arguments_are_admitted(target, type_arguments, types)
            && !generic_function_arguments_are_forwarded(current, target, type_arguments)
            && !crate::vec_ops::source_arguments_are_admitted(program, target, type_arguments)
            && !crate::box_ops::source_arguments_are_admitted(program, target, type_arguments)
        {
            diagnostics.push(error(
                program,
                "SPX-T225",
                format!(
                    "generic function `{name}` accepts only direct `i64` or `bool` type arguments, except admitted Copy scalars in an owned-record relay"
                ),
                expr.span,
            ));
            return None;
        }
        validation_specialize_function(target, type_arguments)
    });
    let borrowed_bytes_loans = specialized_target.as_ref().map_or_else(Vec::new, |target| {
        activate_borrowed_bytes_call_loans(program, args, &target.params, variables, types)
    });
    for (index, arg) in args.iter().enumerate() {
        // Row Loan v1: the one admitted value use of a traversal row.
        let loan = target.and_then(|target| {
            super::super::record_traversal::row_loan::loan_argument(
                arg, target, index, variables, types,
            )
            .inspect(|_| {
                if !super::super::record_traversal::row_loan::reader_proof(types, target, index) {
                    diagnostics.push(error(
                        program,
                        "SPX-T284",
                        super::super::record_traversal::row_loan::HELPER_REFUSAL,
                        arg.span,
                    ));
                }
            })
        });
        let actual = loan.or_else(|| {
            check_expr(
                program,
                current,
                arg,
                variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            )
        });
        let Some(param) = specialized_target
            .as_ref()
            .and_then(|target| target.params.get(index))
        else {
            continue;
        };
        if let Some(actual) = &actual {
            reject_native_unit_value(program, arg, actual, diagnostics);
        }
        if let Some(actual) = actual
            .as_ref()
            .filter(|actual| !actual.native_unit && actual.ty != param.ty)
        {
            diagnostics.push(hints::with_optional_help(
                error(
                    program,
                    "SPX-T205",
                    format!(
                        "argument `{}` to `{name}` expects {}, received {}",
                        param.name, param.ty, actual.ty
                    ),
                    arg.span,
                ),
                hints::argument_view_help(name, &param.ty, &actual.ty),
            ));
        }
        check_argument_ownership(
            program,
            current,
            name,
            arg,
            param,
            actual.as_ref(),
            variables,
            types,
            allow_moves,
            true,
            target.is_some_and(|target| target.type_parameters.is_empty()),
            diagnostics,
        );
    }
    release_borrowed_bytes_call_loans(variables, &borrowed_bytes_loans);
    specialized_target.map(|target| {
        CheckedValue::returned(
            target.return_type.clone(),
            types.needs_drop(&target.return_type),
        )
    })
}

#[allow(clippy::too_many_arguments, clippy::borrowed_box, clippy::ptr_arg)]
pub(super) fn oracle_method_call(
    receiver: &Box<Expr>,
    method: &String,
    type_arguments: &Vec<Type>,
    args: &Vec<Expr>,
    program: &dyn ProgramSource,
    current: &Function,
    expr: &Expr,
    variables: &mut HashMap<String, Binding>,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    result_type: Option<&Type>,
    allow_moves: bool,
    diagnostics: &mut Vec<Diagnostic>,
) -> Option<CheckedValue> {
    if !type_arguments.is_empty() {
        diagnostics.push(error(
            program,
            "SPX-T225",
            format!("method `{method}` does not accept type arguments in this slice"),
            expr.span,
        ));
    }
    let receiver_value = check_expr(
        program,
        current,
        receiver,
        variables,
        functions,
        types,
        result_type,
        allow_moves,
        diagnostics,
    )?;
    let Type::Named {
        name: class_name,
        arguments: class_arguments,
    } = &receiver_value.ty
    else {
        diagnostics.push(hints::with_optional_help(
            error(
                program,
                "SPX-T203",
                format!(
                    "method `{method}` requires a class receiver, found `{}`",
                    receiver_value.ty
                ),
                receiver.span,
            ),
            hints::method_receiver_help(&receiver_value.ty, method),
        ));
        return None;
    };
    if !class_arguments.is_empty() {
        diagnostics.push(error(
            program,
            "SPX-T203",
            format!(
                "method `{method}` on generic class `{class_name}` is not supported in this slice"
            ),
            expr.span,
        ));
        return None;
    }
    // Class Inheritance v1: nearest-definition ancestor walk; the
    // declaring class owns the expected `self` type.
    let Some((holder_name, method_fn)) = resolve_class_method(types, class_name, method) else {
        diagnostics.push(hints::with_optional_help(
            error(
                program,
                "SPX-T203",
                format!("unknown method `{method}` on `{class_name}`"),
                expr.span,
            ),
            hints::non_class_method_help(types, class_name),
        ));
        return None;
    };
    let _ = holder_name;
    let Some(self_param) = method_fn.params.first() else {
        diagnostics.push(error(
            program,
            "SPX-T205",
            format!("method `{method}` on `{class_name}` has no `self` parameter"),
            method_fn.span,
        ));
        return None;
    };
    if self_param.mode != ParamMode::Value
        || self_param.ty
            != (Type::Named {
                name: holder_name.to_owned(),
                arguments: Vec::new(),
            })
    {
        diagnostics.push(error(
            program,
            "SPX-T205",
            format!(
                "method `{method}` expects a value-mode `self: {class_name}` receiver, found `{}`",
                self_param.ty
            ),
            self_param.span,
        ));
        return None;
    }
    if method_fn.params.len() - 1 != args.len() {
        diagnostics.push(error(
            program,
            "SPX-T204",
            format!(
                "`{}.{}` expects {} arguments, received {}",
                class_name,
                method,
                method_fn.params.len() - 1,
                args.len()
            ),
            expr.span,
        ));
        return None;
    }
    check_argument_ownership(
        program,
        current,
        method_fn.name.as_str(),
        receiver,
        self_param,
        Some(&receiver_value),
        variables,
        types,
        allow_moves,
        true,
        false,
        diagnostics,
    );
    for (index, (argument, param)) in args.iter().zip(method_fn.params.iter().skip(1)).enumerate() {
        let actual = check_expr(
            program,
            current,
            argument,
            variables,
            functions,
            types,
            result_type,
            allow_moves,
            diagnostics,
        );
        if let Some(actual) = &actual {
            reject_native_unit_value(program, argument, actual, diagnostics);
        }
        if actual
            .as_ref()
            .is_some_and(|actual| !actual.native_unit && actual.ty != param.ty)
        {
            diagnostics.push(error(
                program,
                "SPX-T205",
                format!(
                    "argument `{}` to `{method}` expects {}, received {}",
                    param.name,
                    param.ty,
                    actual.as_ref().expect("type checked above").ty
                ),
                argument.span,
            ));
        }
        check_argument_ownership(
            program,
            current,
            method_fn.name.as_str(),
            argument,
            param,
            actual.as_ref(),
            variables,
            types,
            allow_moves,
            true,
            false,
            diagnostics,
        );
        let _ = index;
    }
    Some(CheckedValue::returned(
        method_fn.return_type.clone(),
        types.needs_drop(&method_fn.return_type),
    ))
}

//! Recursive source twin of bounded traversal admission and loan expiry.
use super::*;
use crate::ast::program_source::ProgramSource;
#[allow(clippy::too_many_arguments)]
pub(super) fn check(
    program: &dyn ProgramSource,
    current: &Function,
    statement: &Statement,
    scope: &mut HashMap<String, Binding>,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    result_type: Option<&Type>,
    allow_moves: bool,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let (item, item_span, values, body, selected, borrowing) = match statement {
        Statement::For {
            item,
            item_span,
            values,
            body,
            ..
        } => (item, item_span, values, body, None, false),
        Statement::ForBorrow {
            item,
            item_span,
            values,
            body,
            index,
            ..
        } => (item, item_span, values, body, index.as_ref(), true),
        _ => unreachable!(),
    };
    let actual = check_expr(
        program,
        current,
        values,
        scope,
        functions,
        types,
        result_type,
        allow_moves,
        diagnostics,
    );
    let source = match &values.kind {
        ExprKind::Var(name) => Some(name.as_str()),
        _ => None,
    };
    let element = actual.as_ref().and_then(|actual| match &actual.ty {
                            ty @ Type::SliceU8 if !borrowing => crate::source_verify::byte_traversal::element(ty),
                            Type::Named { name, arguments }
                                if name == "Vec" && matches!(arguments.as_slice(), [ty] if (!borrowing && crate::vec_ops::ast_element_is_admitted(ty)) || (borrowing && crate::source_verify::record_traversal::admitted(types, ty))) =>
                            {
                                Some(arguments[0].clone())
                            }
                            _ => None,
                        });
    if source.is_none() || element.is_none() {
        diagnostics.push(error(
            program,
            "SPX-T284",
            "for traversal requires a simple immutable binding of exact Vec<T> for a Copy scalar T",
            values.span,
        ));
    }
    if source.is_some_and(|name| scope.get(name).is_some_and(|binding| binding.mutable)) {
        diagnostics.push(
            error(
                program,
                "SPX-T284",
                "for traversal source must be an immutable Vec binding",
                values.span,
            )
            .with_help(crate::source_verify::hints::IMMUTABLE_TRAVERSAL_HELP),
        );
    }
    let source_name = source.map(str::to_owned);
    let _ = reject_while_disallowed_oracle(program, body, functions, types, diagnostics);
    let item_inserted = !scope.contains_key(item);
    if !item_inserted {
        diagnostics.push(error(
            program,
            "SPX-T209",
            format!("loop item `{item}` shadows an existing value"),
            *item_span,
        ));
    }
    if item_inserted {
        if let Some(element) = element {
            scope.insert(
                item.clone(),
                Binding {
                    contract_local: false,
                    traversal_row: None,
                    ty: element,
                    mode: ParamMode::Value,
                    availability: Availability::Available,
                    moved_places: HashMap::new(),
                    definitely_partial: HashSet::new(),
                    native_unit_discard: false,
                    mutable: false,
                    active_loans: BTreeSet::new(),
                    borrow_origin: None,
                },
            );
        }
    }
    let mut index_inserted = false;
    let freeze = crate::source_verify::binding::SourceLoanId {
        borrower: item.clone(),
        start: values.span.start,
        end: body.span.end,
    };
    if borrowing && item_inserted {
        if let Some(root) = source {
            match crate::source_verify::record_traversal::body_binding_conflict(
                body,
                root,
                item,
                selected.map(|index| index.name.as_str()),
            ) {
                Ok(Some(span)) => {
                    diagnostics.push(error(
                        program,
                        "SPX-T284",
                        "record traversal cannot shadow its carrier, row or index binding",
                        span,
                    ));
                }
                Ok(None) => {}
                Err(()) => diagnostics.push(error(
                    program,
                    "SPX-T284",
                    "record traversal binding scan exceeds its source scratch, depth or work budget",
                    body.span,
                )),
            }
            if let Some(binding) = scope.get_mut(item) {
                binding.mode = ParamMode::Borrow;
                binding.traversal_row =
                    Some(Box::new(crate::source_verify::record_traversal::Row {
                        root: root.to_owned(),
                        element: binding.ty.clone(),
                        freeze: freeze.clone(),
                        index_inserted: false,
                    }));
            }
            if let Some(binding) = scope.get_mut(root) {
                binding
                    .active_loans
                    .insert(crate::source_verify::binding::SourceLoan {
                        id: freeze.clone(),
                        projections: Vec::new(),
                    });
            }
        }
        if let Some(index) = selected {
            if index.name == *item || scope.contains_key(&index.name) {
                diagnostics.push(error(
                    program,
                    "SPX-T209",
                    "record traversal index must be a fresh distinct binding",
                    index.span,
                ));
            } else {
                scope.insert(
                    index.name.clone(),
                    Binding {
                        contract_local: false,
                        traversal_row: None,
                        ty: Type::Usize,
                        mode: ParamMode::Value,
                        availability: Availability::Available,
                        moved_places: HashMap::new(),
                        definitely_partial: HashSet::new(),
                        native_unit_discard: false,
                        mutable: false,
                        active_loans: BTreeSet::new(),
                        borrow_origin: None,
                    },
                );
                index_inserted = true;
            }
        }
    }
    let byte_freeze = (!borrowing
        && item_inserted
        && actual
            .as_ref()
            .is_some_and(|actual| actual.ty == Type::SliceU8))
    .then(|| crate::source_verify::byte_traversal::freeze_id(item, values.span, body.span));
    if let (Some(id), Some(root)) = (&byte_freeze, source) {
        crate::source_verify::byte_traversal::freeze(scope, root, id);
    }
    let _ = matching::in_loop(|| {
        check_expr(
            program,
            current,
            body,
            scope,
            functions,
            types,
            result_type,
            allow_moves,
            diagnostics,
        )
    });
    if item_inserted {
        scope.remove(item);
    }
    if let Some(id) = &byte_freeze {
        crate::source_verify::byte_traversal::release(scope, id);
    }
    if borrowing {
        if let Some(root) = source {
            if let Some(binding) = scope.get_mut(root) {
                binding.active_loans.retain(|loan| loan.id != freeze);
            }
        }
        if index_inserted {
            scope.remove(&selected.expect("inserted index").name);
        }
    }
    if let Some(source) = source_name {
        let changed = scope.get(&source).is_none_or(|after| {
            after.availability != Availability::Available
                || !after.moved_places.is_empty()
                || !after.definitely_partial.is_empty()
        });
        if changed {
            diagnostics.push(error(
                                    program,
                                    "SPX-T284",
                                    format!("for traversal source `{source}` cannot be consumed or mutated in the loop body"),
                                    body.span,
                                ));
        }
    }
}

//! Recursive reference checking for exact String and borrowed-text intrinsics.
use super::*;
use crate::ast::program_source::ProgramSource;
use crate::ast::Param;
use crate::source_verify::arguments::{
    activate_borrowed_bytes_call_loans, check_argument_ownership, release_borrowed_bytes_call_loans,
};

#[allow(clippy::too_many_arguments)]
pub(super) fn check_call(
    name: &str,
    type_arguments: &[Type],
    args: &[Expr],
    program: &dyn ProgramSource,
    current: &Function,
    expression: &Expr,
    variables: &mut HashMap<String, Binding>,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    result_type: Option<&Type>,
    allow_moves: bool,
    diagnostics: &mut Vec<Diagnostic>,
) -> Option<CheckedValue> {
    let typed = crate::map_ops::by_generic_name(name, type_arguments);
    let (params, result): (Vec<Param>, Type) = if let Some(op) = typed {
        let Some(signature) = op.ast_signature(type_arguments) else {
            diagnostics.push(error(
                program,
                "SPX-T274",
                "typed collection requires admitted key/value type arguments",
                expression.span,
            ));
            return None;
        };
        signature
    } else if let Some(op) = crate::string_ops::by_name(name) {
        if op == crate::string_ops::StringOp::Take
            && !crate::string_ops::take::source_operand(args, allow_moves)
        {
            diagnostics.push(error(
                program,
                "SPX-O105",
                "string_take requires an available named owned String outside contracts",
                expression.span,
            ));
        }
        (crate::string_ops::ast_params(op), op.ast_return_type())
    } else {
        let op = crate::str_ops::by_name(name)?;
        (crate::str_ops::ast_params(op), op.ast_return_type())
    };
    if typed.is_none() && !type_arguments.is_empty() {
        diagnostics.push(error(
            program,
            "SPX-T225",
            format!("monomorphic function `{name}` does not accept type arguments"),
            expression.span,
        ));
    }
    if args.len() != params.len() {
        diagnostics.push(error(
            program,
            "SPX-T204",
            format!(
                "`{name}` expects {} arguments, received {}",
                params.len(),
                args.len()
            ),
            expression.span,
        ));
    }
    let loans = activate_borrowed_bytes_call_loans(program, args, &params, variables, types);
    for (index, argument) in args.iter().enumerate() {
        let actual = check_expr(
            program,
            current,
            argument,
            variables,
            functions,
            types,
            result_type,
            allow_moves,
            diagnostics,
        );
        let Some(parameter) = params.get(index) else {
            continue;
        };
        if let Some(actual) = &actual {
            reject_native_unit_value(program, argument, actual, diagnostics);
            if !actual.native_unit && actual.ty != parameter.ty {
                diagnostics.push(hints::with_optional_help(
                    error(
                        program,
                        "SPX-T205",
                        format!(
                            "argument `{}` to `{name}` expects {}, received {}",
                            parameter.name, parameter.ty, actual.ty
                        ),
                        argument.span,
                    ),
                    hints::argument_view_help(name, &parameter.ty, &actual.ty),
                ));
            }
        }
        check_argument_ownership(
            program,
            current,
            name,
            argument,
            parameter,
            actual.as_ref(),
            variables,
            types,
            allow_moves,
            false,
            false,
            diagnostics,
        );
    }
    release_borrowed_bytes_call_loans(variables, &loans);
    let owns = types.needs_drop(&result);
    Some(CheckedValue::returned(result, owns))
}

//! Differential ordinary return checking, distinct from the iterative resume frame.
use super::*;
use crate::ast::program_source::ProgramSource;
#[allow(clippy::too_many_arguments)]
pub(super) fn check(
    program: &dyn ProgramSource,
    current: &Function,
    expr: &Expr,
    variables: &mut HashMap<String, Binding>,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    result_type: Option<&Type>,
    allow_moves: bool,
    diagnostics: &mut Vec<Diagnostic>,
) -> Option<CheckedValue> {
    let ExprKind::LexicalExit { kind, value } = &expr.kind else {
        unreachable!()
    };
    if *kind == crate::ast::LexicalExitKind::Return && value.is_none() {
        diagnostics.push(error(
            program,
            "SPX-T312",
            "return requires a value operand",
            expr.span,
        ));
        return None;
    }
    if let Some(operand) = value {
        let value = check_expr(
            program,
            current,
            operand,
            variables,
            functions,
            types,
            result_type,
            allow_moves,
            diagnostics,
        )?;
        if value.native_unit || value.ty != current.return_type {
            diagnostics.push(error(
                program,
                "SPX-T103",
                "lexical return operand differs from the function result type",
                operand.span,
            ));
        }
        if types.needs_drop(&value.ty) && value.mode != ParamMode::Own {
            diagnostics.push(error(
                program,
                "SPX-O104",
                "lexical return must transfer an owned result",
                operand.span,
            ));
        }
        if !allow_moves {
            diagnostics.push(error(
                program,
                "SPX-T312",
                "return is only admitted in the executable function body",
                expr.span,
            ));
        } else if types.needs_drop(&value.ty) {
            mark_value_sources_moved(program, operand, variables, types, diagnostics);
        }
    }
    Some(CheckedValue::value(Type::Never))
}

//! Test-only recursive checking of `match` expressions: exhaustiveness,
//! per-arm binding state, and the joins that produce the match's value.

use crate::ast::program_source::ProgramSource;
use crate::ast::{Expr, ExprKind, Function, MatchMode, MatchPattern, ParamMode, Type};
use crate::diagnostic::Diagnostic;
use crate::source_verify::binding::{Availability, Binding, CheckedValue};
use crate::source_verify::declared_type::{
    check_record_pattern, generic_function_has_owned_record_composition,
};
use crate::source_verify::diagnostics::{
    error, reject_aggregate_match_result, reject_loop_match_scrutinee, reject_native_unit_value,
    source_identifier,
};
use crate::source_verify::loans::{activate_match_loan, mark_value_sources_moved, merge_moved};
use crate::source_verify::oracle::check_expr;
use crate::source_verify::place::{join_definitely_partial, join_moved_places, source_place};
use crate::source_verify::scope::pattern_literal_type;
use crate::source_verify::type_table::TypeTable;
use crate::source_verify::variant_or::{
    check_variant_or_pattern, VariantOrContext, AGGREGATE_REFUTABLE_HELP,
};
use std::collections::{BTreeSet, HashMap, HashSet};

std::thread_local! {
    /// The recursive twin of `IterativeVerifier::loop_depth`.
    static LOOP_DEPTH: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
    /// The exact consuming-loop item whose owned Bytes/record payload may be
    /// passed to its declared consumer or matched in that loop body.
    static OWNED_ITERATOR_ITEMS: std::cell::RefCell<Vec<(String, Type)>> = const {
        std::cell::RefCell::new(Vec::new())
    };
}

/// Check `inner` as part of a `while`/`for` condition or body.
pub(super) fn in_loop<T>(inner: impl FnOnce() -> T) -> T {
    LOOP_DEPTH.with(|depth| depth.set(depth.get() + 1));
    let result = inner();
    LOOP_DEPTH.with(|depth| depth.set(depth.get().saturating_sub(1)));
    result
}

pub(super) fn with_owned_iterator_item<T>(item: &str, ty: &Type, inner: impl FnOnce() -> T) -> T {
    OWNED_ITERATOR_ITEMS.with(|items| items.borrow_mut().push((item.to_owned(), ty.clone())));
    let result = inner();
    OWNED_ITERATOR_ITEMS.with(|items| {
        items.borrow_mut().pop();
    });
    result
}

pub(super) fn in_owned_iterator_loop<T>(item: &str, ty: &Type, inner: impl FnOnce() -> T) -> T {
    with_owned_iterator_item(item, ty, || in_loop(inner))
}

pub(super) fn is_owned_iterator_item(name: &str, ty: &Type) -> bool {
    OWNED_ITERATOR_ITEMS.with(|items| {
        items
            .borrow()
            .last()
            .is_some_and(|(item, item_ty)| item == name && item_ty == ty)
    })
}

#[allow(clippy::too_many_arguments, clippy::borrowed_box)]
pub(super) fn oracle_match(
    mode: &MatchMode,
    scrutinee: &Box<Expr>,
    arms: &Vec<crate::ast::MatchArm>,
    program: &dyn ProgramSource,
    current: &Function,
    expr: &Expr,
    variables: &mut HashMap<String, Binding>,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    result_type: Option<&Type>,
    allow_moves: bool,
    diagnostics: &mut Vec<Diagnostic>,
) -> Option<CheckedValue> {
    let scrutinee_value = check_expr(
        program,
        current,
        scrutinee,
        variables,
        functions,
        types,
        result_type,
        allow_moves,
        diagnostics,
    );
    if let Some(value) = &scrutinee_value {
        reject_native_unit_value(program, scrutinee, value, diagnostics);
        let exact_owned_record_item = value.mode == ParamMode::Own
            && crate::source_verify::declared_type::owned_leaf_collection::runtime_element(
                types, &value.ty,
            )
            && matches!(&scrutinee.kind, ExprKind::Var(name)
                if is_owned_iterator_item(name, &value.ty));
        if LOOP_DEPTH.with(std::cell::Cell::get) != 0
            && !exact_owned_record_item
            && !crate::finite_owned_record_loop::source_permits(current, expr)
        {
            reject_loop_match_scrutinee(program, types, scrutinee, value, diagnostics);
        }
    }
    // Refutable Match v1: Copy-scalar decision chain in the
    // recursive oracle twin.
    let scalar_scrutinee = *mode == MatchMode::Value
        && scrutinee_value.as_ref().is_some_and(|value| {
            matches!(
                value.ty,
                Type::I64 | Type::I32 | Type::Char | Type::U8 | Type::Usize | Type::Bool
            ) && value.mode == ParamMode::Value
        });
    if scalar_scrutinee {
        let scrutinee_value = scrutinee_value.expect("scalar checked above");
        let mut result = None::<CheckedValue>;
        let baseline = variables.clone();
        let outer_names = variables.keys().cloned().collect::<Vec<_>>();
        let mut joined = baseline.clone();
        for arm in arms {
            *variables = baseline.clone();
            match &arm.pattern {
                MatchPattern::Wildcard { .. } => {}
                MatchPattern::Binding { name, span } => {
                    if !source_identifier(name) || variables.contains_key(name) {
                        diagnostics.push(error(
                            program,
                            "SPX-M104",
                            format!("invalid or duplicate pattern binding `{name}`"),
                            *span,
                        ));
                    } else {
                        variables.insert(
                            name.clone(),
                            Binding {
                                contract_local: false,
                                traversal_row: None,
                                ty: scrutinee_value.ty.clone(),
                                mode: ParamMode::Value,
                                availability: Availability::Available,
                                moved_places: HashMap::new(),
                                definitely_partial: HashSet::new(),
                                native_unit_discard: false,
                                mutable: false,
                                active_loans: BTreeSet::new(),
                                borrow_origin: None,
                            },
                        );
                    }
                }
                MatchPattern::Literal { value, span } => {
                    if pattern_literal_type(*value) != scrutinee_value.ty {
                        diagnostics.push(error(
                            program,
                            "SPX-T255",
                            format!(
                                "literal pattern of type `{}` cannot match a `{}` \
                                 scrutinee; pattern literals compare against exactly \
                                 their own type",
                                value.type_text(),
                                scrutinee_value.ty
                            ),
                            *span,
                        ));
                    }
                }
                MatchPattern::Or { alternatives, span } => {
                    let mut seen_type: Option<Type> = None;
                    for alternative in alternatives {
                        let MatchPattern::Literal { value, span } = alternative else {
                            diagnostics.push(error(
                                program,
                                "SPX-M105",
                                "or-patterns admit only literal alternatives in v1",
                                alternative.span(),
                            ));
                            continue;
                        };
                        if pattern_literal_type(*value) != scrutinee_value.ty {
                            diagnostics.push(error(
                                program,
                                "SPX-T255",
                                format!(
                                    "literal pattern of type `{}` cannot match a `{}` \
                                     scrutinee; pattern literals compare against \
                                     exactly their own type",
                                    value.type_text(),
                                    scrutinee_value.ty
                                ),
                                *span,
                            ));
                        }
                        match (&seen_type, pattern_literal_type(*value)) {
                            (None, ty) => seen_type = Some(ty),
                            (Some(seen), ty) if *seen == ty => {}
                            (Some(seen), ty) => {
                                diagnostics.push(error(
                                    program,
                                    "SPX-M105",
                                    format!(
                                        "or-pattern mixes `{seen}` and `{ty}` literal \
                                         alternatives"
                                    ),
                                    *span,
                                ));
                            }
                        }
                    }
                    if alternatives.is_empty() {
                        diagnostics.push(error(
                            program,
                            "SPX-M105",
                            "or-pattern needs at least one literal alternative",
                            *span,
                        ));
                    }
                }
                MatchPattern::Variant { span, .. } | MatchPattern::Record { span, .. } => {
                    diagnostics.push(error(
                        program,
                        "SPX-M103",
                        "aggregate pattern is incompatible with a Copy-scalar scrutinee",
                        *span,
                    ));
                }
            }
            if let Some(guard) = &arm.guard {
                let guard_value = check_expr(
                    program,
                    current,
                    guard.as_ref(),
                    variables,
                    functions,
                    types,
                    result_type,
                    allow_moves,
                    diagnostics,
                );
                if let Some(value) = &guard_value {
                    reject_native_unit_value(program, guard.as_ref(), value, diagnostics);
                }
                if guard_value
                    .as_ref()
                    .is_none_or(|value| value.ty != Type::Bool || value.mode != ParamMode::Value)
                {
                    diagnostics.push(error(
                        program,
                        "SPX-T256",
                        format!(
                            "match guard must be bool; received {}",
                            guard_value.as_ref().map_or_else(
                                || "an invalid value".to_owned(),
                                |value| value.ty.to_string()
                            )
                        ),
                        guard.span,
                    ));
                }
            }
            let arm_value = check_expr(
                program,
                current,
                &arm.value,
                variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            );
            if let Some(value) = &arm_value {
                reject_native_unit_value(program, &arm.value, value, diagnostics);
                reject_aggregate_match_result(program, &arm.value, value, diagnostics);
            }
            if !crate::ast::returns_only(&arm.value) {
                merge_moved(&mut joined, variables, &outer_names);
            }
            if let Some(arm_value) = arm_value {
                if let Some(expected) = &result {
                    if expected.ty != Type::Never
                        && arm_value.ty != Type::Never
                        && (expected.ty != arm_value.ty || expected.mode != arm_value.mode)
                    {
                        diagnostics.push(error(
                            program,
                            "SPX-T259",
                            format!(
                                "match arms return incompatible values: {} and {}",
                                expected.ty, arm_value.ty
                            ),
                            arm.value.span,
                        ));
                    }
                }
                if result.as_ref().is_none_or(|v| v.ty == Type::Never) {
                    result = Some(arm_value);
                }
            }
        }
        let last = arms.last().expect("match always has an arm list");
        let catch_all = matches!(
            &last.pattern,
            MatchPattern::Wildcard { .. } | MatchPattern::Binding { .. }
        );
        if !catch_all || last.guard.is_some() {
            diagnostics.push(error(
                program,
                "SPX-T257",
                "refutable match requires a trailing irrefutable catch-all arm (`_` or \
                 a binding) without a guard",
                last.span,
            ));
        }
        *variables = joined;
        return result;
    }
    if arms.iter().any(|arm| {
        arm.guard.is_some()
            && !scrutinee_value.as_ref().is_some_and(|value| {
                value.mode == ParamMode::Value
                    && crate::source_verify::variant_guards::admission(
                        types,
                        &value.ty,
                        *mode,
                        &arm.pattern,
                    )
            })
    }) {
        diagnostics.push(error(program, "SPX-T254", "guards and literal/or/binding patterns require a Copy-scalar scrutinee (i64/i32/u8/char/bool)", scrutinee.span).with_help(AGGREGATE_REFUTABLE_HELP));
    }
    if scrutinee_value
        .as_ref()
        .is_some_and(|value| types.record_fields(&value.ty).is_some())
    {
        let Some(scrutinee_value) = scrutinee_value else {
            unreachable!("record instance was checked above");
        };
        let needs_drop = types.needs_drop(&scrutinee_value.ty);
        if *mode != MatchMode::Value
            && types.contains_owned_bytes(&scrutinee_value.ty)
            && !types.is_nested_owned_byte_record(&scrutinee_value.ty)
        {
            diagnostics.push(error(
                program,
                "SPX-O117",
                "ownership-aware record pattern is outside the bounded nested owned-Bytes profile",
                scrutinee.span,
            ));
        }
        match mode {
            MatchMode::Value => {
                if needs_drop || scrutinee_value.mode != ParamMode::Value {
                    diagnostics.push(error(
                        program,
                        "SPX-O111",
                        "plain record match requires a Copy scrutinee",
                        scrutinee.span,
                    ));
                }
            }
            MatchMode::Own => {
                let recursive_profile = types.is_nested_owned_byte_record(&scrutinee_value.ty)
                    && !types.is_flat_owned_byte_record(&scrutinee_value.ty);
                let nested_exact_place = !recursive_profile
                    || source_place(scrutinee, variables, types)
                        .is_some_and(|place| place.projections.is_empty());
                if !needs_drop || scrutinee_value.mode != ParamMode::Own || !nested_exact_place {
                    let message = if recursive_profile {
                        "nested `match own` requires an exact named owned record place"
                    } else {
                        "`match own` requires an owned non-Copy record scrutinee"
                    };
                    diagnostics.push(error(program, "SPX-O117", message, scrutinee.span));
                } else if allow_moves {
                    mark_value_sources_moved(program, scrutinee, variables, types, diagnostics);
                } else {
                    diagnostics.push(error(
                        program,
                        "SPX-O105",
                        "contract expression cannot consume a match scrutinee",
                        scrutinee.span,
                    ));
                }
            }
            MatchMode::Borrow => {
                if !needs_drop
                    || !matches!(scrutinee_value.mode, ParamMode::Own | ParamMode::Borrow)
                    || source_place(scrutinee, variables, types)
                        .is_none_or(|place| !place.projections.is_empty())
                {
                    diagnostics.push(error(
                        program,
                        "SPX-O117",
                        "`match borrow` requires a named owned or borrowed non-Copy record place",
                        scrutinee.span,
                    ));
                }
            }
        }
        let Some((first, rest)) = arms.split_first() else {
            diagnostics.push(error(
                program,
                "SPX-M101",
                format!(
                    "non-exhaustive match; missing record pattern for `{}`",
                    crate::source_verify::private_names::type_name(
                        program,
                        types,
                        &scrutinee_value.ty
                    )
                ),
                expr.span,
            ));
            return None;
        };
        for arm in rest {
            diagnostics.push(error(
                program,
                "SPX-M102",
                "unreachable arm after an irrefutable record pattern",
                arm.pattern.span(),
            ));
        }
        let outer_names = variables.keys().cloned().collect::<Vec<_>>();
        let mut arm_variables = variables.clone();
        if *mode == MatchMode::Borrow {
            if let Some(place) = source_place(scrutinee, variables, types) {
                activate_match_loan(&mut arm_variables, &place, expr.span);
            }
        }
        match &first.pattern {
            MatchPattern::Wildcard { span } if *mode != MatchMode::Value => {
                diagnostics.push(error(
                    program,
                    "SPX-O117",
                    "explicit ownership match requires an exact record pattern",
                    *span,
                ));
            }
            MatchPattern::Wildcard { .. } => {}
            MatchPattern::Record {
                type_name,
                fields,
                span,
                ..
            } => check_record_pattern(
                program,
                type_name,
                fields,
                &scrutinee_value.ty,
                &mut arm_variables,
                types,
                diagnostics,
                *span,
                *mode,
            ),
            MatchPattern::Variant { .. } => diagnostics.push(error(
                program,
                "SPX-M103",
                "variant pattern is incompatible with a record scrutinee",
                first.pattern.span(),
            )),
            MatchPattern::Literal { .. }
            | MatchPattern::Or { .. }
            | MatchPattern::Binding { .. } => {
                diagnostics.push(
                    error(
                        program,
                        "SPX-T254",
                        "refutable patterns are incompatible with an aggregate record \
                         scrutinee",
                        first.pattern.span(),
                    )
                    .with_help(AGGREGATE_REFUTABLE_HELP),
                );
            }
        }
        let result = check_expr(
            program,
            current,
            &first.value,
            &mut arm_variables,
            functions,
            types,
            result_type,
            allow_moves,
            diagnostics,
        );
        if let Some(value) = &result {
            reject_native_unit_value(program, &first.value, value, diagnostics);
        }
        if !result.as_ref().is_some_and(|v| v.ty == Type::Never) {
            merge_moved(variables, &arm_variables, &outer_names);
        }
        let generic_template = functions.get(current.name.as_str()).copied();
        let generic_owned_result = generic_template
            .is_some_and(|function| generic_function_has_owned_record_composition(function, types));
        if result.as_ref().is_some_and(|value| {
            value.ty != Type::Never && (!matches!(value.ty, Type::I64 | Type::Bool) || value.mode != ParamMode::Value)
                && !(generic_template.is_some_and(|function| function.type_parameters.is_empty())
                    && (value.mode == ParamMode::Value
                        || (*mode == MatchMode::Own && scrutinee_value.mode == ParamMode::Own && types.is_nested_owned_byte_record(&scrutinee_value.ty)))
                    && crate::source_verify::declared_type::ordinary_record_match_result(&value.ty, value.mode, types))
                && !(generic_owned_result
                    && (((value.ty == current.return_type || types.is_nested_owned_byte_record(&value.ty)) && value.mode == ParamMode::Own)
                        || (value.mode == ParamMode::Value
                            && (crate::source_verify::type_table::owned_byte_record_copy_field_is_admitted(&value.ty)
                                || matches!(&value.ty, Type::Named { name, arguments }
                                    if arguments.is_empty() && generic_template.is_some_and(|function| function.type_parameters.iter().any(|parameter| parameter.name == *name)))))))
        }) {
            diagnostics.push(error(
                program,
                "SPX-T216",
                "record match arm must return a Copy i64 or bool value",
                first.value.span,
            ));
            return None;
        }
        return result;
    }
    let variant_instance = scrutinee_value.as_ref().and_then(|value| match &value.ty {
        Type::Named { name, arguments } if types.variant_cases(&value.ty).is_some() => {
            Some((name.clone(), arguments.clone()))
        }
        Type::Never
        | Type::I64
        | Type::I32
        | Type::Char
        | Type::U8
        | Type::Usize
        | Type::ArrayU8(_)
        | Type::F32
        | Type::F64
        | Type::Bool
        | Type::String
        | Type::Bytes
        | Type::Str
        | Type::SliceU8
        | Type::StringMap
        | Type::OnceFunction
        | Type::OnceFunctionI64
        | Type::OnceFunctionI64Pair
        | Type::MutFunctionI64
        | Type::Function { .. }
        | Type::Named { .. } => None,
    });
    let variant_name = variant_instance.as_ref().map(|(name, _)| name.clone());
    let declared_cases = scrutinee_value
        .as_ref()
        .and_then(|value| types.variant_cases(&value.ty));
    if declared_cases.is_none() {
        diagnostics.push(error(
            program,
            "SPX-M103",
            format!(
                "match scrutinee must be a Copy variant, received {}",
                scrutinee_value.as_ref().map_or_else(
                    || "an invalid value".to_owned(),
                    |value| crate::source_verify::private_names::type_name(
                        program, types, &value.ty
                    )
                )
            ),
            scrutinee.span,
        ));
    }

    let variant_needs_drop = scrutinee_value
        .as_ref()
        .is_some_and(|value| types.needs_drop(&value.ty));
    if let Some(scrutinee_value) = &scrutinee_value {
        match mode {
            MatchMode::Value if variant_needs_drop => diagnostics.push(error(
                program,
                "SPX-O111",
                "plain variant match requires a Copy scrutinee",
                scrutinee.span,
            )),
            MatchMode::Own
                if !variant_needs_drop
                    || !(types.is_flat_owned_byte_variant(&scrutinee_value.ty)
                        || types.is_direct_owned_variant(&scrutinee_value.ty))
                    || scrutinee_value.mode != ParamMode::Own =>
            {
                diagnostics.push(error(
                    program,
                    "SPX-O117",
                    "`match own` requires an owned admitted non-Copy variant scrutinee",
                    scrutinee.span,
                ));
            }
            MatchMode::Own if allow_moves => {
                mark_value_sources_moved(program, scrutinee, variables, types, diagnostics);
            }
            MatchMode::Own => diagnostics.push(error(
                program,
                "SPX-O105",
                "contract expression cannot consume a match scrutinee",
                scrutinee.span,
            )),
            MatchMode::Borrow
                if !variant_needs_drop
                    || !(types.is_flat_owned_byte_variant(&scrutinee_value.ty)
                        || types.is_direct_owned_variant(&scrutinee_value.ty)
                        || crate::native_rust_binding::admitted_regex_result(
                            program,
                            &scrutinee_value.ty,
                        ))
                    || !matches!(scrutinee_value.mode, ParamMode::Own | ParamMode::Borrow)
                    || source_place(scrutinee, variables, types)
                        .is_none_or(|place| !place.projections.is_empty()) =>
            {
                diagnostics.push(error(
                    program,
                    "SPX-O117",
                    "`match borrow` requires an unprojected named owned or borrowed admitted non-Copy variant place",
                    scrutinee.span,
                ));
            }
            MatchMode::Borrow | MatchMode::Value => {}
        }
    }

    let outer_names = variables.keys().cloned().collect::<Vec<_>>();
    let mut arm_states = Vec::new();
    let mut covered = HashSet::new();
    let mut wildcard_seen = false;
    let mut result = None::<CheckedValue>;
    for arm in arms {
        let mut arm_variables = variables.clone();
        if *mode == MatchMode::Borrow {
            if let Some(place) = source_place(scrutinee, variables, types) {
                if place.projections.is_empty() {
                    activate_match_loan(&mut arm_variables, &place, expr.span);
                }
            }
        }
        match &arm.pattern {
            MatchPattern::Wildcard { span } => {
                if *mode != MatchMode::Value {
                    diagnostics.push(error(
                        program,
                        "SPX-O117",
                        "explicit ownership variant match requires every case pattern",
                        *span,
                    ));
                }
                if wildcard_seen || declared_cases.is_some_and(|cases| covered.len() == cases.len())
                {
                    diagnostics.push(error(
                        program,
                        "SPX-M102",
                        "unreachable wildcard match arm",
                        *span,
                    ));
                }
                wildcard_seen = arm.guard.is_none();
            }
            MatchPattern::Variant {
                type_name,
                case_name,
                fields,
                span,
                ..
            } => {
                let compatible = variant_name.as_deref() == Some(type_name.as_str());
                let declared_case = compatible
                    .then_some(declared_cases)
                    .flatten()
                    .and_then(|cases| cases.iter().find(|case| case.name == *case_name));
                if declared_case.is_none() {
                    let diagnostic = error(
                        program,
                        "SPX-M103",
                        format!(
                            "pattern `{type_name}::{case_name}` is incompatible with the match scrutinee"
                        ),
                        *span,
                    );
                    diagnostics.push(
                        match compatible
                            .then_some(declared_cases)
                            .flatten()
                            .and_then(|cases| {
                                crate::source_verify::hints::nearest_variant_case_name(
                                    case_name, cases,
                                )
                            }) {
                            Some(nearest) => diagnostic.with_help(format!(
                                "did you mean `{type_name}::{nearest} {{ ... }}`?"
                            )),
                            None => diagnostic,
                        },
                    );
                } else if wildcard_seen
                    || covered.contains(case_name.as_str())
                    || (arm.guard.is_none() && !covered.insert(case_name.as_str()))
                {
                    diagnostics.push(error(
                        program,
                        "SPX-M102",
                        format!("unreachable duplicate case `{type_name}::{case_name}`"),
                        *span,
                    ));
                }
                let mut supplied = HashSet::new();
                let mut bindings = HashSet::new();
                for field in fields {
                    let declared_field = declared_case.and_then(|case| {
                        case.fields
                            .iter()
                            .find(|candidate| candidate.name == field.name)
                    });
                    if !supplied.insert(field.name.as_str())
                        || (declared_case.is_some() && declared_field.is_none())
                    {
                        diagnostics.push(error(
                            program,
                            "SPX-M104",
                            format!(
                                "unknown or duplicate pattern field `{}` in `{type_name}::{case_name}`",
                                field.name
                            ),
                            field.span,
                        ));
                    }
                    if !source_identifier(&field.binding)
                        || !bindings.insert(field.binding.as_str())
                        || arm_variables.contains_key(&field.binding)
                    {
                        diagnostics.push(error(
                            program,
                            "SPX-M104",
                            format!("invalid or duplicate pattern binding `{}`", field.binding),
                            field.binding_span,
                        ));
                        continue;
                    }
                    if let Some(declared_field) = declared_field {
                        let binding_ty = variant_instance
                            .as_ref()
                            .and_then(|(name, arguments)| {
                                types.declaration(name).and_then(|declaration| {
                                    TypeTable::substitute_variant_type(
                                        declaration,
                                        arguments,
                                        &declared_field.ty,
                                    )
                                })
                            })
                            .unwrap_or_else(|| declared_field.ty.clone());
                        let binding_mode = if types.needs_drop(&binding_ty) {
                            match mode {
                                MatchMode::Own => ParamMode::Own,
                                MatchMode::Borrow => ParamMode::Borrow,
                                MatchMode::Value => ParamMode::Value,
                            }
                        } else {
                            ParamMode::Value
                        };
                        arm_variables.insert(
                            field.binding.clone(),
                            Binding {
                                contract_local: false,
                                traversal_row: None,
                                ty: binding_ty,
                                mode: binding_mode,
                                availability: Availability::Available,
                                moved_places: HashMap::new(),
                                definitely_partial: HashSet::new(),
                                native_unit_discard: false,
                                mutable: false,
                                active_loans: BTreeSet::new(),
                                borrow_origin: None,
                            },
                        );
                    }
                }
                if let Some(declared_case) = declared_case {
                    for field in &declared_case.fields {
                        if !supplied.contains(field.name.as_str()) {
                            diagnostics.push(error(
                                program,
                                "SPX-M104",
                                format!(
                                    "pattern `{type_name}::{case_name}` is missing payload field `{}`",
                                    field.name
                                ),
                                *span,
                            ));
                        }
                    }
                }
            }
            MatchPattern::Record { span, .. } => diagnostics.push(error(
                program,
                "SPX-M103",
                "record pattern is incompatible with a variant scrutinee",
                *span,
            )),
            MatchPattern::Or { alternatives, span } => {
                let mut candidate_coverage = covered.clone();
                let context = VariantOrContext {
                    variant_name: variant_name.as_deref(),
                    declared_cases,
                    mode: *mode,
                    wildcard_seen,
                };
                check_variant_or_pattern(
                    program,
                    alternatives,
                    *span,
                    &context,
                    &mut |case| candidate_coverage.insert(case),
                    diagnostics,
                );
                if arm.guard.is_none() {
                    covered = candidate_coverage;
                }
            }
            MatchPattern::Literal { span, .. } | MatchPattern::Binding { span, .. } => {
                diagnostics.push(
                    error(
                        program,
                        "SPX-T254",
                        "refutable patterns are incompatible with an aggregate variant \
                         scrutinee",
                        *span,
                    )
                    .with_help(AGGREGATE_REFUTABLE_HELP),
                );
            }
        }
        if let Some(guard) = &arm.guard {
            if !crate::source_verify::variant_guards::guard_shape(guard, &arm_variables) {
                diagnostics.push(error(
                    program,
                    "SPX-T254",
                    "Copy variant guards require an ordinary Boolean expression without yield, closure, unsafe or residual propagation",
                    guard.span,
                ));
            }
            if let Some(value) = check_expr(
                program,
                current,
                guard,
                &mut arm_variables,
                functions,
                types,
                result_type,
                allow_moves,
                diagnostics,
            ) {
                if value.ty != Type::Bool || value.mode != ParamMode::Value {
                    diagnostics.push(error(
                        program,
                        "SPX-T256",
                        format!("match guard must be bool; received {}", value.ty),
                        guard.span,
                    ));
                }
            }
            if !crate::source_verify::variant_guards::ownership_unchanged(variables, &arm_variables)
            {
                diagnostics.push(error(
                    program,
                    "SPX-T254",
                    "Copy variant guard changes surrounding ownership",
                    guard.span,
                ));
            }
        }
        let arm_value = check_expr(
            program,
            current,
            &arm.value,
            &mut arm_variables,
            functions,
            types,
            result_type,
            allow_moves,
            diagnostics,
        );
        if let Some(value) = &arm_value {
            reject_native_unit_value(program, &arm.value, value, diagnostics);
            if !scrutinee_value.as_ref().is_some_and(|input| {
                crate::source_verify::declared_type::collection_outcome::match_result(
                    types, &input.ty, *mode, &value.ty, value.mode,
                )
            }) && !crate::source_verify::declared_type::generic_variant::match_result(
                functions.get(current.name.as_str()).copied(),
                types,
                *mode,
                &value.ty,
                value.mode,
            ) {
                reject_aggregate_match_result(program, &arm.value, value, diagnostics);
            }
        }
        let exits = crate::ast::returns_only(&arm.value);
        if let Some(arm_value) = arm_value {
            if arm_value.ty != Type::Never
                && variant_needs_drop
                && !scrutinee_value.as_ref().is_some_and(|input| {
                    crate::source_verify::declared_type::collection_outcome::match_result(
                        types,
                        &input.ty,
                        *mode,
                        &arm_value.ty,
                        arm_value.mode,
                    )
                })
                && !crate::source_verify::declared_type::generic_variant::match_result(
                    functions.get(current.name.as_str()).copied(),
                    types,
                    *mode,
                    &arm_value.ty,
                    arm_value.mode,
                )
                && (*mode == MatchMode::Value
                    || !matches!(arm_value.ty, Type::I64 | Type::Bool)
                    || arm_value.mode != ParamMode::Value)
            {
                diagnostics.push(error(
                    program,
                    "SPX-T216",
                    "owned variant match arms must return a Copy i64 or bool value",
                    arm.value.span,
                ));
            }
            if let Some(expected) = &result {
                if expected.ty != Type::Never
                    && arm_value.ty != Type::Never
                    && (expected.ty != arm_value.ty || expected.mode != arm_value.mode)
                {
                    diagnostics.push(error(
                        program,
                        "SPX-T216",
                        format!(
                            "match arms return incompatible values: {} and {}",
                            expected.ty, arm_value.ty
                        ),
                        arm.value.span,
                    ));
                }
            }
            if result.as_ref().is_none_or(|v| v.ty == Type::Never) {
                result = Some(arm_value);
            }
        }
        if !exits {
            arm_states.push(arm_variables);
        }
    }
    if !wildcard_seen {
        if let (Some(variant_name), Some(cases)) = (&variant_name, declared_cases) {
            if let Some(missing) = cases
                .iter()
                .find(|case| !covered.contains(case.name.as_str()))
            {
                diagnostics.push(crate::source_verify::private_names::missing_case(
                    program,
                    types,
                    variant_name,
                    &missing.name,
                    !missing.fields.is_empty(),
                    expr.span,
                ));
            }
        }
    }
    if let Some((first, rest)) = arm_states.split_first() {
        let mut joined = first.clone();
        for state in rest {
            for name in &outer_names {
                if let (Some(joined_binding), Some(state_binding)) =
                    (joined.get_mut(name), state.get(name))
                {
                    joined_binding.availability =
                        joined_binding.availability.join(state_binding.availability);
                    joined_binding.moved_places = join_moved_places(joined_binding, state_binding);
                    joined_binding.definitely_partial =
                        join_definitely_partial(joined_binding, state_binding);
                }
            }
        }
        merge_moved(variables, &joined, &outer_names);
    }
    result
}

pub(super) fn in_loop_scope() -> bool {
    LOOP_DEPTH.with(|depth| depth.get() != 0)
}

//! Recursive oracle for the closed streaming operation signatures.
use super::*;
use crate::ast::program_source::ProgramSource;
#[allow(clippy::too_many_arguments)]
pub(super) fn check_call(
    name: &str,
    type_arguments: &[Type],
    args: &[Expr],
    program: &dyn ProgramSource,
    current: &Function,
    expression: &Expr,
    variables: &mut HashMap<String, Binding>,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    result_type: Option<&Type>,
    allow_moves: bool,
    diagnostics: &mut Vec<Diagnostic>,
) -> Option<CheckedValue> {
    let (params, result, own) = if let Some(op) = crate::stdin_stream_ops::pure_by_name(name) {
        (op.params(), op.ast_result(), false)
    } else {
        let op = crate::stdin_stream_ops::host_by_name(name)?;
        (
            crate::stdin_stream_ops::host_params(op),
            crate::stdin_stream_ops::ast_reader(),
            true,
        )
    };
    if !type_arguments.is_empty() || args.len() != params.len() {
        diagnostics.push(error(
            program,
            "SPX-T270",
            "invalid streaming stdin call shape",
            expression.span,
        ));
    }
    let loans = crate::source_verify::arguments::activate_borrowed_bytes_call_loans(
        program, args, &params, variables, types,
    );
    for (index, arg) in args.iter().enumerate() {
        let actual = check_expr(
            program,
            current,
            arg,
            variables,
            functions,
            types,
            result_type,
            allow_moves,
            diagnostics,
        );
        let Some(param) = params.get(index) else {
            continue;
        };
        if let Some(value) = actual.as_ref().filter(|value| value.ty != param.ty) {
            diagnostics.push(error(
                program,
                "SPX-T205",
                format!(
                    "argument `{}` to `{name}` expects {}, received {}",
                    param.name, param.ty, value.ty
                ),
                arg.span,
            ));
        }
        crate::source_verify::arguments::check_argument_ownership(
            program,
            current,
            name,
            arg,
            param,
            actual.as_ref(),
            variables,
            types,
            allow_moves,
            false,
            false,
            diagnostics,
        );
    }
    crate::source_verify::arguments::release_borrowed_bytes_call_loans(variables, &loans);
    Some(CheckedValue::returned(result, own))
}

//! Test-only recursive `while` statement checking and the oracle form of the
//! `while` admission rules.

use crate::ast::program_source::ProgramSource;
use crate::ast::{Expr, ExprKind, Function, Span, Statement, Type};
#[cfg(test)]
use crate::diagnostic::Diagnostic;
use crate::source_verify::binding::Binding;
use crate::source_verify::diagnostics::{error, reject_native_unit_value};
use crate::source_verify::oracle::check_expr;
use crate::source_verify::type_table::TypeTable;
use std::collections::HashMap;

/// Recursive-oracle twin of the iterative verifier's `while` handling: the
/// contract-context rejection, the collect-all admission scan, the condition
/// typing check, ordinary body-block checking, and ownership-drift detection,
/// emitted in exactly the same diagnostic order.
#[cfg(test)]
#[allow(clippy::too_many_arguments)]
pub(super) fn check_while_statement(
    program: &dyn ProgramSource,
    current: &Function,
    condition: &Expr,
    body: &Expr,
    statement_span: Span,
    variables: &mut HashMap<String, Binding>,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    result_type: Option<&Type>,
    allow_moves: bool,
    diagnostics: &mut Vec<Diagnostic>,
) {
    if !allow_moves {
        diagnostics.push(error(
            program,
            "SPX-T253",
            "while statements are not allowed in contract expressions",
            condition.span,
        ));
    }
    let _ = reject_while_disallowed_oracle(program, condition, functions, types, diagnostics);
    if crate::finite_owned_record_loop::source(current, body).is_none() {
        let _ = reject_while_disallowed_oracle(program, body, functions, types, diagnostics);
    }
    let baseline = variables.clone();
    let condition_value = super::matching::in_loop(|| {
        check_expr(
            program,
            current,
            condition,
            variables,
            functions,
            types,
            result_type,
            allow_moves,
            diagnostics,
        )
    });
    if let Some(value) = condition_value {
        if value.native_unit {
            reject_native_unit_value(program, condition, &value, diagnostics);
        } else if value.ty != Type::Bool {
            diagnostics.push(error(
                program,
                "SPX-T251",
                "`while` condition must be bool",
                condition.span,
            ));
        }
    }
    let mut names = baseline.keys().collect::<Vec<_>>();
    names.sort();
    for name in names {
        let before = &baseline[name];
        if variables.get(name).is_none_or(|now| {
            now.availability != before.availability
                || now.moved_places != before.moved_places
                || now.definitely_partial != before.definitely_partial
        }) {
            diagnostics.push(error(
                program,
                "SPX-T252",
                format!("ownership of `{name}` changes inside a while condition"),
                condition.span,
            ));
        }
    }
    let body_value = super::matching::in_loop(|| {
        check_expr(
            program,
            current,
            body,
            variables,
            functions,
            types,
            result_type,
            allow_moves,
            diagnostics,
        )
    });
    if body_value.as_ref().is_some_and(|v| v.ty == Type::Never) && crate::ast::returns_only(body) {
        for (name, before) in &baseline {
            variables.insert(name.clone(), before.clone());
        }
    }
    for (name, before) in &baseline {
        let drifted = match variables.get(name) {
            Some(now) => {
                now.availability != before.availability
                    || now.moved_places != before.moved_places
                    || now.definitely_partial != before.definitely_partial
            }
            None => true,
        };
        if drifted {
            diagnostics.push(error(
                program,
                "SPX-T252",
                format!(
                    "ownership of `{name}` changes inside a while loop, which is not yet admitted"
                ),
                statement_span,
            ));
        }
    }
}

/// Collect-all admission scan used by the recursive oracle; mirrors
/// `IterativeVerifier::reject_while_disallowed` diagnostic for diagnostic.
#[cfg(test)]
pub(in crate::source_verify) fn reject_while_disallowed_oracle(
    program: &dyn ProgramSource,
    expression: &Expr,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    diagnostics: &mut Vec<Diagnostic>,
) -> Result<(), ()> {
    reject_with_scratch(program, expression, functions, types, diagnostics, None)
}
pub(in crate::source_verify) fn reject_finite_iterator_body_oracle(
    program: &dyn ProgramSource,
    current: &Function,
    expression: &Expr,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    diagnostics: &mut Vec<Diagnostic>,
) -> Result<(), ()> {
    let scratch = crate::finite_byte_scratch::source(current, expression);
    reject_with_scratch(
        program,
        expression,
        functions,
        types,
        diagnostics,
        scratch.as_ref(),
    )
}
pub(in crate::source_verify) fn reject_with_scratch(
    program: &dyn ProgramSource,
    expression: &Expr,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    diagnostics: &mut Vec<Diagnostic>,
    scratch: Option<&crate::finite_byte_scratch::SourceScratch<'_>>,
) -> Result<(), ()> {
    match &expression.kind {
        ExprKind::LexicalExit { value, .. } => match value {
            Some(value) => {
                reject_with_scratch(program, value, functions, types, diagnostics, scratch)
            }
            None => Ok(()),
        },
        ExprKind::Closure { .. } => Ok(()),

        ExprKind::Int(_)
        | ExprKind::Int32(_)
        | ExprKind::Char(_)
        | ExprKind::Uint8(_)
        | ExprKind::Usize(_)
        | ExprKind::Float32(_)
        | ExprKind::Float64(_)
        | ExprKind::Bool(_)
        | ExprKind::Var(_) => Ok(()),
        ExprKind::ArrayU8(_) | ExprKind::RepeatArrayU8 { .. } => {
            diagnostics.push(error(
                program,
                "SPX-T252",
                "fixed-array literals are not admitted in bounded while bodies",
                expression.span,
            ));
            Err(())
        }
        ExprKind::SuperMethod { .. } => {
            diagnostics.push(error(
                program,
                "SPX-T252",
                "super method calls are not yet admitted in while bodies",
                expression.span,
            ));
            Err(())
        }
        // Owned String Loops v1: a literal allocates one owned String in the
        // per-iteration body region.
        ExprKind::String(_) => Ok(()),
        ExprKind::BorrowedUtf8Literal(text) => {
            match crate::source_verify::static_text::checked(program, expression.span, text) {
                Ok(_) => Ok(()),
                Err(error) => {
                    diagnostics.push(error);
                    Err(())
                }
            }
        }
        ExprKind::VecConstructor { value, .. } | ExprKind::Unary { value, .. } => {
            reject_with_scratch(program, value, functions, types, diagnostics, scratch)
        }
        ExprKind::Binary { left, right, .. } => {
            let left = reject_with_scratch(program, left, functions, types, diagnostics, scratch);
            let right = reject_with_scratch(program, right, functions, types, diagnostics, scratch);
            left.and(right)
        }
        ExprKind::If {
            condition,
            then_branch,
            else_branch,
        } => {
            let condition =
                reject_with_scratch(program, condition, functions, types, diagnostics, scratch);
            let then =
                reject_with_scratch(program, then_branch, functions, types, diagnostics, scratch);
            let else_branch =
                reject_with_scratch(program, else_branch, functions, types, diagnostics, scratch);
            condition.and(then).and(else_branch)
        }
        ExprKind::Block { statements, tail } => {
            let mut result = Ok(());
            for statement in statements {
                result = reject_statement_with_scratch(
                    program,
                    statement,
                    functions,
                    types,
                    diagnostics,
                    scratch,
                );
                result?;
            }
            result.and(reject_with_scratch(
                program,
                tail,
                functions,
                types,
                diagnostics,
                scratch,
            ))
        }
        ExprKind::Call {
            type_arguments,
            args,
            name,
            ..
        } => {
            let vec_operation = crate::vec_ops::by_name(name);
            if !type_arguments.is_empty()
                && vec_operation.is_none()
                && name != crate::vec_field::NAME
                && crate::map_ops::by_generic_name(name, type_arguments).is_none()
            {
                diagnostics.push(error(
                    program,
                    "SPX-T252",
                    "generic calls are not yet admitted in while bodies",
                    expression.span,
                ));
                return Err(());
            }
            if let Some(operation) = vec_operation {
                if !operation.admitted_in_while()
                    || (if operation == crate::vec_ops::VecOp::StrAt {
                        !crate::source_verify::string_slot::while_shape(type_arguments, args)
                    } else {
                        type_arguments.len() != 1
                    || !(crate::vec_ops::ast_element_is_admitted(&type_arguments[0])
                                || crate::source_verify::declared_type::copy_record_collection::source_admitted(program, &type_arguments[0]) || crate::source_verify::declared_type::owned_leaf_collection::source_admitted(program, &type_arguments[0]))
                    })
                    || args.len() != operation.arity()
                {
                    #[cfg(test)]
                    crate::source_verify::string_slot::trace_while_refusal(
                        "oracle",
                        operation,
                        type_arguments,
                        args,
                    );
                    diagnostics.push(error(
                        program,
                        "SPX-T283",
                        "only exact typed scalar Vec update/read operations are admitted in while bodies",
                        expression.span,
                    ));
                    return Err(());
                }
            }
            if crate::command_io_ops::by_name(name)
                .is_some_and(|operation| !crate::command_io_ops::admitted_in_while(operation))
            {
                diagnostics.push(error(
                    program,
                    "SPX-T270",
                    format!("command I/O operation `{name}` is not admitted in while bodies"),
                    expression.span,
                ));
                return Err(());
            }
            if crate::command_io_ops::by_name(name)
                .is_some_and(|operation| args.len() != crate::command_io_ops::arity(operation))
            {
                diagnostics.push(error(
                    program,
                    "SPX-T270",
                    format!("invalid command I/O operation `{name}` call shape"),
                    expression.span,
                ));
                return Err(());
            }
            if let Some(operation) = crate::byte_ops::by_name(name) {
                if (!operation.admitted_in_while()
                    && !scratch.is_some_and(|proof| proof.permits(expression)))
                    || args.len() != operation.arity()
                {
                    diagnostics.push(error(
                        program,
                        "SPX-T252",
                        format!(
                            "byte operation `{name}` is not admitted in while bodies; only exact byte_len, byte_get and byte_range reads and the loop-carried bytes_set fill qualify"
                        ),
                        expression.span,
                    ));
                    return Err(());
                }
            }
            if let Some(declared) = functions.get(name.as_str()) {
                let scalar_signature = crate::loop_calls::byte_writer::source_target(program, declared)
                    || crate::stdin_stream_ops::ast_forward_signature(declared)
                    || (crate::loop_calls::effects_admitted(&declared.effects)
                        && crate::loop_calls::ast_result_admitted(program, &declared.return_type)
                        && declared.params.iter().zip(args).all(|(param, argument)| {
                            crate::loop_calls::ast_param_admitted(program, param.mode, &param.ty)
                                || (param.mode == crate::ast::ParamMode::Borrow
                                    && crate::source_verify::declared_type::owned_record_collection::is_owner_renewal_record(
                                        types,
                                        &param.ty,
                                    ))
                                || (param.mode == crate::ast::ParamMode::Own
                                    && matches!(&argument.kind, ExprKind::Var(argument_name)
                                    if super::matching::is_owned_iterator_item(
                                        argument_name,
                                        &param.ty,
                                    )))
                        }));
                if !scalar_signature {
                    diagnostics.push(error(
                        program,
                        "SPX-T252",
                        format!(
                            "call `{name}` is not admitted in loop bodies; use scalar/text signatures with read-only input effects. For output, build one string in the loop and write it once afterwards"
                        ),
                        expression.span,
                    ));
                    return Err(());
                }
            }
            let mut result = Ok(());
            for argument in args {
                result =
                    reject_with_scratch(program, argument, functions, types, diagnostics, scratch);
                result?;
            }
            result
        }
        ExprKind::MethodCall { .. } => {
            diagnostics.push(error(
                program,
                "SPX-T252",
                "method calls are not yet admitted in while bodies",
                expression.span,
            ));
            Err(())
        }
        ExprKind::Project { base, .. } => {
            reject_with_scratch(program, base, functions, types, diagnostics, scratch)
        }
        ExprKind::ConstructRecord {
            type_name,
            type_arguments,
            fields,
            ..
        } => {
            let ty = Type::Named {
                name: type_name.clone(),
                arguments: type_arguments.clone(),
            };
            if crate::source_verify::declared_type::owned_leaf_collection::copy_or_leaf_admitted(
                types, &ty,
            ) {
                let mut result = Ok(());
                for field in fields {
                    if reject_with_scratch(
                        program,
                        &field.value,
                        functions,
                        types,
                        diagnostics,
                        scratch,
                    )
                    .is_err()
                    {
                        result = Err(());
                    }
                }
                result
            } else {
                diagnostics.push(error(
                    program,
                    "SPX-T252",
                    "record construction is not yet admitted in while bodies",
                    expression.span,
                ));
                Err(())
            }
        }
        ExprKind::ConstructVariant {
            type_name,
            type_arguments,
            fields,
            ..
        } => {
            let ty = Type::Named {
                name: type_name.clone(),
                arguments: type_arguments.clone(),
            };
            if !crate::source_verify::variant_guards::copy_variant(types, &ty) {
                diagnostics.push(error(
                    program,
                    "SPX-T252",
                    "variant construction in a loop requires only Copy scalar payloads",
                    expression.span,
                ));
                return Err(());
            }
            for field in fields {
                reject_with_scratch(
                    program,
                    &field.value,
                    functions,
                    types,
                    diagnostics,
                    scratch,
                )?;
            }
            Ok(())
        }
        ExprKind::UpdateRecord { .. } => {
            diagnostics.push(error(
                program,
                "SPX-T252",
                "record updates are not yet admitted in while bodies",
                expression.span,
            ));
            Err(())
        }
        // Owned String Loops v2: the typed scrutinee rule lives in the
        // match checker; the admission scan visits every operand.
        ExprKind::Match {
            scrutinee, arms, ..
        } => {
            reject_with_scratch(program, scrutinee, functions, types, diagnostics, scratch)?;
            let mut result = Ok(());
            for arm in arms {
                result = match &arm.guard {
                    Some(guard) => {
                        let guard = reject_with_scratch(
                            program,
                            guard,
                            functions,
                            types,
                            diagnostics,
                            scratch,
                        );
                        let value = reject_with_scratch(
                            program,
                            &arm.value,
                            functions,
                            types,
                            diagnostics,
                            scratch,
                        );
                        guard.and(value)
                    }
                    None => reject_with_scratch(
                        program,
                        &arm.value,
                        functions,
                        types,
                        diagnostics,
                        scratch,
                    ),
                };
                result?;
            }
            result
        }
        ExprKind::Try { .. } => {
            diagnostics.push(error(
                program,
                "SPX-T252",
                "postfix `?` propagation is not yet admitted in while bodies",
                expression.span,
            ));
            Err(())
        }
        // Resumable Effects control profile (issue #296): the parser admits a
        // direct statement-value `yield`; its request is an ordinary operand.
        ExprKind::Yield { request } => {
            reject_with_scratch(program, request, functions, types, diagnostics, scratch)
        }
    }
}

#[cfg(test)]
pub(super) fn reject_statement_with_scratch(
    program: &dyn ProgramSource,
    statement: &Statement,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    diagnostics: &mut Vec<Diagnostic>,
    scratch: Option<&crate::finite_byte_scratch::SourceScratch<'_>>,
) -> Result<(), ()> {
    match statement {
        Statement::Assign {
            name,
            field: None,
            value,
            ..
        } if source_record_owner_renewal(program, functions, name, value) => {
            let ExprKind::Call { args, .. } = &value.kind else {
                unreachable!("record renewal admission requires a call")
            };
            let mut result = Ok(());
            for argument in args {
                result =
                    reject_with_scratch(program, argument, functions, types, diagnostics, scratch);
                result?;
            }
            result
        }
        Statement::Let { value, .. } | Statement::Assign { value, .. } => {
            reject_with_scratch(program, value, functions, types, diagnostics, scratch)
        }
        Statement::Unsafe { span, .. } => {
            diagnostics.push(error(
                program,
                "SPX-T252",
                "unsafe boundary statements are not yet admitted in while bodies",
                *span,
            ));
            Err(())
        }
        Statement::While {
            condition, body, ..
        } => {
            let condition =
                reject_with_scratch(program, condition, functions, types, diagnostics, scratch);
            let body = reject_with_scratch(program, body, functions, types, diagnostics, scratch);
            condition.and(body)
        }
        Statement::For { span, .. }
        | Statement::ForBorrow { span, .. }
        | Statement::ForOwn { span, .. } => {
            diagnostics.push(error(
                program,
                "SPX-T284",
                "nested for traversal is not admitted in this bounded profile",
                *span,
            ));
            Err(())
        }
    }
}

#[cfg(test)]
fn source_record_owner_renewal(
    program: &dyn ProgramSource,
    functions: &HashMap<&str, &Function>,
    binding: &str,
    value: &Expr,
) -> bool {
    if crate::loop_calls::byte_writer::source_assignment(program, binding, value) {
        return true;
    }
    let ExprKind::Call {
        name,
        type_arguments,
        args,
        ..
    } = &value.kind
    else {
        return false;
    };
    let Some(target) = functions.get(name.as_str()) else {
        return false;
    };
    let types = TypeTable::new(program);
    type_arguments.is_empty()
        && target.type_parameters.is_empty()
        && target.effects.is_empty()
        && crate::source_verify::declared_type::owned_record_collection::is_owner_renewal_record(
            &types,
            &target.return_type,
        )
        && target.params.len() == args.len()
        && target
            .params
            .iter()
            .zip(args)
            .filter(|(parameter, argument)| {
                parameter.mode == crate::ast::ParamMode::Own
                    && parameter.ty == target.return_type
                    && matches!(&argument.kind, ExprKind::Var(name) if name == binding)
            })
            .count()
            == 1
        && target.params.iter().zip(args).all(|(parameter, argument)| {
            match parameter.mode {
                crate::ast::ParamMode::Own => {
                    parameter.ty == target.return_type
                        && matches!(&argument.kind, ExprKind::Var(name) if name == binding)
                }
                crate::ast::ParamMode::Borrow => {
                    (crate::source_verify::declared_type::owned_record_collection::
                        is_owner_renewal_record(&types, &parameter.ty)
                        || crate::loop_calls::ast_renewal_view(&parameter.ty))
                        && matches!(argument.kind, ExprKind::Var(_))
                }
                crate::ast::ParamMode::Value => true,
                crate::ast::ParamMode::Shared => false,
            }
        })
}
